const Salterio = (() => {
  const PSALMOS = {"1":[{"r":"","t":"Dichoso el hombre\nque no sigue el consejo de los impíos,\nni entra por la senda de los pecadores,\nni se sienta en la reunión de los cínicos;\nsino que su gozo es la ley del Señor,\ny medita su ley día y noche.\n\nSerá como un árbol \nplantado al borde de la acequia:\nda fruto en su sazón\ny no se marchitan sus hojas;\ny cuanto emprende tiene buen fin.\n\nNo así los impíos, no así;\nserán paja que arrebata el viento.\nEn el juicio los impíos no se levantarán,\nni los pecadores en la asamblea de los justos;\nporque el Señor protege el camino de los justos,\npero el camino de los impíos acaba mal.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"2":[{"r":"","t":"¿Por qué se amotinan las naciones,\ny los pueblos planean un fracaso?\n\nSe alían los reyes de la tierra, \nlos príncipes conspiran\ncontra el Señor y contra su Mesías:\n«Rompamos sus coyundas,\nsacudamos su yugo.»\n\nEl que habita en el cielo sonríe,\nel Señor se burla de ellos.\nLuego les habla con ira,\nlos espanta con su cólera:\n«Yo mismo he establecido a mi rey\nen Sion, mi monte santo.»\n\nVoy a proclamar el decreto del Señor;\nél me ha dicho:\n«Tú eres mi hijo:\nyo te he engendrado hoy.\nPídemelo: te daré en herencia las naciones,\nen posesión, los confines de la tierra:\nlos gobernarás con cetro de hierro,\nlos quebrarás como jarro de loza.»\n\nY ahora, reyes, sed sensatos;\nescarmentad, los que regís la tierra:\nservid al Señor con temor,\nrendidle homenaje temblando;\nno sea que se irrite, y vayáis a la ruina,\nporque se inflama de pronto su ira.\n¡Dichosos los que se refugian en Él!\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"3":[{"r":"","t":"Señor, cuántos son mis enemigos,\ncuántos se levantan contra mí;\ncuántos dicen de mí:\n«Ya no lo protege Dios»\n\nPero tú, Señor, eres mi escudo y mi gloria,\ntú mantienes alta mi cabeza.\nSi grito invocando al Señor,\nél me escucha desde su monte santo.\n\nPuedo acostarme y dormir y despertar:\nel Señor me sostiene. \nNo temeré al pueblo innumerable\nque acampa a mi alrededor.\n\nLevántate, Señor;\nsálvame, Dios mío: \ntú golpeaste a mis enemigos en la mejilla,\nrompiste los dientes de los malvados.\n\nDe ti, Señor, viene la salvación\ny la bendición sobre tu pueblo.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"4":[{"r":"","t":"Escúchame cuando te invoco, Dios, defensor mío;\ntú que en el aprieto me diste anchura,\nten piedad de mí y escucha mi oración.\n\nY vosotros, ¿hasta cuándo ultrajaréis mi honor,\namaréis la falsedad y buscaréis el engaño?\nSabedlo: el Señor hizo milagros en mi favor,\ny el Señor me escuchará cuando lo invoque.\n\nTemblad y no pequéis,\nreflexionad en el silencio de vuestro lecho;\nofreced sacrificios legítimos\ny confiad en el Señor.\n\nHay muchos que dicen: \"¿Quién nos hará ver la dicha,\nsi la luz de tu rostro ha huido de nosotros?\"\n\nPero tú, Señor, has puesto en mi corazón más alegría\nque si abundara en trigo y en vino.\n\nEn paz me acuesto y en seguida me duermo,\nporque tú sólo, Señor, me haces vivir tranquilo.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Escúchame cuando te invoco, Dios, defensor mío;\ntú que en el aprieto me diste anchura,\nten piedad de mí y escucha mi oración.\n\nY vosotros, ¿hasta cuándo ultrajaréis mi honor,\namaréis la falsedad y buscaréis el engaño?\nSabedlo: el Señor hizo milagros en mi favor,\ny el Señor me escuchará cuando lo invoque.\n\nTemblad y no pequéis,\nreflexionad en el silencio de vuestro lecho;\nofreced sacrificios legítimos\ny confiad en el Señor.\n\nHay muchos que dicen: \"¿Quién nos hará ver la dicha,\nsi la luz de tu rostro ha huido de nosotros?\"\n\nPero tú, Señor, has puesto en mi corazón más alegría\nque si abundara en trigo y en vino.\n\nEn paz me acuesto y enseguida me duermo,\nporque tú sólo, Señor, me haces vivir tranquilo.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"5":[{"r":"2-10","t":"Señor, escucha mis palabras,\natiende a mis gemidos,\nhaz caso de mis gritos de auxilio,\nRey mío y Dios mío.\n\nA ti te suplico, Señor;\npor la mañana escucharás mi voz,\npor la mañana te expongo mi causa,\ny me quedo aguardando.\n\nTú no eres un Dios que ame la maldad,\nni el malvado es tu huésped,\nni el arrogante se mantiene en tu presencia.\n\nDetestas a los malhechores,\ndestruyes a los mentirosos;\nal hombre sanguinario y traicionero\nlo aborrece el Señor.\n\nPero yo, por tu gran bondad,\nentraré en tu casa,\nme postraré ante tu templo santo\ncon toda reverencia.\n\nSeñor, guíame con tu justicia,\nporque tengo enemigos;\nalláname tu camino.\n\nEn su boca no hay sinceridad,\nsu corazón es perverso;\nsu garganta es un sepulcro abierto,\nmientras halagan con la lengua.\n\nQue se alegren los que se acogen a ti, \ncon júbilo eterno;\nprotégelos, para que se llenen de gozo\nlos que aman tu nombre.\n\nPorque tú, Señor, bendices al justo,\ny como un escudo lo rodea tu favor.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"6":[{"r":"","t":"Señor, no me corrijas con ira,\nno me castigues con cólera.\nMisericordia, Señor, que desfallezco;\ncura, Señor, mis huesos dislocados.\nTengo el alma en delirio,\ny tú, Señor, ¿hasta cuándo?\n\nVuélvete, Señor, liberta mi alma,\nsálvame por tu misericordia.\nPorque en el reino de la muerte nadie te invoca,\ny en el abismo, ¿quién te alabará?\n\nEstoy agotado de gemir:\nde noche lloro sobre el lecho,\nriego mi cama con lágrimas.\nMis ojos se consumen irritados,\nenvejecen por tantas contradicciones.\n\nApartaos de mí, los malvados,\nporque el Señor ha escuchado mis sollozos;\nel Señor ha escuchado mi súplica, \nel Señor ha aceptado mi oración.\n\nQue la vergüenza abrume a mis enemigos,\nque avergonzados huyan al momento.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"7":[{"r":"","t":"Señor, Dios mío, a ti me acojo,\nlíbrame de mis perseguidores y sálvame,\nque no me atrapen como leones \ny me desgarren sin remedio.\n\nSeñor, Dios mío: si soy culpable,\nsi hay crímenes en mis manos,\nsi he causado daño a mi amigo,\nsi he protegido a un opresor injusto,\nque el enemigo me persiga y me alcance,\nque me pisotee vivo por tierra,\napretando mi vientre contra el polvo.\n\nLevántate, Señor, con tu ira,\nálzate contra el furor de mis adversarios,\nacude, Dios mío, a defenderme\nen el juicio que has convocado.\nQue te rodee la asamblea de las naciones,\ny pon tu asiento en lo más alto de ella.\nEl Señor es juez de los pueblos.\n\nJúzgame, Señor, según mi justicia,\nsegún la inocencia que hay en mí.\nCese la maldad de los culpables,\ny apoya tú al inocente,\ntú que sondeas el corazón y las entrañas,\ntú, el Dios justo.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Mi escudo es Dios,\nque salva a los rectos de corazón.\nDios es un juez justo,\nDios amenaza cada día:\nsi no se convierten, afilará su espada,\ntensará el arco y apuntará.\nApunta sus armas mortíferas,\nprepara sus flechas incendiarias.\n\nMirad: concibió el crimen, está preñado de maldad,\ny da a luz el engaño.\nCavó y ahondó una fosa,\ncaiga en la fosa que hizo,\nrecaiga su maldad sobre su cabeza,\nbaje su violencia sobre su cráneo.\n\nYo daré gracias al Señor por su justicia,\ntañendo para el nombre del Señor Altísimo.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"8":[{"r":"","t":"Señor, dueño nuestro, \n¡qué admirable es tu nombre\nen toda la tierra!\n\nEnsalzaste tu majestad sobre los cielos.\nDe la boca de los niños de pecho\nhas sacado una alabanza contra tus enemigos,\npara reprimir al adversario y al rebelde.\n\nCuando contemplo el cielo, obra de tus dedos,\nla luna y las estrellas que has creado,\n¿qué es el hombre, para que te acuerdes de él,\nel ser humano, para darle poder?\n\nLo hiciste poco inferior a los ángeles,\nlo coronaste de gloria y dignidad, \nle diste el mando sobre las obras de tus manos,\ntodo lo sometiste bajo sus pies:\n\nrebaños de ovejas y toros,\ny hasta las bestias del campo,\nlas aves del cielo, los peces del mar,\nque trazan sendas por el mar.\n\nSeñor, dueño nuestro, \n¡qué admirable es tu nombre\nen toda la tierra!\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"9":[{"r":"","t":"¿Por qué te quedas lejos, Señor,\ny te escondes en el momento del aprieto?\nLa soberbia del impío oprime al infeliz\ny lo enreda en las intrigas que ha tramado.\n\nEl malvado se gloría de su ambición,\nel codicioso blasfema y desprecia al Señor.\nEl malvado dice con insolencia:\n«No hay Dios que me pida cuentas.»\n\nLa intriga vicia siempre su conducta,\naleja de su mente tus juicios\ny desafía a sus rivales.\nPiensa: «No vacilaré,\nnunca jamás seré desgraciado.»\n\nSu boca está llena de maldiciones,\nde engaños y de fraudes;\nsu lengua encubre maldad y opresión;\nen el zaguán se sienta al acecho\npara matar a escondidas al inocente.\n\nSus ojos espían al pobre;\nacecha en su escondrijo como león en su guarida,\nacecha al desgraciado para robarle,\narrastrándolo a sus redes;\n\nse agacha y se encoge\ny con violencia cae sobre el indefenso.\nPiensa: «Dios lo olvida,\nse tapa la cara para no enterarse.»\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Levántate, Señor, extiende tu mano,\nno te olvides de los humildes;\n¿por qué ha de despreciar a Dios el malvado,\npensando que no le pedirá cuentas?\n\nPero tú ves las penas y los trabajos,\ntú miras y los tomas en tus manos.\nA ti se encomienda el pobre,\ntú socorres al huérfano.\n\nRómpele el brazo al malvado,\npídele cuentas de su maldad, y que desaparezca.\nEl Señor reinará eternamente\ny los gentiles desaparecerán de su tierra.\n\nSeñor, tú escuchas los deseos de los humildes,\nles prestas oído y los animas;\ntú defiendes al huérfano y al desvalido:\nque el hombre hecho de tierra\nno vuelva a sembrar su terror.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Te doy gracias, Señor, de todo corazón,\nproclamando todas tus maravillas;\nme alegro y exulto contigo, \ny toco en honor de tu nombre, oh Altísimo.\n\nPorque mis enemigos retrocedieron,\ncayeron y perecieron ante tu rostro.\nDefendiste mi causa y mi derecho,\nsentado en tu trono como juez justo.\n\nReprendiste a los pueblos, destruiste al impío\ny borraste para siempre su apellido.\nEl enemigo acabó en ruina perpetua,\narrasaste sus ciudades y se perdió su nombre.\n\nDios está sentado por siempre\nen el trono que ha colocado para juzgar.\nÉl juzgará el orbe con justicia\ny regirá las naciones con rectitud.\n\nÉl será refugio del oprimido,\nsu refugio en los momentos de peligro.\nConfiarán en ti los que conocen tu nombre,\nporque no abandonas a los que te buscan.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Tañed en honor del Señor, que reside en Sion;\nnarrad sus hazañas a los pueblos;\nél venga la sangre, él recuerda \ny no olvida los gritos de los humildes.\n\nPiedad, Señor; mira cómo me afligen mis enemigos;\nlevántame del umbral de la muerte, \npara que pueda proclamar tus alabanzas\ny gozar de tu salvación en las puertas de Sion.\n\nLos pueblos se han hundido en la fosa que hicieron,\nsu pie quedó prendido en la red que escondieron.\nEl Señor apareció para hacer justicia,\ny se enredó el malvado en sus propias acciones.\n\nVuelvan al abismo los malvados,\nlos pueblos que olvidan a Dios.\nÉl no olvida jamás al pobre,\nni la esperanza del humilde perecerá.\n\nLevántate, Señor, que el hombre no triunfe:\nsean juzgados los gentiles en tu presencia.\nSeñor, infúndeles terror, \ny aprendan los pueblos que no son más que hombres.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"10":[{"r":"","t":"Al Señor me acojo, ¿por qué me decís:\n\"Escapa como un pájaro al monte,\nporque los malvados tensan el arco,\najustan las saetas a la cuerda,\npara disparar en la sombra contra los buenos?\nCuando fallan los cimientos,\n¿qué podrá hacer el justo?\"\n\nPero el Señor está en su templo santo,\nel Señor tiene su trono en el cielo;\nsus ojos están observando,\nsus pupilas examinan a los hombres.\n\nEl Señor examina a inocentes y culpables,\ny al que ama la violencia él lo odia.\nHará llover sobre los malvados ascuas y azufre,\nles tocará en suerte un viento huracanado.\n\nPorque el Señor es justo y ama la justicia:\nlos buenos verán su rostro.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"11":[{"r":"","t":"Sálvanos, Señor, que se acaban los buenos, \nque desaparece la lealtad entre los hombres:\nno hacen más que mentir a su prójimo,\nhablan con labios embusteros\ny con doblez de corazón.\n\nExtirpe el Señor los labios embusteros\ny la lengua fanfarrona\nde los que dicen: «la lengua es nuestra fuerza,\nnuestros labios nos defienden,\n¿quién será nuestro amo?»\n\nEl Señor responde: «Por la opresión del humilde,\npor el gemido del pobre, yo me levantaré,\ny pondré a salvo al que lo ansía.»\n\nLas palabras del Señor son palabras auténticas,\ncomo plata limpia de ganga,\nrefinada siete veces.\n\nTú nos guardarás, Señor,\nnos librarás para siempre de esa gente:\nde los malvados que merodean\npara chupar como sanguijuelas sangre humana.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"12":[{"r":"","t":"¿Hasta cuándo, Señor, seguirás olvidándome?\n¿Hasta cuándo me esconderás tu rostro?\n¿Hasta cuándo he de estar preocupado,\ncon el corazón apenado todo el día?\n¿Hasta cuándo va a triunfar mi enemigo?\n\nAtiende y respóndeme, Señor, Dios mío;\nda luz a mis ojos\npara que no me duerma en la muerte,\npara que no diga mi enemigo: «le he podido»,\nni se alegre mi adversario de mi fracaso.\n\nPorque yo confío en tu misericordia:\nalegra mi corazón con tu auxilio,\ny cantaré al Señor por el bien que me ha hecho.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"13":[{"r":"","t":"Dice el necio para sí:\n«No hay Dios.»\nSe han corrompido cometiendo execraciones,\nno hay quien obre bien.\n\nEl Señor observa desde el cielo\na los hijos de Adán, \npara ver si hay alguno sensato\nque busque a Dios.\n\nTodos se extravían\nigualmente obstinados,\nno hay uno que obre bien,\nni uno solo.\n\n-Pero ¿no aprenderán los malhechores,\nque devoran a mi pueblo como pan\ny no invocan al Señor?\n\nPues temblarán de espanto,\nporque Dios está con los justos.\nPodéis burlaros de los planes del desvalido,\npero el Señor es su refugio.\n\n¡Ojalá venga desde Sion \nla salvación de Israel!\nCuando el Señor cambie la suerte de su pueblo,\nse alegrará Jacob y gozará Israel.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"14":[{"r":"","t":"Señor, ¿quién puede hospedarse en tu tienda\ny habitar en tu monte santo?\n\nEl que procede honradamente \ny practica la justicia,\nel que tiene intenciones leales \ny no calumnia con su lengua,\n\nel que no hace mal a su prójimo\nni difama al vecino,\nel que considera despreciable al impío\ny honra a los que temen al Señor,\n\nel que no retracta lo que juró\naun en daño propio,\nel que no presta dinero a usura\nni acepta soborno contra el inocente.\n\nEl que así obra nunca fallará.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"15":[{"r":"","t":"Protégeme, Dios mío, que me refugio en ti;\nyo digo al Señor: «Tú eres mi bien.»\nLos dioses y señores de la tierra\nno me satisfacen.\n\nMultiplican las estatuas \nde dioses extraños;\nno derramaré sus libaciones con mis manos,\nni tomaré sus nombres en mis labios.\n\nEl Señor es el lote de mi heredad y mi copa;\nmi suerte está en tu mano:\nme ha tocado un lote hermoso,\nme encanta mi heredad.\n\nBendeciré al Señor, que me aconseja,\nhasta de noche me instruye internamente.\nTengo siempre presente al Señor,\ncon él a mi derecha no vacilaré.\n\nPor eso se me alegra el corazón,\nse gozan mis entrañas,\ny mi carne descansa serena.\nPorque no me entregarás a la muerte,\nni dejarás a tu fiel conocer la corrupción.\n\nMe enseñarás el sendero de la vida,\nme saciarás de gozo en tu presencia,\nde alegría perpetua a tu derecha.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"16":[{"r":"","t":"Señor, escucha mi apelación\natiende a mis clamores,\npresta oído a mi súplica,\nque en mis labios no hay engaño:\nemane de ti la sentencia,\nmiren tus ojos la rectitud.\n\nAunque sondees mi corazón,\nvisitándolo de noche,\naunque me pruebes al fuego,\nno encontrarás malicia en mí.\n\nMi boca no ha faltado\ncomo suelen los hombres;\nsegún tus mandatos, yo me he mantenido\nen la senda establecida.\nMis pies estuvieron firmes en tus caminos,\ny no vacilaron mis pasos.\n\nYo te invoco porque tú me respondes, Dios mío;\ninclina el oído y escucha mis palabras.\nMuestra las maravillas de tu misericordia,\ntú que salvas de los adversarios\na quien se refugia a tu derecha.\n\nGuárdame como a las niñas de tus ojos,\na la sombra de tus alas escóndeme\nde los malvados que me asaltan,\ndel enemigo mortal que me cerca.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Han cerrado sus entrañas\ny hablan con boca arrogante;\nya me rodean sus pasos,\nse hacen guiños para derribarme,\ncomo un león ávido de presa,\ncomo un cachorro agazapado en su escondrijo.\n\nLevántate, Señor, hazle frente, doblégalo,\nque tu espada me libre del malvado,\ny tu mano, Señor, de los mortales;\nmortales de este mundo:\nsea su lote esta vida;\nde tu despensa les llenarás el vientre,\nse saciarán sus hijos\ny dejarán a sus pequeños lo que sobra.\n\nPero yo con mi apelación vengo a tu presencia,\ny al despertar me saciaré de tu semblante.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Señor, escucha mi apelación\natiende a mis clamores,\npresta oído a mi súplica,\nque en mis labios no hay engaño:\nemane de ti la sentencia,\nmiren tus ojos la rectitud.\n\nAunque sondees mi corazón,\nvisitándolo de noche,\naunque me pruebes al fuego,\nno encontrarás malicia en mí.\n\nMi boca no ha faltado\ncomo suelen los hombres;\nsegún tus mandatos, yo me he mantenido\nen la senda establecida.\nMis pies estuvieron firmes en tus caminos,\ny no vacilaron mis pasos.\n\nYo te invoco porque tú me respondes, Dios mío;\ninclina el oído y escucha mis palabras.\nMuestra las maravillas de tu misericordia,\ntú que salvas de los adversarios\na quien se refugia a tu derecha.\n\nGuárdame como a las niñas de tus ojos,\na la sombra de tus alas escóndeme\nde los malvados que me asaltan,\ndel enemigo mortal que me cerca.\n\nHan cerrado sus entrañas\ny hablan con boca arrogante;\nya me rodean sus pasos,\nse hacen guiños para derribarme,\ncomo un león ávido de presa,\ncomo un cachorro agazapado en su escondrijo.\n\nLevántate, Señor, hazle frente, doblégalo,\nque tu espada me libre del malvado,\ny tu mano, Señor, de los mortales;\nmortales de este mundo:\nsea su lote esta vida;\nde tu despensa les llenarás el vientre,\nse saciarán sus hijos\ny dejarán a sus pequeños lo que sobra.\n\nPero yo con mi apelación vengo a tu presencia,\ny al despertar me saciaré de tu semblante.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"17":[{"r":"31-51-","t":"Perfecto es el camino de Dios,\nacendrada es la promesa del Señor;\nÉl es escudo para los que a él se acogen.\n\n¿Quién es dios fuera del Señor?\n¿Qué roca hay fuera de nuestro Dios?\nDios me ciñe de valor \ny me enseña un camino perfecto;\n\nÉl me da pies de ciervo,\ny me coloca en las alturas;\nÉl adiestra mis manos para la guerra,\ny mis brazos para tensar la ballesta.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"2-30-","t":"Yo te amo, Señor; Tú eres mi fortaleza;\nSeñor, mi roca, mi alcázar, mi libertador.\nDios mío, peña mía, refugio mío, escudo mío,\nmi fuerza salvadora, mi baluarte.\nInvoco al Señor de mi alabanza\ny quedo libre de mis enemigos.\n\nMe cercaban olas mortales,\ntorrentes destructores me aterraban,\nme envolvían las redes del abismo,\nme alcanzaban los lazos de la muerte.\n\nEn el peligro invoqué al Señor,\ngrité a mi Dios:\ndesde su templo Él escuchó mi voz,\ny mi grito llegó a sus oídos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"18":[{"r":"","t":"El cielo proclama la gloria de Dios,\nel firmamento pregona la obra de sus manos:\nel día al día le pasa el mensaje,\nla noche a la noche se lo susurra.\n\nSin que hablen, sin que pronuncien,\nsin que resuene su voz,\na toda la tierra alcanza su pregón\ny hasta los límites del orbe su lenguaje.\n\nAllí le ha puesto su tienda al sol:\nél sale como el esposo de su alcoba,\ncontento como un héroe, a recorrer su camino.\n\nAsoma por un extremo del cielo,\ny su órbita llega al otro extremo:\nnada se libra de su calor.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"La ley del Señor es perfecta\ny es descanso del alma;\nel precepto del Señor es fiel\ne instruye al ignorante.\n\nLos mandatos del Señor son rectos\ny alegran el corazón;\nla norma del Señor es límpida\ny da luz a los ojos.\n\nLa voluntad del Señor es pura\ny eternamente estable;\nlos mandamientos del Señor son verdaderos\ny enteramente justos.\n\nMás preciosos que el oro,\nmás que el oro fino;\nmás dulces que la miel\nde un panal que destila.\n\nAunque tu siervo vigila\npara guardarlos con cuidado,\n¿quién conoce sus faltas?\nAbsuélveme de lo que se me oculta.\n\nPreserva a tu siervo de la arrogancia,\npara que no me domine:\nasí quedaré libre e inocente\ndel gran pecado.\n\nQue te agraden las palabras de mi boca,\ny llegue a tu presencia el meditar de mi corazón,\nSeñor, roca mía, redentor mío.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"19":[{"r":"","t":"Que te escuche el Señor el día del peligro,\nque te sostenga el nombre del Dios de Jacob;\nque te envíe auxilio desde el santuario,\nque te apoye desde el monte Sion.\n\nQue se acuerde de todas tus ofrendas,\nque le agraden tus sacrificios;\nque cumpla el deseo de tu corazón,\nque dé éxito a todos tus planes.\n\nQue podamos celebrar tu victoria\ny en el nombre de nuestro Dios alzar estandartes;\nque el Señor te conceda todo lo que pides.\n\nAhora reconozco que el Señor\nda la victoria a su Ungido,\nque lo ha escuchado desde su santo cielo,\ncon los prodigios de su mano victoriosa.\n\nUnos confían en sus carros,\notros en su caballería;\nnosotros invocamos el nombre\ndel Señor, Dios nuestro.\n\nEllos cayeron derribados,\nnosotros nos mantenemos en pie.\n\nSeñor, da la victoria al rey\ny escúchanos cuando te invocamos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"20":[{"r":"2-8","t":"Señor, el rey se alegra por tu fuerza,\n¡y cuánto goza con tu victoria!\nLe has concedido el deseo de su corazón,\nno le has negado lo que pedían sus labios.\n\nTe adelantaste a bendecirlo con el éxito,\ny has puesto en su cabeza una corona de oro fino.\nTe pidió vida, y se la has concedido,\naños que se prolongan sin término.\n\nTu victoria ha engrandecido su fama,\nlo has vestido de honor y majestad.\nLe concedes bendiciones incesantes,\nlo colmas de gozo en tu presencia;\nporque el rey confía en el Señor,\ny con la gracia del Altísimo no fracasará.\n\nLevántate, Señor, con tu fuerza,\ny al son de instrumentos cantaremos tu poder.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"21":[{"r":"","t":"Dios mío, Dios mío, ¿por qué me has abandonado?\na pesar de mis gritos, mi oración no te alcanza.\n\nDios mío, de día te grito, y no respondes;\nde noche, y no me haces caso;\naunque tú habitas en el santuario,\nesperanza de Israel.\n\nEn ti confiaban nuestros padres;\nconfiaban, y los ponías a salvo;\na ti gritaban, y quedaban libres;\nen ti confiaban, y no los defraudaste.\n\nPero yo soy un gusano, no un hombre,\nvergüenza de la gente, desprecio del pueblo;\nal verme, se burlan de mí, \nhacen visajes, menean la cabeza:\n«Acudió al Señor, que lo ponga a salvo;\nque lo libre, si tanto lo quiere.»\n\nTú eres quien me sacó del vientre,\nme tenías confiado en los pechos de mi madre;\ndesde el seno pasé a tus manos,\ndesde el vientre materno tú eres mi Dios.\nNo te quedes lejos, que el peligro está cerca\ny nadie me socorre.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Me acorrala un tropel de novillos,\nme cercan toros de Basán;\nabren contra mí las fauces\nleones que descuartizan y rugen.\n\nEstoy como agua derramada,\ntengo los huesos descoyuntados;\nmi corazón, como cera,\nse derrite en mis entrañas;\n\nmi garganta está seca como una teja,\nla lengua se me pega al paladar;\nme aprietas contra el polvo de la muerte.\n\nMe acorrala una jauría de mastines,\nme cerca una banda de malhechores;\nme taladran las manos y los pies,\npuedo contar mis huesos.\n\nEllos me miran triunfantes,\nse reparten mi ropa,\nechan a suerte mi túnica.\n\nPero tú, Señor, no te quedes lejos;\nfuerza mía, ven corriendo a ayudarme.\nlíbrame a mí de la espada,\ny a mi única vida, de la garra del mastín;\nsálvame de las fauces del león;\na este pobre, de los cuernos del búfalo.\n\nContaré tu fama a mis hermanos,\nen medio de la asamblea te alabaré.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"III","t":"Fieles del Señor, alabadlo;\nlinaje de Jacob, glorificadlo;\ntemedlo, linaje de Israel.\n\nPorque no ha sentido desprecio ni repugnancia\nhacia el pobre desgraciado;\nno le ha escondido su rostro:\ncuando pidió auxilio le escuchó.\n\nÉl es mi alabanza en la gran asamblea,\ncumpliré mis votos delante de sus fieles.\nLos desvalidos comerán hasta saciarse,\nalabarán al Señor los que lo buscan:\nviva su corazón por siempre.\n\nLo recordarán y volverán al Señor\nhasta de los confines del orbe;\nen su presencia se postrarán\nlas familias de los pueblos.\n\nPorque del Señor es el reino,\nÉl gobierna a los pueblos.\nAnte él se postrarán las cenizas de la tumba,\nante él se inclinarán los que bajan al polvo.\n\nMe hará vivir para él, mi descendencia le servirá,\nhablarán del Señor a la generación futura,\ncontarán su justicia al pueblo que ha de nacer:\ntodo lo que hizo el Señor.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"2-23","t":"Dios mío, Dios mío, ¿por qué me has abandonado?\na pesar de mis gritos, mi oración no te alcanza.\n\nDios mío, de día te grito, y no respondes;\nde noche, y no me haces caso;\naunque tú habitas en el santuario,\nesperanza de Israel.\n\nEn ti confiaban nuestros padres;\nconfiaban, y los ponías a salvo;\na ti gritaban, y quedaban libres;\nen ti confiaban, y no los defraudaste.\n\nPero yo soy un gusano, no un hombre,\nvergüenza de la gente, desprecio del pueblo;\nal verme, se burlan de mí, \nhacen visajes, menean la cabeza:\n\"Acudió al Señor, que lo ponga a salvo;\nque lo libre, si tanto lo quiere.\"\n\nTú eres quien me sacó del vientre,\nme tenías confiado en los pechos de mi madre;\ndesde el seno pasé a tus manos,\ndesde el vientre materno tú eres mi Dios.\nNo te quedes lejos, que el peligro está cerca\ny nadie me socorre.\n\nMe acorrala un tropel de novillos,\nme cercan toros de Basán;\nabren contra mí las fauces\nleones que descuartizan y rugen.\n\nEstoy como agua derramada,\ntengo los huesos descoyuntados;\nmi corazón, como cera,\nse derrite en mis entrañas;\n\nmi garganta está seca como una teja,\nla lengua se me pega al paladar;\nme aprietas contra el polvo de la muerte.\n\nMe acorrala una jauría de mastines,\nme cerca una banda de malhechores;\nme taladran las manos y los pies,\npuedo contar mis huesos.\n\nEllos me miran triunfantes,\nse reparten mi ropa,\nechan a suerte mi túnica.\n\nPero tú, Señor, no te quedes lejos;\nfuerza mía, ven corriendo a ayudarme.\nlíbrame a mí de la espada,\ny a mi única vida, de la garra del mastín;\nsálvame de las fauces del león;\na este pobre, de los cuernos del búfalo.\n\nContaré tu fama a mis hermanos,\nen medio de la asamblea te alabaré.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"22":[{"r":"","t":"El Señor es mi pastor, nada me falta:\nen verdes praderas me hace recostar;\n\nme conduce hacia fuentes tranquilas\ny repara mis fuerzas;\nme guía por el sendero justo,\npor el honor de su nombre.\n\nAunque camine por cañadas oscuras,\nnada temo, porque tú vas conmigo:\ntu vara y tu cayado me sosiegan.\n\nPreparas una mesa ante mí,\nenfrente de mis enemigos;\nme unges la cabeza con perfume,\ny mi copa rebosa.\n\nTu bondad y tu misericordia me acompañan\ntodos los días de mi vida,\ny habitaré en la casa del Señor\npor años sin término.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"23":[{"r":"","t":"Del Señor es la tierra y cuanto la llena,\nel orbe y todos sus habitantes:\nÉl la fundó sobre los mares,\nÉl la afianzó sobre los ríos.\n Se repite la antífona- ¿Quién puede subir al monte del Señor?\n¿Quién puede estar en el recinto sacro?\nSe repite la antífona- El hombre de manos inocentes\ny puro corazón,\nque no confía en los ídolos\nni jura contra el prójimo en falso.\nEse recibirá la bendición del Señor,\nle hará justicia el Dios de salvación.\nSe repite la antífona- Este es el grupo que busca al Señor,\nque viene a tu presencia, Dios de Jacob.\nSe repite la antífona¡Portones!, alzad los dinteles,\nque se alcen las antiguas compuertas:\nva a entrar el Rey de la gloria.\nSe repite la antífona- ¿Quién es ese Rey de la gloria?\n- El Señor, héroe valeroso;\nel Señor, héroe de la guerra.\nSe repite la antífona¡Portones!, alzad los dinteles,\nque se alcen las antiguas compuertas:\nva a entrar el Rey de la gloria.\nSe repite la antífona- ¿Quién es ese Rey de la gloria?\n- El Señor, Dios de los ejércitos.\nÉl es el Rey de la gloria.\nSe repite la antífonaGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Del Señor es la tierra y cuanto la llena,\nel orbe y todos sus habitantes:\nél la fundó sobre los mares,\nél la afianzó sobre los ríos.\n\n- ¿Quién puede subir al monte del Señor?\n¿Quién puede estar en el recinto sacro?\n\n- El hombre de manos inocentes\ny puro corazón,\nque no confía en los ídolos\nni jura contra el prójimo en falso.\nÉse recibirá la bendición del Señor,\nle hará justicia el Dios de salvación.\n\n- Éste es el grupo que busca al Señor,\nque viene a tu presencia, Dios de Jacob.\n\n¡Portones!, alzad los dinteles,\nque se alcen las antiguas compuertas:\nva a entrar el Rey de la gloria.\n\n- ¿Quién es ese Rey de la gloria?\n- El Señor, héroe valeroso;\nel Señor, héroe de la guerra.\n\n¡Portones!, alzad los dinteles,\nque se alcen las antiguas compuertas:\nva a entrar el Rey de la gloria.\n\n- ¿Quién es ese Rey de la gloria?\n- El Señor, Dios de los ejércitos.\nÉl es el Rey de la gloria.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"24":[{"r":"","t":"A ti, Señor, levanto mi alma;\nDios mío, en ti confío, \nno quede yo defraudado,\nque no triunfen de mí mis enemigos;\npues los que esperan en ti no quedan defraudados,\nmientras que el fracaso malogra a los traidores.\n\nSeñor, enséñame tus caminos,\ninstrúyeme en tus sendas:\nhaz que camine con lealtad;\nenséñame, porque tú eres mi Dios y Salvador,\ny todo el día te estoy esperando.\n\nRecuerda, Señor, que tu ternura\ny tu misericordia son eternas; \nno te acuerdes de los pecados\nni de las maldades de mi juventud; \nacuérdate de mí con misericordia, \npor tu bondad, Señor.\n\nEl Señor es bueno y es recto,\ny enseña el camino a los pecadores; \nhace caminar a los humildes con rectitud, \nenseña su camino a los humildes. \n\nLas sendas del Señor son misericordia y lealtad \npara los que guardan su alianza y sus mandatos. \nPor el honor de tu nombre, Señor,\nperdona mis culpas, que son muchas.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"¿Hay alguien que tema al Señor? \nÉl le enseñará el camino escogido: \nsu alma vivirá feliz,\nsu descendencia poseerá la tierra.\n\nEl Señor se confía con sus fieles \ny les da a conocer su alianza.\nTengo los ojos puestos en el Señor, \nporque él saca mis pies de la red.\n\nMírame, oh Dios, y ten piedad de mí, \nque estoy solo y afligido. \nEnsancha mi corazón oprimido \ny sácame de mis tribulaciones.\n\nMira mis trabajos y mis penas\ny perdona todos mis pecados; \nmira cuántos son mis enemigos, \nque me detestan con odio cruel.\n\nGuarda mi vida y líbrame,\nno quede yo defraudado de haber acudido a ti.\nLa inocencia y la rectitud me protegerán, \nporque espero en ti.\n\nSalva, oh Dios, a Israel\nde todos sus peligros.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"25":[{"r":"","t":"Hazme justicia, Señor, que camino en la inocencia;\nconfiando en el Señor, no me he desviado.\n\nEscrútame, Señor, ponme a prueba,\nsondea mis entrañas y mi corazón, \nporque tengo ante los ojos tu bondad,\ny camino en tu verdad.\n\nNo me siento con gente falsa,\nno me junto con mentirosos;\ndetesto las bandas de malhechores,\nno tomo asiento con los impíos.\n\nLavo en la inocencia mis manos,\ny rodeo tu altar, Señor,\nproclamando tu alabanza,\nenumerando tus maravillas.\n\nSeñor, yo amo la belleza de tu casa,\nel lugar donde reside tu gloria.\n\nNo arrebates mi alma con los pecadores,\nni mi vida con los sanguinarios,\nque en su izquierda llevan infamias,\ny su derecha está llena de sobornos.\n\nYo, en cambio, camino en la integridad;\nsálvame, ten misericordia de mí.\nMi pie se mantiene en el camino llano;\nen la asamblea bendeciré al Señor.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"26":[{"r":"","t":"El Señor es mi luz y mi salvación,\n¿a quién temeré?\nEl Señor es la defensa de mi vida,\n¿quién me hará temblar?\n\nCuando me asaltan los malvados\npara devorar mi carne, \nellos, enemigos y adversarios,\ntropiezan y caen.\n\nSi un ejército acampa contra mí,\nmi corazón no tiembla;\nsi me declaran la guerra,\nme siento tranquilo.\n\nUna cosa pido al Señor,\neso buscaré:\nhabitar en la casa del Señor\npor los días de mi vida;\ngozar de la dulzura del Señor, \ncontemplando su templo.\n\nÉl me protegerá en su tienda\nel día del peligro;\nme esconderá en lo escondido de su morada,\nme alzará sobre la roca;\n\ny así levantaré la cabeza\nsobre el enemigo que me cerca;\nen su tienda ofreceré\nsacrificios de aclamación:\ncantaré y tocaré para el Señor.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Escúchame, Señor, que te llamo;\nten piedad, respóndeme.\n\nOigo en mi corazón: «Buscad mi rostro.»\nTu rostro buscaré, Señor,\nno me escondas tu rostro.\n\nNo rechaces con ira a tu siervo,\nque tú eres mi auxilio;\nno me deseches, no me abandones,\nDios de mi salvación.\n\nSi mi padre y mi madre me abandonan,\nel Señor me recogerá.\n\nSeñor, enséñame tu camino, \nguíame por la senda llana,\nporque tengo enemigos.\n\nNo me entregues a la saña de mi adversario,\nporque se levantan contra mí testigos falsos,\nque respiran violencia.\n\nEspero gozar de la dicha del Señor\nen el país de la vida.\n\nEspera en el Señor, sé valiente,\nten ánimo, espera en el Señor.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"El Señor es mi luz y mi salvación,\n¿a quién temeré?\nEl Señor es la defensa de mi vida,\n¿quién me hará temblar?\n\nCuando me asaltan los malvados\npara devorar mi carne, \nellos, enemigos y adversarios,\ntropiezan y caen.\n\nSi un ejército acampa contra mí,\nmi corazón no tiembla;\nsi me declaran la guerra,\nme siento tranquilo.\n\nUna cosa pido al Señor,\neso buscaré:\nhabitar en la casa del Señor\npor los días de mi vida;\ngozar de la dulzura del Señor, \ncontemplando su templo.\n\nÉl me protegerá en su tienda\nel día del peligro;\nme esconderá en lo escondido de su morada,\nme alzará sobre la roca;\n\ny así levantaré la cabeza\nsobre el enemigo que me cerca;\nen su tienda ofreceré\nsacrificios de aclamación:\ncantaré y tocaré para el Señor.\n\nEscúchame, Señor, que te llamo;\nten piedad, respóndeme.\n\nOigo en mi corazón: \"Buscad mi rostro.\"\nTu rostro buscaré, Señor,\nno me escondas tu rostro.\n\nNo rechaces con ira a tu siervo,\nque tú eres mi auxilio;\nno me deseches, no me abandones,\nDios de mi salvación.\n\nSi mi padre y mi madre me abandonan,\nel Señor me recogerá.\n\nSeñor, enséñame tu camino, \nguíame por la senda llana,\nporque tengo enemigos.\n\nNo me entregues a la saña de mi adversario,\nporque se levantan contra mí testigos falsos,\nque respiran violencia.\n\nEspero gozar de la dicha del Señor\nen el país de la vida.\n\nEspera en el Señor, sé valiente,\nten ánimo, espera en el Señor.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"27":[{"r":"1-3","t":"A ti, Señor, te invoco;\nRoca mía, no seas sordo a mi voz;\nque, si no me escuchas, seré igual\nque los que bajan a la fosa.\n\nEscucha mi voz suplicante\ncuando te pido auxilio,\ncuando alzo las manos\nhacia tu santuario.\n\nNo me arrebates con los malvados\nni con los malhechores,\nque hablan de paz con el prójimo,\npero llevan la maldad en el corazón.\n\nBendito el Señor, que escuchó\nmi voz suplicante;\nel Señor es mi fuerza y mi escudo:\nen él confía mi corazón;\nme socorrió, y mi corazón se alegra\ny le canta agradecido.\n\nEl Señor es fuerza para su pueblo,\napoyo y salvación para su Ungido.\nSalva a tu pueblo y bendice tu heredad,\nsé su pastor y llévalos siempre.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"28":[{"r":"","t":"Hijos de Dios, aclamad al Señor,\naclamad la gloria y el poder del Señor,\naclamad la gloria del nombre del Señor,\npostraos ante el Señor en el atrio sagrado.\n\nLa voz del Señor sobre las aguas,\nel Dios de la gloria ha tronado,\nel Señor sobre las aguas torrenciales.\n\nLa voz del Señor es potente,\nla voz del Señor es magnífica,\nla voz del Señor descuaja los cedros,\nel Señor descuaja los cedros del Líbano.\n\nHace brincar al Líbano como a un novillo,\nal Sarión como a una cría de búfalo.\nLa voz del Señor lanza llamas de fuego,\nla voz del Señor sacude el desierto,\nel Señor sacude el desierto de Cadés.\n\nLa voz del Señor retuerce los robles,\nel Señor descorteza las selvas.\nEn su templo un grito unánime: «¡Gloria!»\n\nEl Señor se sienta por encima del aguacero,\nel Señor se sienta como rey eterno.\nEl Señor da fuerza a su pueblo,\nEl Señor bendice a su pueblo con la paz.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"29":[{"r":"","t":"Te ensalzaré, Señor, porque me has librado\ny no has dejado que mis enemigos se rían de mí.\n\nSeñor, Dios mío, a ti grité,\ny tú me sanaste.\nSeñor, sacaste mi vida del abismo,\nme hiciste revivir cuando bajaba a la fosa.\n\nTañed para el Señor, fieles suyos,\ndad gracias a su nombre santo;\nsu cólera dura un instante;\nsu bondad, de por vida;\nal atardecer nos visita el llanto;\npor la mañana, el júbilo.\n\nYo pensaba muy seguro:\n«No vacilaré jamás.»\nTu bondad, Señor, me aseguraba\nel honor y la fuerza;\npero escondiste tu rostro,\ny quedé desconcertado.\n\nA ti, Señor, llamé,\nsupliqué a mi Dios:\n«¿Qué ganas con mi muerte,\ncon que yo baje a la fosa?\n\n¿Te va a dar gracias el polvo,\no va a proclamar tu lealtad?\nEscucha, Señor, y ten piedad de mí;\nSeñor, socórreme.»\n\nCambiaste mi luto en danzas,\nme desataste el sayal y me has vestido de fiesta;\nte cantará mi alma sin callarse.\nSeñor, Dios mío, te daré gracias por siempre.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"I","t":"Te ensalzaré, Señor, porque me has librado\ny no has dejado que mis enemigos se rían de mí.\n\nSeñor, Dios mío, a ti grité,\ny tú me sanaste.\nSeñor, sacaste mi vida del abismo,\nme hiciste revivir cuando bajaba a la fosa.\n\nTañed para el Señor, fieles suyos,\ndad gracias a su nombre santo;\nsu cólera dura un instante;\nsu bondad, de por vida;\nal atardecer nos visita el llanto;\npor la mañana, el júbilo.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Yo pensaba muy seguro:\n\"no vacilaré jamás.\"\nTu bondad, Señor, me aseguraba\nel honor y la fuerza;\npero escondiste tu rostro,\ny quedé desconcertado.\n\nA ti, Señor, llamé,\nsupliqué a mi Dios:\n\"¿Qué ganas con mi muerte,\ncon que yo baje a la fosa?\n\n¿Te va a dar gracias el polvo,\no va a proclamar tu lealtad?\nEscucha, Señor, y ten piedad de mí;\nSeñor, socórreme.\"\n\nCambiaste mi luto en danzas,\nme desataste el sayal y me has vestido de fiesta;\nte cantará mi alma sin callarse.\nSeñor, Dios mío, te daré gracias por siempre.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"30":[{"r":"2-6","t":"A ti, Señor, me acojo:\nno quede yo nunca defraudado;\ntú, que eres justo, ponme a salvo,\ninclina tu oído hacia mí;\n\nven aprisa a librarme,\nsé la roca de mi refugio,\nun baluarte donde me salve,\ntú que eres mi roca y mi baluarte;\n\npor tu nombre dirígeme y guíame:\nsácame de la red que me han tendido,\nporque tú eres mi amparo.\n\nA tus manos encomiendo mi espíritu:\nTú, el Dios leal, me librarás.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"2-17","t":"A ti, Señor, me acojo:\nno quede yo nunca defraudado;\ntú, que eres justo, ponme a salvo,\ninclina tu oído hacia mí;\n\nven aprisa a librarme,\nsé la roca de mi refugio,\nun baluarte donde me salve,\ntú que eres mi roca y mi baluarte;\n\npor tu nombre dirígeme y guíame:\nsácame de la red que me han tendido,\nporque tú eres mi amparo.\n\nA tus manos encomiendo mi espíritu:\nTú, el Dios leal, me librarás;\ntú aborreces a los que veneran ídolos inertes,\npero yo confío en el Señor;\ntu misericordia sea mi gozo y mi alegría.\n\nTe has fijado en mi aflicción,\nvelas por mi vida en peligro;\nno me has entregado en manos del enemigo,\nhas puesto mis pies en un camino ancho.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"31":[{"r":"","t":"Dichoso el que está absuelto de su culpa,\na quien le han sepultado su pecado;\ndichoso el hombre a quien el Señor\nno le apunta el delito.\n\nMientras callé se consumían mis huesos,\nrugiendo todo el día,\nporque día y noche tu mano\npesaba sobre mí;\nmi savia se me había vuelto un fruto seco.\n\nHabía pecado, lo reconocí,\nno te encubrí mi delito;\npropuse: «Confesaré al Señor mi culpa»,\ny tú perdonaste mi culpa y mi pecado.\n\nPor eso, que todo fiel te suplique\nen el momento de la desgracia:\nla crecida de las aguas caudalosas\nno lo alcanzará.\n\nTú eres mi refugio, me libras del peligro,\nme rodeas de cantos de liberación.\n\n- Te instruiré y te enseñaré el camino que has de seguir,\nfijaré en ti mis ojos.\n\nNo seáis irracionales como caballos y mulos,\ncuyo brío hay que domar con freno y brida;\nsi no, no puedes acercarte.\n\nLos malvados sufren muchas penas;\nal que confía en el Señor,\nla misericordia lo rodea.\n\nAlegraos, justos, y gozad con el Señor;\naclamadlo, los de corazón sincero.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"32":[{"r":"","t":"Aclamad, justos, al Señor,\nque merece la alabanza de los buenos.\n\nDad gracias al Señor con la cítara,\ntocad en su honor el arpa de diez cuerdas;\ncantadle un cántico nuevo,\nacompañando los vítores con bordones:\n\nque la palabra del Señor es sincera,\ny todas sus acciones son leales;\nél ama la justicia y el derecho,\ny su misericordia llena la tierra.\n\nLa palabra del Señor hizo el cielo;\nel aliento de su boca, sus ejércitos;\nencierra en un odre las aguas marinas,\nmete en un depósito el océano.\n\nTema al Señor la tierra entera,\ntiemblen ante él los habitantes del orbe:\nporque él lo dijo, y existió,\nél lo mandó, y surgió.\n\nEl Señor deshace los planes de las naciones,\nfrustra los proyectos de los pueblos;\npero el plan del Señor subsiste por siempre,\nlos proyectos de su corazón, de edad en edad.\n\nDichosa la nación cuyo Dios es el Señor,\nel pueblo que él se escogió como heredad.\n\nEl Señor mira desde el cielo, \nse fija en todos los hombres;\ndesde su morada observa\na todos los habitantes de la tierra:\nél modeló cada corazón,\ny comprende todas sus acciones.\n\nNo vence el rey por su gran ejército,\nno escapa el soldado por su mucha fuerza,\nnada valen sus caballos para la victoria,\nni por su gran ejército se salva.\n\nLos ojos del Señor están puestos en sus fieles, \nen los que esperan en su misericordia,\npara librar sus vidas de la muerte\ny reanimarlos en tiempo de hambre.\n\nNosotros aguardamos al Señor:\nél es nuestro auxilio y escudo;\ncon él se alegra nuestro corazón,\nen su santo nombre confiamos.\n\nQue tu misericordia, Señor, venga sobre nosotros,\ncomo lo esperamos de ti.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Aclamad, justos, al Señor,\nque merece la alabanza de los buenos.\n\nDad gracias al Señor con la cítara,\ntocad en su honor el arpa de diez cuerdas;\ncantadle un cántico nuevo,\nacompañando los vítores con bordones:\n\nque la palabra del Señor es sincera,\ny todas sus acciones son leales;\nél ama la justicia y el derecho,\ny su misericordia llena la tierra.\n\nLa palabra del Señor hizo el cielo;\nel aliento de su boca, sus ejércitos;\nencierra en un odre las aguas marinas,\nmete en un depósito el océano.\n\nTema al Señor la tierra entera,\ntiemblen ante él los habitantes del orbe:\nporque él lo dijo, y existió,\nél lo mandó y surgió.\n\nEl Señor deshace los planes de las naciones,\nfrustra los proyectos de los pueblos;\npero el plan del Señor subsiste por siempre,\nlos proyectos de su corazón, de edad en edad.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Dichosa la nación cuyo Dios es el Señor,\nel pueblo que él se escogió como heredad.\n\nEl Señor mira desde el cielo, \nse fija en todos los hombres;\nDesde su morada observa\na todos los habitantes de la tierra:\nél modeló cada corazón,\ny comprende todas sus acciones.\n\nNo vence el rey por su gran ejército,\nno escapa el soldado por su mucha fuerza,\nnada valen sus caballos para la victoria,\nni por su gran ejército se salva.\n\nLos ojos del Señor están puestos en sus fieles, \nen los que esperan en su misericordia,\npara librar sus vidas de la muerte\ny reanimarlos en tiempo de hambre.\n\nNosotros aguardamos al Señor:\nél es nuestro auxilio y escudo;\ncon él se alegra nuestro corazón,\nen su santo nombre confiamos.\n\nQue tu misericordia, Señor, venga sobre nosotros,\ncomo lo esperamos de ti.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"33":[{"r":"","t":"Bendigo al Señor en todo momento,\nsu alabanza está siempre en mi boca;\nmi alma se gloría en el Señor:\nque los humildes lo escuchen \ny se alegren.\n\nProclamad conmigo la grandeza del Señor,\nensalcemos juntos su nombre.\nYo consulté al Señor, y me respondió,\nme libró de todas mis ansias.\n\nContempladlo, y quedaréis radiantes,\nvuestro rostro no se avergonzará.\nSi el afligido invoca al Señor, él lo escucha\ny lo salva de sus angustias.\n\nEl ángel del Señor acampa \nen torno a sus fieles y los protege.\nGustad y ved qué bueno es el Señor,\ndichoso el que se acoge a él.\n\nTodos sus santos, temed al Señor,\nporque nada les falta a los que le temen;\nlos ricos empobrecen y pasan hambre,\nlos que buscan al Señor no carecen de nada.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Venid, hijos, escuchadme: \nos instruiré en el temor del Señor;\n¿Hay alguien que ame la vida\ny desee días de prosperidad?\n\nGuarda tu lengua del mal,\ntus labios de la falsedad;\napártate del mal, obra el bien,\nbusca la paz y corre tras ella.\n\nLos ojos del Señor miran a los justos,\nsus oídos escuchan sus gritos;\npero el Señor se enfrenta con los malhechores,\npara borrar de la tierra su memoria.\n\nCuando uno grita, el Señor lo escucha\ny lo libra de sus angustias;\nel Señor está cerca de los atribulados,\nsalva a los abatidos.\n\nAunque el justo sufra muchos males,\nde todos lo libra el Señor;\nél cuida de todos sus huesos,\ny ni uno sólo se quebrará.\n\nLa maldad da muerte al malvado,\nlos que odian al justo serán castigados.\nEl Señor redime a sus siervos,\nno será castigado quien se acoge a Él.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"34":[{"r":"1-2","t":"Pelea, Señor, contra los que me atacan,\nguerrea contra los que me hacen guerra;\nempuña el escudo y la adarga,\nlevántate y ven en mi auxilio;\ndi a mi alma: \n«Yo soy tu victoria.»\n\nY yo me alegraré con el Señor,\ngozando de su victoria;\ntodo mi ser proclamará:\n«Señor, ¿quién como Tú,\nque defiendes al débil del poderoso,\nal pobre y humilde del explotador?»\n\nSe presentaban testigos violentos:\nme acusaban de cosas que ni sabía,\nme pagaban mal por bien,\ndejándome desamparado.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"35":[{"r":"","t":"El malvado escucha en su interior \nun oráculo del pecado:\n«No tengo miedo a Dios,\nni en su presencia.»\nPorque se hace la ilusión de que su culpa\nno será descubierta ni aborrecida.\n\nLas palabras de su boca son maldad y traición,\nrenuncia a ser sensato y a obrar bien;\nacostado medita el crimen,\nse obstina en el mal camino,\nno rechaza la maldad.\n\nSeñor, tu misericordia llega al cielo,\ntu fidelidad hasta las nubes;\ntu justicia hasta las altas cordilleras,\ntus sentencias son como el océano inmenso.\n\nTú socorres a hombres y animales;\n¡qué inapreciable es tu misericordia, oh Dios!,\nlos humanos se acogen a la sombra de tus alas;\n\nse nutren de lo sabroso de tu casa,\nles das a beber del torrente de tus delicias,\nporque en ti está la fuente viva,\ny tu luz nos hace ver la luz.\n\nProlonga tu misericordia con los que te reconocen,\ntu justicia con los rectos de corazón;\nque no me pisotee el pie del soberbio,\nque no me eche fuera la mano del malvado.\n\nHan fracasado los malhechores;\nderribados, no se pueden levantar.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"36":[{"r":"","t":"No te exasperes por los malvados,\nno envidies a los que obran el mal:\nse secarán pronto, como la hierba,\ncomo el césped verde se agostarán.\n\nConfía en el Señor y haz el bien,\nhabita tu tierra y practica la lealtad;\nsea el Señor tu delicia,\ny Él te dará lo que pide tu corazón.\n\nEncomienda tu camino al Señor,\nconfía en Él, y Él actuará:\nhará tu justicia como el amanecer,\ntu derecho como el mediodía.\n\nDescansa en el Señor y espera en Él,\nno te exasperes por el hombre que triunfa\nempleando la intriga:\n\nCohíbe la ira, reprime el coraje,\nno te exasperes, no sea que obres mal;\nporque los que obran mal son excluidos,\npero los que esperan en el Señor poseerán la tierra.\n\nAguarda un momento: desapareció el malvado,\nfíjate en su sitio: ya no está;\nen cambio, los sufridos poseen la tierra\ny disfrutan de paz abundante.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"El malvado intriga contra el justo,\nrechina sus dientes contra él;\npero el Señor se ríe de él,\nporque ve que le llega su hora.\n\nLos malvados desenvainan la espada,\nasestan el arco,\npara abatir a pobres y humildes,\npara asesinar a los honrados;\npero su espada les atravesará el corazón,\nsus arcos se romperán.\n\nMejor es ser honrado con poco\nque ser malvado en la opulencia;\npues al malvado se le romperán los brazos,\npero al honrado lo sostiene el Señor.\n\nEl Señor vela por los días de los buenos,\ny su herencia durará siempre;\nno se agostarán en tiempo de sequía,\nen tiempo de hambres se saciarán;\n\npero los malvados perecerán,\nlos enemigos del Señor\nse marchitarán como la belleza de un prado,\nen humo se disiparán.\n\nEl malvado pide prestado y no devuelve,\nel justo se compadece y perdona.\nLos que el Señor bendice poseen la tierra,\nlos que él maldice son excluidos.\n\nEl Señor asegura los pasos del hombre,\nse complace en sus caminos;\nsi tropieza, no caerá,\nporque el Señor lo tiene de la mano.\n\nFui joven, ya soy viejo:\nnunca he visto a un justo abandonado,\nni a su linaje mendigando el pan.\nA diario se compadece y da prestado;\nbendita será su descendencia.\n\nApártate del mal y haz el bien,\ny siempre tendrás una casa;\nporque el Señor ama la justicia\ny no abandona a sus fieles.\n\nLos inicuos son exterminados,\nla estirpe de los malvados se extinguirá;\npero los justos poseen la tierra,\nla habitarán por siempre jamás.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"III","t":"La boca del justo expone la sabiduría,\nsu lengua explica el derecho;\nporque lleva en el corazón la ley de su Dios,\ny sus pasos no vacilan.\n\nEl malvado espía al justo\ne intenta darle muerte;\npero el Señor no lo entrega en sus manos,\nno deja que lo condenen en el juicio.\n\nConfía en el Señor, sigue su camino;\nél te levantará a poseer la tierra,\ny verás la expulsión de los malvados.\n\nVi a un malvado que se jactaba,\nque prosperaba como un cedro frondoso;\nvolví a pasar, y ya no estaba;\nlo busqué, y no lo encontré.\n\nObserva al honrado, fíjate en el bueno:\nsu porvenir es la paz;\nlos impíos serán totalmente aniquilados,\nel porvenir de los malvados quedará truncado.\n\nEl Señor es quien salva a los justos,\nél es su alcázar en el peligro;\nel Señor los protege y los libra,\nlos libra de los malvados y los salva\nporque se acogen a él.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"37":[{"r":"","t":"Señor, no me corrijas con ira,\nno me castigues con cólera;\ntus flechas se me han clavado,\ntu mano pesa sobre mí;\n\nno hay parte ilesa en mi carne\na causa de tu furor,\nno tienen descanso mis huesos\na causa de mis pecados;\n\nmis culpas sobrepasan mi cabeza,\nson un peso superior a mis fuerzas.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Mis llagas están podridas y supuran\npor causa de mi insensatez; \nvoy encorvado y encogido,\ntodo el día camino sombrío.\n\nTengo las espaldas ardiendo,\nno hay parte ilesa en mi carne;\nestoy agotado, deshecho del todo;\nrujo con más fuerza que un león.\n\nSeñor mío, todas mis ansias están en tu presencia,\nno se te ocultan mis gemidos;\nsiento palpitar mi corazón,\nme abandonan las fuerzas,\ny me falta hasta la luz de los ojos.\n\nMis amigos y compañeros se alejan de mí,\nmis parientes se quedan a distancia;\nme tienden lazos los que atentan contra mí,\nlos que desean mi daño me amenazan de muerte,\ntodo el día murmuran traiciones.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"III","t":"Pero yo, como un sordo, no oigo;\ncomo un mudo, no abro la boca;\nsoy como uno que no oye\ny no puede replicar.\n\nEn ti, Señor, espero,\ny tú me escucharás, Señor, Dios mío;\nesto pido: que no se alegren por mi causa,\nque, cuando resbale mi pie, no canten triunfo.\n\nPorque yo estoy a punto de caer,\ny mi pena no se aparta de mí:\nyo confieso mi culpa,\nme aflige mi pecado.\n\nMis enemigos mortales son poderosos,\nson muchos los que me aborrecen sin razón,\nlos que me pagan males por bienes,\nlos que me atacan cuando procuro el bien.\n\nNo me abandones, Señor;\nDios mío, no te quedes lejos;\nven aprisa a socorrerme,\nSeñor mío, mi salvación.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Señor, no me corrijas con ira,\nno me castigues con cólera;\ntus flechas se me han clavado,\ntu mano pesa sobre mí;\n\nno hay parte ilesa en mi carne\na causa de tu furor,\nno tienen descanso mis huesos\na causa de mis pecados;\n\nmis culpas sobrepasan mi cabeza,\nson un peso superior a mis fuerzas.\n\nMis llagas están podridas y supuran\npor causa de mi insensatez; \nvoy encorvado y encogido,\ntodo el día camino sombrío.\n\nTengo las espaldas ardiendo,\nno hay parte ilesa en mi carne;\nestoy agotado, deshecho del todo;\nrujo con más fuerza que un león.\n\nSeñor mío, todas mis ansias están en tu presencia,\nno se te ocultan mis gemidos;\nsiento palpitar mi corazón,\nme abandonan las fuerzas,\ny me falta hasta la luz de los ojos.\n\nMis amigos y compañeros se alejan de mí,\nmis parientes se quedan a distancia;\nme tienden lazos los que atentan contra mí,\nlos que desean mi daño me amenazan de muerte,\ntodo el día murmuran traiciones.\n\nPero yo, como un sordo, no oigo;\ncomo un mudo, no abro la boca;\nsoy como uno que no oye\ny no puede replicar.\n\nEn ti, Señor, espero,\ny tú me escucharás, Señor, Dios mío;\nesto pido: que no se alegren por mi causa,\nque, cuando resbale mi pie, no canten triunfo.\n\nPorque yo estoy a punto de caer,\ny mi pena no se aparta de mí:\nyo confieso mi culpa,\nme aflige mi pecado.\n\nMis enemigos mortales son poderosos,\nson muchos los que me aborrecen sin razón,\nlos que me pagan males por bienes,\nlos que me atacan cuando procuro el bien.\n\nNo me abandones, Señor;\nDios mío, no te quedes lejos;\nven aprisa a socorrerme,\nSeñor mío, mi salvación.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"38":[{"r":"","t":"Yo me dije: «vigilaré mi proceder,\npara que no se me vaya la lengua;\npondré una mordaza a mi boca\nmientras el impío esté presente.»\n\nGuardé silencio resignado,\nno hablé con ligereza;\npero mi herida empeoró,\ny el corazón me ardía por dentro;\npensándolo me requemaba,\nhasta que solté la lengua.\n\n«Señor, dame a conocer mi fin\ny cuál es la medida de mis años,\npara que comprenda lo caduco que soy.»\n\nMe concediste un palmo de vida,\nmis días son nada ante ti;\nel hombre no dura más que un soplo,\nel hombre pasa como una sombra,\npor un soplo se afana,\natesora sin saber para quién.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Y ahora, Señor, ¿qué esperanza me queda?\nTú eres mi confianza.\nLíbrame de mis inquietudes,\nno me hagas la burla de los necios.\n\nEnmudezco, no abro la boca,\nporque eres tú quien lo ha hecho.\nAparta de mí tus golpes,\nque el ímpetu de tu mano me acaba.\n\nEscarmientas al hombre\ncastigando su culpa;\ncomo una polilla roes sus tesoros;\nel hombre no es más que un soplo.\n\nEscucha, Señor, mi oración,\nhaz caso de mis gritos,\nno seas sordo a mi llanto;\n\nporque yo soy huésped tuyo,\nforastero como todos mis padres.\nAplácate, dame respiro,\nantes de que pase y no exista.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"39":[{"r":"2-14","t":"Yo esperaba con ansia al Señor;\nél se inclinó y escuchó mi grito:\n\nme levantó de la fosa fatal, \nde la charca fangosa;\nafianzó mis pies sobre roca,\ny aseguró mis pasos;\n\nme puso en la boca un cántico nuevo,\nun himno a nuestro Dios.\nMuchos, al verlo, quedaron sobrecogidos\ny confiaron en el Señor.\n\nDichoso el hombre que ha puesto\nsu confianza en el Señor,\ny no acude a los idólatras,\nque se extravían con engaños.\n\nCuántas maravillas has hecho,\nSeñor, Dios mío,\ncuántos planes en favor nuestro;\nnadie se te puede comparar.\nIntento proclamarlas, decirlas,\npero superan todo número.\n\nTú no quieres sacrificios ni ofrendas,\ny, en cambio, me abriste el oído;\nno pides sacrificio expiatorio,\nentonces yo digo: «Aquí estoy\n-como está escrito en mi libro-\npara hacer tu voluntad.»\n\nDios mío, lo quiero,\ny llevo tu ley en las entrañas.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"40":[{"r":"","t":"Dichoso el que cuida del pobre y desvalido;\nen el día aciago lo pondrá a salvo el Señor.\n\nEl Señor lo guarda y lo conserva en vida,\npara que sea dichoso en la tierra,\ny no lo entrega a la saña de sus enemigos.\n\nEl Señor lo sostendrá en el lecho del dolor,\ncalmará los dolores de su enfermedad.\n\nYo dije: «Señor, ten misericordia,\nsáname, porque he pecado contra ti.»\n\nMis enemigos me desean lo peor:\n«A ver si se muere, y se acaba su apellido.»\n\nEl que viene a verme habla con fingimiento,\ndisimula su mala intención,\ny, cuando sale afuera, la dice.\n\nMis adversarios se reúnen a murmurar contra mí,\nhacen cálculos siniestros:\n«Padece un mal sin remedio,\nse acostó para no levantarse.»\n\nIncluso mi amigo, de quien yo me fiaba,\nque compartía mi pan,\nes el primero en traicionarme.\n\nPero tú, Señor, apiádate de mí,\nhaz que pueda levantarme,\npara que yo les dé su merecido.\n\nEn esto conozco que me amas:\nen que mi enemigo no triunfa de mí.\n\nA mí, en cambio, me conservas la salud,\nme mantienes siempre en tu presencia.\n\nBendito el Señor, Dios de Israel,\nahora y por siempre. Amén, amén.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"41":[{"r":"","t":"Como busca la cierva\ncorrientes de agua,\nasí mi alma te busca\na ti, Dios mío;\n\ntiene sed de Dios,\ndel Dios vivo:\n¿cuándo entraré a ver\nel rostro de Dios?\n\nLas lágrimas son mi pan\nnoche y día,\nmientras todo el día me repiten:\n«¿Dónde está tu Dios?»\n\nRecuerdo otros tiempos,\ny desahogo mi alma conmigo:\ncómo marchaba a la cabeza del grupo,\nhacia la casa de Dios,\nentre cantos de júbilo y alabanza,\nen el bullicio de la fiesta.\n\n¿Por qué te acongojas, alma mía,\npor qué te me turbas?\nEspera en Dios, que volverás a alabarlo:\n«Salud de mi rostro, Dios mío.»\n\nCuando mi alma se acongoja,\nte recuerdo\ndesde el Jordán y el Hermón\ny el Monte Menor.\n\nUna sima grita a otra sima\ncon voz de cascadas:\ntus torrentes y tus olas\nme han arrollado.\n\nDe día el Señor\nme hará misericordia,\nde noche cantaré la alabanza\ndel Dios de mi vida.\n\nDiré a Dios: «Roca mía,\n¿por qué me olvidas?\n¿Por qué voy andando, sombrío,\nhostigado por mi enemigo?»\n\nSe me rompen los huesos\npor las burlas del adversario;\ntodo el día me preguntan:\n«¿Dónde está tu Dios?»\n\n¿Por qué te acongojas, alma mía,\npor qué te me turbas?\nEspera en Dios, que volverás a alabarlo:\n«Salud de mi rostro, Dios mío.»\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"42":[{"r":"","t":"Hazme justicia, oh Dios, defiende mi causa\ncontra gente sin piedad,\nsálvame del hombre traidor y malvado.\n\nTú eres mi Dios y protector,\n¿por qué me rechazas?,\n¿por qué voy andando sombrío,\nhostigado por mi enemigo?\n\nEnvía tu luz y tu verdad: \nque ellas me guíen\ny me conduzcan hasta tu monte santo,\nhasta tu morada.\n\nQue yo me acerque al altar de Dios,\nal Dios de mi alegría;\nque te dé gracias al son de la cítara,\nDios, Dios mío.\n\n¿Por qué te acongojas, alma mía,\npor qué te me turbas?\nEspera en Dios, que volverás a alabarlo:\n\"Salud de mi rostro, Dios mío.\"\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"43":[{"r":"","t":"Oh Dios, nuestros oídos lo oyeron,\nnuestros padres nos lo han contado:\nla obra que realizaste en sus días,\nen los años remotos.\n\nTú mismo con tu mano desposeíste a los gentiles,\ny los plantaste a ellos;\ntrituraste a las naciones,\ny los hiciste crecer a ellos.\n\nPorque no fue su espada la que ocupó la tierra,\nni su brazo el que les dio la victoria,\nsino tu diestra y tu brazo y la luz de tu rostro,\nporque tú los amabas.\n\nMi rey y mi Dios eres tú,\nque das la victoria a Jacob:\ncon tu auxilio embestimos al enemigo,\nen tu nombre pisoteamos al agresor.\n\nPues yo no confío en mi arco,\nni mi espada me da la victoria;\ntú nos das la victoria sobre el enemigo\ny derrotas a nuestros adversarios.\n\nDios ha sido siempre nuestro orgullo,\ny siempre damos gracias a tu nombre.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Ahora, en cambio, nos rechazas y nos avergüenzas,\ny ya no sales, Señor, con nuestras tropas:\nnos haces retroceder ante el enemigo,\ny nuestro adversario nos saquea.\n\nNos entregas como ovejas a la matanza\ny nos has dispersado por las naciones;\nvendes a tu pueblo por nada,\nno lo tasas muy alto.\n\nNos haces el escarnio de nuestros vecinos,\nirrisión y burla de los que nos rodean;\nnos has hecho el refrán de los gentiles,\nnos hacen muecas las naciones.\n\nTengo siempre delante mi deshonra,\ny la vergüenza me cubre la cara\nal oír insultos e injurias,\nal ver a mi rival y a mi enemigo.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"III","t":"Todo esto nos viene encima,\nsin haberte olvidado\nni haber violado tu alianza,\nsin que se volviera atrás nuestro corazón\nni se desviaran de tu camino nuestros pasos;\nY tú nos arrojaste a un lugar de chacales\ny nos cubriste de tinieblas.\n\nSi hubiéramos olvidado el nombre de nuestro Dios\ny extendido las manos a un dios extraño,\nel Señor lo habría averiguado,\npues él penetra los secretos del corazón.\n\nPor tu causa nos degüellan cada día,\nnos tratan como a ovejas de matanza.\nDespierta, Señor, ¿por qué duermes?\nLevántate, no nos rechaces más.\n¿Por qué nos escondes tu rostro\ny olvidas nuestra desgracia y opresión?\n\nNuestro aliento se hunde en el polvo,\nnuestro vientre está pegado al suelo.\nLevántate a socorrernos,\nredímenos por tu misericordia.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"44":[{"r":"","t":"Me brota del corazón un poema bello,\nrecito mis versos a un rey;\nmi lengua es ágil pluma de escribano.\n\nEres el más bello de los hombres,\nen tus labios se derrama la gracia,\nel Señor te bendice eternamente.\n\nCíñete al flanco la espada, valiente:\nes tu gala y tu orgullo;\ncabalga victorioso por la verdad y la justicia,\ntu diestra te enseñe a realizar proezas.\nTus flechas son agudas, los pueblos se te rinden,\nse acobardan los enemigos del rey.\n\nTu trono, oh Dios, permanece para siempre,\ncetro de rectitud es tu cetro real;\nhas amado la justicia y odiado la impiedad:\npor eso el Señor, tu Dios, te ha ungido\ncon aceite de júbilo \nentre todos tus compañeros.\n\nA mirra, áloe y acacia huelen tus vestidos,\ndesde los palacios de marfiles te deleitan las arpas.\nHijas de reyes salen a tu encuentro,\nde pie a tu derecha está la reina,\nenjoyada con oro de Ofir.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Escucha, hija, mira: inclina el oído,\nolvida tu pueblo y la casa paterna;\nprendado está el rey de tu belleza:\npóstrate ante él, que él es tu señor.\nLa ciudad de Tiro viene con regalos, \nlos pueblos más ricos buscan tu favor.\n\nYa entra la princesa, bellísima,\nvestida de perlas y brocado;\nla llevan ante el rey, con séquito de vírgenes,\nla siguen sus compañeras:\nlas traen entre alegría y algazara,\nvan entrando en el palacio real.\n\n«A cambio de tus padres, tendrás hijos,\nque nombrarás príncipes por toda la tierra.»\n\nQuiero hacer memorable tu nombre\npor generaciones y generaciones,\ny los pueblos te alabarán\npor los siglos de los siglos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Me brota del corazón un poema bello,\nrecito mis versos a un rey;\nmi lengua es ágil pluma de escribano.\n\nEres el más bello de los hombres,\nen tus labios se derrama la gracia,\nel Señor te bendice eternamente.\n\nCíñete al flanco la espada, valiente:\nes tu gala y tu orgullo;\ncabalga victorioso por la verdad y la justicia,\ntu diestra te enseñe a realizar proezas.\nTus flechas son agudas, los pueblos se te rinden,\nse acobardan los enemigos del rey.\n\nTu trono, oh Dios, permanece para siempre,\ncetro de rectitud es tu cetro real;\nhas amado la justicia y odiado la impiedad:\npor eso el Señor, tu Dios, te ha ungido\ncon aceite de júbilo \nentre todos tus compañeros.\n\nA mirra, áloe y acacia huelen tus vestidos,\ndesde los palacios de marfiles te deleitan las arpas.\nHijas de reyes salen a tu encuentro,\nde pie a tu derecha está la reina,\nenjoyada con oro de Ofir.\n\nEscucha, hija, mira: inclina el oído,\nolvida tu pueblo y la casa paterna;\nprendado está el rey de tu belleza:\npóstrate ante él, que él es tu señor.\nLa ciudad de Tiro viene con regalos, \nlos pueblos más ricos buscan tu favor.\n\nYa entra la princesa, bellísima,\nvestida de perlas y brocado;\nla llevan ante el rey, con séquito de vírgenes,\nla siguen sus compañeras:\nlas traen entre alegría y algazara,\nvan entrando en el palacio real.\n\n\"A cambio de tus padres tendrás hijos,\nque nombrarás príncipes por toda la tierra.\"\n\nQuiero hacer memorable tu nombre\npor generaciones y generaciones,\ny los pueblos te alabarán\npor los siglos de los siglos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"45":[{"r":"","t":"Dios es nuestro refugio y nuestra fuerza,\npoderoso defensor en el peligro.\n\nPor eso no tememos aunque tiemble la tierra\ny los montes se desplomen en el mar.\n\nQue hiervan y bramen sus olas,\nque sacudan a los montes con su furia:\n\nEl Señor de los ejércitos está con nosotros,\nnuestro alcázar es el Dios de Jacob.\n\nEl correr de las acequias alegra la ciudad de Dios,\nel Altísimo consagra su morada.\n\nTeniendo a Dios en medio, no vacila;\nDios la socorre al despuntar la aurora.\n\nLos pueblos se amotinan, los reyes se rebelan;\npero él lanza su trueno y se tambalea la tierra.\n\nEl Señor de los ejércitos está con nosotros,\nnuestro alcázar es el Dios de Jacob.\n\nVenid a ver las obras del Señor,\nlas maravillas que hace en la tierra:\n\nPone fin a la guerra hasta el extremo del orbe,\nrompe los arcos, quiebra las lanzas,\nprende fuego a los escudos.\n\n«Rendíos, reconoced que yo soy Dios:\nmás alto que los pueblos, más alto que la tierra.»\n\nEl Señor de los ejércitos está con nosotros,\nnuestro alcázar es el Dios de Jacob.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"46":[{"r":"","t":"Pueblos todos, batid palmas,\naclamad a Dios con gritos de júbilo;\nporque el Señor es sublime y terrible,\nemperador de toda la tierra.\n\nÉl nos somete los pueblos\ny nos sojuzga las naciones;\nél nos escogió por heredad suya:\ngloria de Jacob, su amado.\n\nDios asciende entre aclamaciones;\nel Señor, al son de trompetas:\ntocad para Dios, tocad,\ntocad para nuestro Rey, tocad.\n\nPorque Dios es el rey del mundo:\ntocad con maestría.\nDios reina sobre las naciones,\nDios se sienta en su trono sagrado.\n\nLos príncipes de los gentiles se reúnen\ncon el pueblo del Dios de Abrahán;\nporque de Dios son los grandes de la tierra,\ny él es excelso.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"47":[{"r":"","t":"Grande es el Señor y muy digno de alabanza\nen la ciudad de nuestro Dios,\nsu monte santo, altura hermosa,\nalegría de toda la tierra:\n\nel monte Sion, vértice del cielo,\nciudad del gran rey;\nentre sus palacios,\nDios descuella como un alcázar.\n\nMirad: los reyes se aliaron\npara atacarla juntos;\npero, al verla, quedaron aterrados \ny huyeron despavoridos;\n\nallí los agarró un temblor\ny dolores como de parto;\ncomo un viento del desierto\nque destroza las naves de Tarsis.\n\nLo que habíamos oído lo hemos visto\nen la ciudad del Señor de los ejércitos,\nen la ciudad de nuestro Dios:\nque Dios la ha fundado para siempre.\n\nOh Dios, meditamos tu misericordia\nen medio de tu templo:\ncomo tu renombre, oh Dios, tu alabanza\nllega al confín de la tierra;\n\ntu diestra está llena de justicia:\nel monte Sion se alegra,\nlas ciudades de Judá se gozan\ncon tus sentencias.\n\nDad la vuelta en torno a Sion,\ncontando sus torreones;\nfijaos en sus baluartes,\nobservad sus palacios,\n\npara poder decirle a la próxima generación:\n«Éste es el Señor, nuestro Dios.»\nÉl nos guiará por siempre jamás.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"48":[{"r":"","t":"Oíd esto, todas las naciones;\nescuchadlo, habitantes del orbe:\nplebeyos y nobles, ricos y pobres;\n\nmi boca hablará sabiamente,\ny serán muy sensatas mis reflexiones;\nprestaré oído al proverbio\ny propondré mi problema al son de la cítara.\n\n¿Por qué habré de temer los días aciagos,\ncuando me cerquen y acechen los malvados\nque confían en su opulencia\ny se jactan de sus inmensas riquezas,\nsi nadie puede salvarse\nni dar a Dios un rescate?\n\nEs tan caro el rescate de la vida,\nque nunca les bastará\npara vivir perpetuamente\nsin bajar a la fosa.\n\nMirad: los sabios mueren,\nlo mismo que perecen los ignorantes y necios,\ny legan sus riquezas a extraños.\n\nEl sepulcro es su morada perpetua\ny su casa de edad en edad,\naunque hayan dado nombre a países.\n\nEl hombre no perdura en la opulencia,\nsino que perece como los animales.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Éste es el camino de los confiados,\nel destino de los hombres satisfechos:\nson un rebaño para el abismo,\nla muerte es su pastor,\ny bajan derechos a la tumba;\nse desvanece su figura,\ny el abismo es su casa.\n\nPero a mí, Dios me salva,\nme saca de las garras del abismo \ny me lleva consigo.\n\nNo te preocupes si se enriquece un hombre \ny aumenta el fasto de su casa:\ncuando muera, no se llevará nada,\nsu fasto no bajará con él.\n\nAunque en vida se felicitaba:\n\"Ponderan lo bien que lo pasas\",\nirá a reunirse con sus antepasados,\nque no verán nunca la luz.\n\nEl hombre rico e inconsciente\nes como un animal que perece.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"49":[{"r":"","t":"El Dios de los dioses, el Señor, habla:\nconvoca la tierra de oriente a occidente.\nDesde Sion, la hermosa, Dios resplandece:\nviene nuestro Dios, y no callará.\n\nLo precede fuego voraz,\nlo rodea tempestad violenta.\nDesde lo alto convoca cielo y tierra\npara juzgar a su pueblo:\n\n«Congregadme a mis fieles,\nque sellaron mi pacto con un sacrificio».\nProclame el cielo su justicia;\nDios en persona va a juzgar.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"«Escucha, pueblo mío, que voy a hablarte;\nIsrael, voy a dar testimonio contra ti;\nYo, Dios, tu Dios.\n\nNo te reprocho tus sacrificios,\npues siempre están tus holocaustos ante mí.\nPero no aceptaré un becerro de tu casa,\nni un cabrito de tus rebaños;\n\nPues las fieras de la selva son mías,\ny hay miles de bestias en mis montes;\nconozco todos los pájaros del cielo,\ntengo a mano cuanto se agita en los campos.\n\nSi tuviera hambre, no te lo diría;\npues el orbe y cuanto lo llena es mío.\n¿Comeré yo carne de toros,\nbeberé sangre de cabritos?\n\nOfrece a Dios un sacrificio de alabanza,\ncumple tus votos al Altísimo\ne invócame el día del peligro:\nyo te libraré y tú me darás gloria».\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"III","t":"Dios dice al pecador:\n«¿Por qué recitas mis preceptos\ny tienes siempre en la boca mi alianza,\ntú que detestas mi enseñanza\ny te echas a la espalda mis mandatos?\n\nCuando ves un ladrón, corres con él;\nte mezclas con los adúlteros;\nsueltas tu lengua para el mal,\ntu boca urde el engaño;\n\nte sientas a hablar contra tu hermano,\ndeshonras al hijo de tu madre;\nesto haces, ¿y me voy callar?\n¿Crees que soy como tú?\nTe acusaré, te lo echaré en cara.\n\nAtención los que olvidáis a Dios,\nno sea que os destroce sin remedio.\n\nEl que me ofrece acción de gracias,\nese me honra;\nal que sigue buen camino\nle haré ver la salvación de Dios».\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"50":[{"r":"","t":"Misericordia, Dios mío, por tu bondad,\npor tu inmensa compasión borra mi culpa;\nlava del todo mi delito, \nlimpia mi pecado.\n\nPues yo reconozco mi culpa,\ntengo siempre presente mi pecado:\ncontra ti, contra ti solo pequé,\ncometí la maldad que aborreces.\n\nEn la sentencia tendrás razón,\nen el juicio resultarás inocente.\nMira, en la culpa nací,\npecador me concibió mi madre.\n\nTe gusta un corazón sincero,\ny en mi interior me inculcas sabiduría.\nRocíame con el hisopo: quedaré limpio;\nlávame: quedaré más blanco que la nieve.\n\nHazme oír el gozo y la alegría,\nque se alegren los huesos quebrantados.\nAparta de mi pecado tu vista,\nborra en mí toda culpa.\n\nOh Dios, crea en mí un corazón puro,\nrenuévame por dentro con espíritu firme,\nno me arrojes lejos de tu rostro,\nno me quites tu santo espíritu.\n\nDevuélveme la alegría de tu salvación,\nafiánzame con espíritu generoso:\nenseñaré a los malvados tus caminos,\nlos pecadores volverán a ti.\n\nLíbrame de la sangre, oh Dios,\nDios, Salvador mío,\ny cantará mi lengua tu justicia.\nSeñor, me abrirás los labios,\ny mi boca proclamará tu alabanza.\n\nLos sacrificios no te satisfacen:\nsi te ofreciera un holocausto, no lo querrías.\nMi sacrificio es un espíritu quebrantado;\nun corazón quebrantado y humillado,\ntú no lo desprecias.\n\nSeñor, por tu bondad, favorece a Sion,\nreconstruye las murallas de Jerusalén:\nentonces aceptarás los sacrificios rituales,\nofrendas y holocaustos,\nsobre tu altar se inmolarán novillos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"51":[{"r":"","t":"¿Por qué te glorías de la maldad\ny te envalentonas contra el piadoso?\nEstás todo el día maquinando injusticias,\ntu lengua es navaja afilada,\nautor de fraudes;\n\nprefieres el mal al bien, \nla mentira a la honradez;\nprefieres las palabras corrosivas,\nlengua embustera.\n\nPues Dios te destruirá para siempre,\nte abatirá y te barrerá de tu tienda;\narrancará tus raíces\ndel suelo vital.\n\nLo verán los justos, y temerán,\ny se reirán de él:\n«Mirad al valiente\nque no puso en Dios su apoyo,\nconfió en sus muchas riquezas,\nse insolentó en sus crímenes.»\n\nPero yo, como verde olivo,\nen la casa de Dios,\nconfío en la misericordia de Dios\npor siempre jamás.\n\nTe daré siempre gracias\nporque has actuado;\nproclamaré delante de tus fieles:\n«Tu nombre es bueno»\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"52":[{"r":"","t":"Dice el necio para sí:\n«No hay Dios»\nSe han corrompido cometiendo execraciones,\nno hay quien obre bien.\n\nDios observa desde el cielo\na los hijos de Adán,\npara ver si hay alguno sensato\nque busque a Dios.\n\nTodos se extravían\nigualmente obstinados,\nno hay uno que obre bien,\nni uno solo.\n\nPero ¿no aprenderán los malhechores\nque devoran a mi pueblo como pan\ny no invocan al Señor?\n\nPues temblarán de espanto,\nporque Dios esparce los huesos del agresor,\ny serán derrotados,\nporque Dios los rechaza.\n\n¡Ojalá venga desde Sion\nla salvación de Israel!\nCuando el Señor cambie la suerte de su pueblo,\nse alegrará Jacob y gozará Israel.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"53":[{"r":"3-6","t":"Oh Dios, sálvame por tu nombre,\nsal por mí con tu poder.\nOh Dios, escucha mi súplica,\natiende a mis palabras;\n\nporque unos insolentes se alzan contra mí,\ny hombres violentos me persiguen a muerte,\nsin tener presente a Dios.\n\nPero Dios es mi auxilio,\nel Señor sostiene mi vida.\n\nTe ofreceré un sacrificio voluntario,\ndando gracias a tu nombre, que es bueno;\nporque me libraste del peligro,\ny he visto la derrota de mis enemigos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"54":[{"r":"2-15","t":"Dios mío, escucha mi oración,\nno te cierres a mi súplica;\nhazme caso y respóndeme,\nme agitan mis ansiedades.\n\nMe turba la voz del enemigo,\nlos gritos del malvado:\ndescargan sobre mí calamidades\ny me atacan con furia.\n\nSe me retuercen dentro las entrañas,\nme sobrecoge un pavor mortal,\nme asalta el temor y el terror,\nme cubre el espanto,\n\ny pienso: «¡Quién me diera alas de paloma\npara volar y posarme!\nEmigraría lejos,\nhabitaría en el desierto,\n\nme pondría enseguida a salvo de la tormenta,\ndel huracán que devora, Señor;\ndel torrente de sus lenguas.»\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"55":[{"r":"2-7","t":"Misericordia, Dios mío, que me hostigan,\nme atacan y me acosan todo el día;\ntodo el día me hostigan mis enemigos,\nme atacan en masa.\n\nLevántate en el día terrible,\nyo confío en ti.\n\nEn Dios, cuya promesa alabo, \nen Dios confío y no temo:\n¿qué podrá hacerme un mortal?\n\nTodos los días discuten y planean\npensando sólo en mi daño;\nbuscan un sitio para espiarme,\nacechan mis pasos y atentan contra mi vida.\n\nAnota en tu libro mi vida errante,\nrecoge mis lágrimas en tu odre, Dios mío.\n\nQue retrocedan mis enemigos cuando te invoco,\ny así sabré que eres mi Dios.\n\nEn Dios, cuya promesa alabo,\nen el Señor, cuya promesa alabo,\nen Dios confío y no temo;\n¿qué podrá hacerme un hombre?\n\nTe debo, Dios mío, los votos que hice,\nlos cumpliré con acción de gracias;\nporque libraste mi alma de la muerte,\nmis pies de la caída;\npara que camine en presencia de Dios\na la luz de la vida.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"56":[{"r":"","t":"Misericordia, Dios mío, misericordia,\nque mi alma se refugia en ti;\nme refugio a la sombra de tus alas\nmientras pasa la calamidad.\n\nInvoco al Dios altísimo,\nal Dios que hace tanto por mí:\ndesde el cielo me enviará la salvación,\nconfundirá a los que ansían matarme,\nenviará su gracia y su lealtad.\n\nEstoy echado entre leones\ndevoradores de hombres;\nsus dientes son lanzas y flechas,\nsu lengua es una espada afilada.\n\nElévate sobre el cielo, Dios mío,\ny llene la tierra tu gloria.\n\nHan tendido una red a mis pasos\npara que sucumbiera;\nme han cavado delante una fosa,\npero han caído en ella.\n\nMi corazón está firme, Dios mío,\nmi corazón está firme.\nVoy a cantar y a tocar:\ndespierta, gloria mía;\ndespertad, cítara y arpa;\ndespertaré a la aurora.\n\nTe daré gracias ante los pueblos, Señor;\ntocaré para ti ante las naciones:\npor tu bondad, que es más grande que los cielos;\npor tu fidelidad, que alcanza a las nubes.\n\nElévate sobre el cielo, Dios mío,\ny llene la tierra tu gloria.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"58":[{"r":"2-5","t":"Líbrame de mi enemigo, Dios mío;\nprotégeme de mis agresores,\nlíbrame de los malhechores,\nsálvame de los hombres sanguinarios.\n\nMira que me están acechando,\ny me acosan los poderosos:\nsin que yo haya pecado ni faltado, Señor,\nsin culpa mía, avanzan para acometerme.\n\nDespierta, ven a mi encuentro, mira:\ntú, el Señor de los ejércitos,\nel Dios de Israel.\n\nEstoy velando contigo, fuerza mía,\nporque tú, oh Dios, eres mi alcázar;\nque tu favor se adelante, oh Dios,\ny me haga ver la derrota del enemigo.\n\nPero yo cantaré tu fuerza,\npor la mañana aclamaré tu misericordia;\nporque has sido mi alcázar\ny mi refugio en el peligro.\n\nY tocaré en tu honor, fuerza mía,\nporque tú, oh Dios, eres mi alcázar.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"59":[{"r":"","t":"Oh Dios, nos rechazaste y rompiste nuestras filas;\nestabas airado, pero restáuranos.\nHas sacudido y agrietado el país:\nrepara sus grietas, que se desmorona.\n\nHiciste sufrir un desastre a tu pueblo,\ndándole a beber un vino de vértigo;\ndiste a tus fieles la señal de desbandada,\nhaciéndolos huir de los arcos.\n\nPara que se salven tus predilectos,\nque tu mano salvadora nos responda.\n\nDios habló en su santuario:\n«Triunfante ocuparé Siquén,\nparcelaré el valle de Sucot;\n\nmío es Galaad, mío Manasés,\nEfraín es yelmo de mi cabeza,\nJudá es mi cetro;\n\nMoab, una jofaina para lavarme;\nsobre Edom echo mi sandalia,\nsobre Filistea canto victoria».\n\nPero ¿quién me guiará a la plaza fuerte,\nquién me conducirá a Edom,\nsi tú, oh Dios, nos has rechazado\ny no sales ya con nuestras tropas?\n\nAuxílianos contra el enemigo,\nque la ayuda del hombre es inútil.\nCon Dios haremos proezas,\nÉl pisoteará a nuestros enemigos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"60":[{"r":"","t":"Dios mío, escucha mi clamor,\natiende a mi súplica;\nte invoco desde el confín de la tierra\ncon el corazón abatido:\n\nllévame a una roca inaccesible,\nporque tú eres mi refugio\ny mi bastión contra el enemigo.\n\nHabitaré siempre en tu morada,\nrefugiado al amparo de tus alas;\nporque tú, oh Dios, escucharás mis votos\ny me darás la heredad de los que veneran tu nombre.\n\nAñade días a los días del rey,\nque sus años alcancen varias generaciones;\nque reine siempre en presencia de Dios,\nque tu gracia y tu lealtad le hagan guardia.\n\nYo tañeré siempre en tu honor,\ne iré cumpliendo mis votos día tras día.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"61":[{"r":"","t":"Sólo en Dios descansa mi alma,\nporque de él viene mi salvación;\nsólo él es mi roca y mi salvación,\nmi alcázar: no vacilaré.\n\n¿Hasta cuándo arremeteréis contra un hombre\ntodos juntos, para derribarlo\ncomo a una pared que cede \no a una tapia ruinosa?\n\nSólo piensan en derribarme de mi altura,\ny se complacen en la mentira:\ncon la boca bendicen,\ncon el corazón maldicen.\n\nDescansa sólo en Dios, alma mía,\nporque él es mi esperanza;\nsólo él es mi roca y mi salvación,\nmi alcázar: no vacilaré.\n\nDe Dios vienen mi salvación y mi gloria,\nél es mi roca firme,\nDios es mi refugio.\n\nPueblo suyo, confiad en él,\ndesahogad ante él vuestro corazón,\nque Dios es nuestro refugio.\n\nLos hombres no son más que un soplo,\nlos nobles son apariencia:\ntodos juntos en la balanza subirían\nmás leves que un soplo.\n\nNo confiéis en la opresión,\nno pongáis ilusiones en el robo;\ny aunque crezcan vuestras riquezas,\nno les deis el corazón.\n\nDios ha dicho una cosa,\ny dos cosas que he escuchado:\n\n\"Que Dios tiene el poder\ny el Señor tiene la gracia;\nque tú pagas a cada uno\nsegún sus obras.\"\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"62":[{"r":"2-9","t":"Oh Dios, tú eres mi Dios, por ti madrugo,\nmi alma está sedienta de ti;\nmi carne tiene ansia de ti,\ncomo tierra reseca, agostada, sin agua.\n\n¡Cómo te contemplaba en el santuario\nviendo tu fuerza y tu gloria!\nTu gracia vale más que la vida,\nte alabarán mis labios.\n\nToda mi vida te bendeciré\ny alzaré las manos invocándote.\nMe saciaré como de enjundia y de manteca,\ny mis labios te alabarán jubilosos.\n\nEn el lecho me acuerdo de ti\ny velando medito en ti,\nporque fuiste mi auxilio,\ny a la sombra de tus alas canto con júbilo;\nmi alma está unida a ti,\ny tu diestra me sostiene.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"63":[{"r":"","t":"Escucha, oh Dios, la voz de mi lamento,\nprotege mi vida del terrible enemigo;\nescóndeme de la conjura de los perversos\ny del motín de los malhechores:\n\nafilan sus lenguas como espadas\ny disparan como flechas palabras venenosas,\npara herir a escondidas al inocente,\npara herirlo por sorpresa y sin riesgo.\n\nSe animan al delito,\ncalculan cómo esconder trampas,\ny dicen: «¿quién lo descubrirá?»\nInventan maldades y ocultan sus invenciones,\nporque su mente y su corazón no tienen fondo.\n\nPero Dios los acribilla a flechazos,\npor sorpresa los cubre de heridas;\nsu misma lengua los lleva a la ruina,\ny los que lo ven menean la cabeza.\n\nTodo el mundo se atemoriza,\nproclama la obra de Dios\ny medita sus acciones.\n\nEl justo se alegra con el Señor,\nse refugia en Él,\ny se felicitan los rectos de corazón.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"64":[{"r":"","t":"Oh Dios, tú mereces un himno en Sion,\ny a ti se te cumplen los votos,\nporque tú escuchas las súplicas.\n\nA ti acude todo mortal\na causa de sus culpas;\nnuestros delitos nos abruman,\npero tú los perdonas.\n\nDichoso el que tú eliges y acercas\npara que viva en tus atrios:\nque nos saciemos de los bienes de tu casa,\nde los dones sagrados de tu templo.\n\nCon portentos de justicia nos respondes,\nDios, salvador nuestro;\ntú, esperanza del confín de la tierra\ny del océano remoto;\n\ntú que afianzas los montes con tu fuerza,\nceñido de poder;\ntú que reprimes el estruendo del mar,\nel estruendo de las olas\ny el tumulto de los pueblos.\n\nLos habitantes del extremo del orbe\nse sobrecogen ante tus signos,\ny a las puertas de la aurora y del ocaso\nlas llenas de júbilo.\n\nTú cuidas de la tierra, la riegas\ny la enriqueces sin medida;\nla acequia de Dios va llena de agua,\npreparas los trigales;\n\nriegas los surcos, igualas los terrones,\ntu llovizna los deja mullidos,\nbendices sus brotes;\ncoronas el año con tus bienes,\ntus carriles rezuman abundancia;\n\nrezuman los pastos del páramo,\ny las colinas se orlan de alegría;\nlas praderas se cubren de rebaños,\ny los valles se visten de mieses,\nque aclaman y cantan.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"65":[{"r":"","t":"Aclamad al Señor, tierra entera;\ntocad en honor de su nombre,\ncantad himnos a su gloria.\n\nDecid a Dios: \"¡Qué temibles son tus obras,\npor tu inmenso poder tus enemigos te adulan!\"\n\nQue se postre ante ti la tierra entera,\nque toquen en tu honor,\nque toquen para tu nombre.\n\nVenid a ver las obras de Dios,\nsus temibles proezas en favor de los hombres:\ntransformó el mar en tierra firme,\na pie atravesaron el río.\n\nAlegrémonos con Dios,\nque con su poder gobierna eternamente;\nsus ojos vigilan a las naciones,\npara que no se subleven los rebeldes.\n\nBendecid, pueblos, a nuestro Dios,\nhaced resonar sus alabanzas,\nporque él nos ha devuelto la vida \ny no dejó que tropezaran nuestros pies.\n\nOh Dios, nos pusiste a prueba,\nnos refinaste como refinan la plata;\nnos empujaste a la trampa,\nnos echaste a cuestas un fardo:\n\nsobre nuestro cuello cabalgaban,\npasamos por fuego y por agua,\npero nos has dado respiro.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Entraré en tu casa con víctimas,\npara cumplirte mis votos:\nlos que pronunciaron mis labios\ny prometió mi boca en el peligro.\n\nTe ofreceré víctimas cebadas,\nte quemaré carneros,\ninmolaré bueyes y cabras.\n\nFieles de Dios, venid a escuchar,\nos contaré lo que ha hecho conmigo:\na él gritó mi boca\ny lo ensalzó mi lengua.\n\nSi hubiera tenido yo mala intención,\nel Señor no me habría escuchado;\npero Dios me escuchó,\ny atendió a mi voz suplicante.\n\nBendito sea Dios, que no rechazó mi súplica\nni me retiró su favor.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"66":[{"r":"","t":"El Señor tenga piedad y nos bendiga,\nilumine su rostro sobre nosotros;\nconozca la tierra tus caminos,\ntodos los pueblos tu salvación.\n Se repite la antífonaOh Dios, que te alaben los pueblos,\nque todos los pueblos te alaben.\nSe repite la antífonaQue canten de alegría las naciones,\nporque riges el mundo con justicia,\nriges los pueblos con rectitud\ny gobiernas las naciones de la tierra.\nSe repite la antífonaOh Dios, que te alaben los pueblos,\nque todos los pueblos te alaben.\nSe repite la antífonaLa tierra ha dado su fruto,\nnos bendice el Señor, nuestro Dios.\nQue Dios nos bendiga; que le teman\nhasta los confines del orbe.\nSe repite la antífonaGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"El Señor tenga piedad y nos bendiga,\nilumine su rostro sobre nosotros;\nconozca la tierra tus caminos,\ntodos los pueblos tu salvación.\n\nOh Dios, que te alaben los pueblos,\nque todos los pueblos te alaben.\n\nQue canten de alegría las naciones,\nporque riges el mundo con justicia,\nriges los pueblos con rectitud\ny gobiernas las naciones de la tierra.\n\nOh Dios, que te alaben los pueblos,\nque todos los pueblos te alaben.\n\nLa tierra ha dado su fruto,\nnos bendice el Señor, nuestro Dios.\nQue Dios nos bendiga; que le teman\nhasta los confines del orbe.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"67":[{"r":"","t":"Se levanta Dios, y se dispersan sus enemigos,\nhuyen de su presencia los que lo odian;\n\ncomo el humo se disipa, se disipan ellos;\ncomo se derrite la cera ante el fuego,\nasí perecen los impíos ante Dios.\n\nEn cambio, los justos se alegran,\ngozan en la presencia de Dios,\nrebosando de alegría.\n\nCantad a Dios, tocad en su honor,\nalfombrad el camino del que avanza por el desierto;\nsu nombre es el Señor:\nalegraos en su presencia.\n\nPadre de huérfanos, protector de viudas,\nDios vive en su santa morada.\n\nDios prepara casa a los desvalidos,\nlibera a los cautivos y los enriquece;\nsólo los rebeldes \nse quedan en la tierra abrasada.\n\nOh Dios, cuando salías al frente de tu pueblo\ny avanzabas por el desierto,\nla tierra tembló, el cielo destiló\nante Dios, el Dios del Sinaí;\nante Dios, el Dios de Israel.\n\nDerramaste en tu heredad, oh Dios, una lluvia copiosa,\naliviaste la tierra extenuada;\ny tu rebaño habitó en la tierra\nque tu bondad, oh Dios, preparó para los pobres.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"El Señor pronuncia un oráculo,\nmillares pregonan la alegre noticia:\n\"los reyes, los ejércitos van huyendo, van huyendo;\nlas mujeres reparten el botín.\n\nMientras reposabais en los apriscos,\nlas palomas batieron sus alas de plata,\nel oro destellaba en sus plumas.\nMientras el Todopoderoso dispersaba a los reyes,\nla nieve bajaba sobre el Monte Umbrío\".\n\nLas montañas de Basán son altísimas,\nlas montañas de Basán son escarpadas;\n¿por qué tenéis envidia, montañas escarpadas,\ndel monte escogido por Dios para habitar,\nmorada perpetua del Señor?\n\nLos carros de Dios son miles y miles:\nDios marcha del Sinaí al santuario.\nSubiste a la cumbre llevando cautivos,\nte dieron tributo de hombres:\nincluso los que se resistían\na que el Señor Dios tuviera una morada.\n\nBendito el Señor cada día,\nDios lleva nuestras cargas, es nuestra salvación.\nNuestro Dios es un Dios que salva,\nel Señor Dios nos hace escapar de la muerte.\n\nDios aplasta las cabezas de sus enemigos,\nlos cráneos de los malvados contumaces.\nDice el Señor: \"Los traeré desde Basán,\nlos traeré desde el fondo del mar;\nteñirás tus pies en la sangre del enemigo\ny los perros la lamerán con sus lenguas\".\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"III","t":"Aparece tu cortejo, oh Dios,\nel cortejo de mi Dios, de mi Rey,\nhacia el santuario.\n\nAl frente, marchan los cantores;\nlos últimos, los tocadores de arpa;\nen medio, las muchachas van tocando panderos.\n\n\"En el bullicio de la fiesta, bendecid a Dios,\nal Señor, estirpe de Israel\".\n\nVa delante Benjamín, el más pequeño;\nlos príncipes de Judá con sus tropeles;\nlos príncipes de Zabulón,\nlos príncipes de Neftalí.\n\nOh Dios, despliega tu poder,\ntu poder, oh Dios, que actúa en favor nuestro.\nA tu templo de Jerusalén\ntraigan los reyes su tributo.\n\nReprime a la Fiera del Cañaveral,\nal tropel de los Toros,\na los Novillos de los pueblos.\n\nQue se te rindan con lingotes de plata:\ndispersa las naciones belicosas.\nLleguen los magnates de Egipto,\nEtiopía extienda sus manos a Dios.\n\nReyes de la tierra, cantad a Dios,\ntocad para el Señor,\nque avanza por los cielos,\nlos cielos antiquísimos,\nque lanza su voz, su voz poderosa:\n\"Reconoced el poder de Dios\".\n\nSobre Israel resplandece su majestad,\ny su poder sobre las nubes.\nDesde el santuario, Dios impone reverencia:\nes el Dios de Israel \nquien da fuerza y poder a su pueblo.\n\n¡Dios sea bendito!\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"68":[{"r":"2-22","t":"Dios mío, sálvame,\nque me llega el agua al cuello:\nme estoy hundiendo en un cieno profundo\ny no puedo hacer pie;\nhe entrado en la hondura del agua,\nme arrastra la corriente.\n\nEstoy agotado de gritar,\ntengo ronca la garganta;\nse me nublan los ojos\nde tanto aguardar a mi Dios.\n\nMás que los pelos de mi cabeza\nson los que me odian sin razón;\nmás duros que mis huesos,\nlos que me atacan injustamente.\n¿Es que voy a devolver \nlo que no he robado?\n\nDios mío, tú conoces mi ignorancia, \nno se te ocultan mis delitos.\nQue por mi causa no queden defraudados\nlos que esperan en ti, Señor de los ejércitos.\n\nQue por mi causa no se avergüencen\nlos que te buscan, Dios de Israel.\nPor ti he aguantado afrentas,\nla vergüenza cubrió mi rostro.\n\nSoy un extraño para mis hermanos,\nun extranjero para los hijos de mi madre;\nporque me devora el celo de tu templo,\ny las afrentas con que te afrentan caen sobre mí.\n\nCuando me aflijo con ayunos,\nse burlan de mí;\ncuando me visto de saco,\nse ríen de mí;\nsentados a la puerta cuchichean,\nmientras beben vino me sacan coplas.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"69":[{"r":"","t":"Dios mío, dígnate librarme;\nSeñor, date prisa en socorrerme.\nSufran una derrota ignominiosa\nlos que me persiguen a muerte;\n\nvuelvan la espalda afrentados\nlos que traman mi daño;\nque se retiren avergonzados\nlos que se ríen de mí.\n\nAlégrense y gocen contigo\ntodos los que te buscan;\ny digan siempre: «Dios es grande»,\nlos que desean tu salvación.\n\nYo soy pobre y desgraciado:\nDios mío, socórreme,\nque tú eres mi auxilio y mi liberación.\n¡Señor, no tardes!\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"70":[{"r":"","t":"A ti, Señor, me acojo:\nno quede yo derrotado para siempre;\ntú que eres justo, líbrame y ponme a salvo,\ninclina a mí tu oído, y sálvame.\n\nSé tú mi roca de refugio,\nel alcázar donde me salve,\nporque mi peña y mi alcázar eres tú.\n\nDios mío, líbrame de la mano perversa,\ndel puño criminal y violento;\nporque tú, Dios mío, fuiste mi esperanza\ny mi confianza, Señor, desde mi juventud.\n\nEn el vientre materno ya me apoyaba en ti,\nen el seno tú me sostenías, \nsiempre he confiado en ti.\n\nMuchos me miraban como a un milagro,\nporque tú eres mi fuerte refugio.\nLlena estaba mi boca de tu alabanza\ny de tu gloria, todo el día.\n\nNo me rechaces ahora en la vejez,\nme van faltando las fuerzas, no me abandones;\nporque mis enemigos hablan de mí,\nlos que acechan mi vida celebran consejo;\ndicen: \"Dios lo ha abandonado;\nperseguidlo, agarradlo, que nadie lo defiende.\"\n\nDios mío, no te quedes a distancia;\nDios mío, ven aprisa a socorrerme.\nQue fracasen y se pierdan\nlos que atentan contra mi vida,\nqueden cubiertos de oprobio y vergüenza\nlos que buscan mi daño.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Yo, en cambio, seguiré esperando,\nredoblaré tus alabanzas;\nmi boca contará tu auxilio,\ny todo el día tu salvación.\nContaré tus proezas, Señor mío,\nnarraré tu victoria, tuya entera.\n\nDios mío, me instruiste desde mi juventud,\ny hasta hoy relato tus maravillas,\nahora, en la vejez y las canas,\nno me abandones, Dios mío,\n\nhasta que describa tu brazo\na la nueva generación,\ntus proezas y tus victorias excelsas,\nlas hazañas que realizaste:\nDios mío, ¿quién como tú?\n\nMe hiciste pasar por peligros,\nmuchos y graves:\nde nuevo me darás la vida,\nme harás subir de lo hondo de la tierra;\n\nacrecerás mi dignidad, \nde nuevo me consolarás;\ny yo te daré gracias, Dios mío,\ncon el arpa, por tu lealtad;\n\ntocaré para ti la cítara,\nSanto de Israel;\nte aclamarán mis labios, Señor,\nmi alma, que tú redimiste;\n\ny mi lengua todo el día\nrecitará tu auxilio,\nporque quedaron derrotados y afrentados\nlos que buscaban mi daño.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"71":[{"r":"","t":"Dios mío, confía tu juicio al rey,\ntu justicia al hijo de reyes,\npara que rija a tu pueblo con justicia,\na tus humildes con rectitud.\n\nQue los montes traigan paz,\ny los collados justicia;\nque él defienda a los humildes del pueblo,\nsocorra a los hijos del pobre\ny quebrante al explotador.\n\nQue dure tanto como el sol,\ncomo la luna, de edad en edad;\nque baje como lluvia sobre el césped,\ncomo llovizna que empapa la tierra.\n\nQue en sus días florezcan la justicia\ny la paz hasta que falte la luna;\nque dominen de mar a mar,\ndel Gran Río al confín de la tierra.\n\nQue en su presencia se inclinen sus rivales;\nque sus enemigos muerdan el polvo;\nque los reyes de Tarsis y de las islas\nle paguen tributo.\n\nQue los reyes de Saba y de Arabia\nle ofrezcan sus dones;\nque se postren ante él todos los reyes,\ny que todos los pueblos le sirvan.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Él librará al pobre que clamaba,\nal afligido que no tenía protector;\nél se apiadará del pobre y del indigente,\ny salvará la vida de los pobres;\nél rescatará sus vidas de la violencia,\nsu sangre será preciosa a sus ojos.\n\nQue viva y que le traigan el oro de Saba;\nque recen por él continuamente\ny lo bendigan todo el día.\n\nQue haya trigo abundante en los campos,\ny susurre en lo alto de los montes;\nque den fruto como el Líbano,\ny broten las espigas como hierba del campo.\n\nQue su nombre sea eterno,\ny su fama dure como el sol;\nque él sea la bendición de todos los pueblos,\ny lo proclamen dichoso todas las razas de la tierra.\n\nBendito sea el Señor, Dios de Israel,\nel único que hace maravillas;\nbendito por siempre su nombre glorioso;\nque su gloria llene la tierra.\n¡Amén, amén!\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Dios mío, confía tu juicio al rey,\ntu justicia al hijo de reyes,\npara que rija a tu pueblo con justicia,\na tus humildes con rectitud.\n\nQue los montes traigan paz,\ny los collados justicia;\nque él defienda a los humildes del pueblo,\nsocorra a los hijos del pobre\ny quebrante al explotador.\n\nQue dure tanto como el sol,\ncomo la luna, de edad en edad;\nque baje como lluvia sobre el césped,\ncomo llovizna que empapa la tierra.\n\nQue en sus días florezcan la justicia\ny la paz hasta que falte la luna;\nque dominen de mar a mar,\ndel Gran Río al confín de la tierra.\n\nQue en su presencia se inclinen sus rivales;\nque sus enemigos muerdan el polvo;\nque los reyes de Tarsis y de las islas\nle paguen tributo.\n\nQue los reyes de Saba y de Arabia\nle ofrezcan sus dones;\nque se postren ante él todos los reyes,\ny que todos los pueblos le sirvan:\n\nporque él librará al pobre que clamaba,\nal afligido que no tenía protector;\nél se apiadará del pobre y del indigente,\ny salvará la vida de los pobres;\nél rescatará sus vidas de la violencia,\nsu sangre será preciosa a sus ojos.\n\nQue viva y que le traigan el oro de Saba;\nque recen por él continuamente\ny lo bendigan todo el día.\n\nQue haya trigo abundante en los campos,\ny susurre en lo alto de los montes;\nque den fruto como el Líbano,\ny broten las espigas como hierba del campo.\n\nQue su nombre sea eterno,\ny su fama dure como el sol;\nque él sea la bendición de todos los pueblos,\ny lo proclamen dichoso todas las razas de la tierra.\n\nBendito sea el Señor, Dios de Israel,\nel único que hace maravillas;\nbendito por siempre su nombre glorioso;\nque su gloria llene la tierra.\n¡Amén, amén!\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"72":[{"r":"","t":"¡Qué bueno es Dios para el justo,\nel Señor para los limpios de corazón!\n\nPero yo por poco doy un mal paso,\ncasi resbalaron mis pisadas:\nporque envidiaba a los perversos,\nviendo prosperar a los malvados.\n\nPara ellos no hay sinsabores,\nestán sanos y orondos;\nno pasan las fatigas humanas,\nni sufren como los demás.\n\nPor eso su collar es el orgullo,\ny los cubre un vestido de violencia;\nde las carnes les rezuma la maldad,\nel corazón les rebosa de malas ideas.\n\nInsultan y hablan mal,\ny desde lo alto amenazan con la opresión.\nSu boca se atreve con el cielo.\nY su lengua recorre la tierra.\n\nPor eso mi pueblo se vuelve a ellos\ny se bebe sus palabras.\nEllos dicen: \"¿Es que Dios lo va a saber,\nse va a enterar el Altísimo?\"\nAsí son los malvados:\nsiempre seguros, acumulan riquezas.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Entonces, ¿para qué he limpiado yo mi corazón\ny he lavado en la inocencia mis manos?\n¿Para qué aguanto yo todo el día\ny me corrijo cada mañana?\n\nSi yo dijera: \"Voy a hablar como ellos\",\nrenegaría de la estirpe de tus hijos.\n\nMeditaba yo para entenderlo,\npero me resultaba muy difícil;\nhasta que entré en el misterio de Dios,\ny comprendí el destino de ellos.\n\nEs verdad: los pones en el resbaladero,\nlos precipitas en la ruina;\nen un momento causan horror,\ny acaban consumidos de espanto.\n\nComo un sueño al despertar, Señor,\nal despertarte desprecias sus sombras.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"III","t":"Cuando mi corazón se agriaba\ny me punzaba mi interior,\nyo era un necio y un ignorante,\nyo era un animal ante ti.\n\nPero yo siempre estaré contigo,\ntu agarras mi mano derecha,\nme guías según tus planes,\ny me llevas a un destino glorioso.\n\n¿No te tengo a ti en el cielo?\nY contigo, ¿qué me importa la tierra?\nSe consumen mi corazón y mi carne\npor Dios, mi lote perpetuo.\n\nSí: los que se alejan de ti se pierden;\ntú destruyes a los que te son infieles.\n\nPara mí lo bueno es estar junto a Dios,\nhacer del Señor mi refugio,\ny contar todas tus acciones\nen las puertas de Sion.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"73":[{"r":"","t":"¿Por qué, oh Dios, nos tienes siempre abandonados,\ny está ardiendo tu cólera contra las ovejas de tu rebaño?\n\nAcuérdate de la comunidad que adquiriste desde antiguo,\nde la tribu que rescataste para posesión tuya,\ndel monte Sion donde pusiste tu morada.\n\nDirige tus pasos a estas ruinas sin remedio;\nel enemigo ha arrasado del todo el santuario.\nRugían los agresores en medio de tu asamblea,\nlevantaron sus propios estandartes.\n\nEn la entrada superior \nabatieron a hachazos el entramado;\ndespués, con martillos y mazas,\ndestrozaron todas las esculturas.\n\nPrendieron fuego a tu santuario,\nderribaron y profanaron la morada de tu nombre.\nPensaban: \"Acabaremos con ellos\",\ne incendiaron todos los templos del país.\n\nYa no vemos nuestros signos, ni hay profeta:\nnadie entre nosotros sabe hasta cuándo.\n\n¿Hasta cuándo, oh Dios, nos va a afrentar el enemigo?\n¿No cesará de despreciar tu nombre el adversario?\n¿Por qué retraes tu mano izquierda \ny tienes tu derecha escondida en el pecho?\n\nPero tú, Dios mío, eres rey desde siempre,\ntú ganaste la victoria en medio de la tierra.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Tú hendiste con fuerza el mar,\nrompiste la cabeza del dragón marino;\ntú aplastaste la cabeza del Leviatán,\nse la echaste en pasto a las bestias del mar;\ntú alumbraste manantiales y torrentes,\ntú secaste ríos inagotables.\n\nTuyo es el día, tuya la noche,\ntú colocaste la luna y el sol;\ntú plantaste los linderos del orbe,\ntú formaste el verano y el invierno.\n\nTenlo en cuenta, Señor, que el enemigo te ultraja,\nque un pueblo insensato desprecia tu nombre;\nno entregues a los buitres la vida de tu tórtola,\nni olvides sin remedio la vida de los pobres.\n\nPiensa en tu alianza: que los rincones del país\nestán llenos de violencias.\nQue el humilde no se marche defraudado,\nque pobres y afligidos alaben tu nombre.\n\nLevántate, oh Dios, defiende tu causa:\nrecuerda los ultrajes continuos del insensato;\nno olvides las voces de tus enemigos,\nel tumulto creciente de los rebeldes contra ti.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"74":[{"r":"","t":"Te damos gracias, oh Dios, te damos gracias,\ninvocando tu nombre, contando tus maravillas.\n\n«Cuando elija la ocasión,\nyo juzgaré rectamente.\nAunque tiemble la tierra con sus habitantes,\nyo he afianzado sus columnas.»\n\nDigo a los jactanciosos: «No jactaros»;\na los malvados: «No alcéis la testuz,\nno alcéis la testuz contra el cielo,\nno digáis insolencias contra la Roca.»\n\nNi del oriente ni del occidente,\nni del desierto ni de los montes,\nsólo Dios gobierna:\na uno humilla, a otro ensalza.\n\nEl Señor tiene una copa en la mano,\nun vaso lleno de vino drogado:\nlo da a beber hasta las heces\na todos los malvados de la tierra.\n\nPero yo siempre proclamaré su grandeza,\ny tañeré para el Dios de Jacob:\nderribaré el poder de los malvados,\ny se alzará el poder del justo.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"75":[{"r":"","t":"Dios se manifiesta en Judá,\nsu fama es grande en Israel;\nsu tabernáculo está en Jerusalén,\nsu morada en Sion:\nallí quebró los relámpagos del arco,\nel escudo, la espada y la guerra.\n\nTú eres deslumbrante, magnífico,\ncon montones de botín conquistados.\nLos valientes duermen su sueño,\ny a los guerreros no les responden sus brazos.\nCon un bramido, oh Dios de Jacob,\ninmovilizaste carros y caballos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Tú eres terrible: ¿quién resiste frente a ti\nal ímpetu de tu ira?\nDesde el cielo proclamas la sentencia:\nla tierra teme sobrecogida,\ncuando Dios se pone en pie para juzgar,\npara salvar a los humildes de la tierra.\n\nLa cólera humana tendrá que alabarte,\nlos que sobrevivan al castigo te rodearán.\nHaced votos al Señor y cumplidlos,\ny traigan los vasallos tributo al Temible:\nÉl deja sin aliento a los príncipes,\ny es temible para los reyes del orbe.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Dios se manifiesta en Judá,\nsu fama es grande en Israel;\nsu tabernáculo está en Jerusalén,\nsu morada en Sion:\nallí quebró los relámpagos del arco,\nel escudo, la espada y la guerra.\n\nTú eres deslumbrante, magnífico,\ncon montones de botín conquistados.\nLos valientes duermen su sueño,\ny a los guerreros no les responden sus brazos.\nCon un bramido, oh Dios de Jacob,\ninmovilizaste carros y caballos.\n\nTú eres terrible: ¿quién resiste frente a ti\nal ímpetu de tu ira?\nDesde el cielo proclamas la sentencia:\nla tierra teme sobrecogida,\ncuando Dios se pone en pie para juzgar,\npara salvar a los humildes de la tierra.\n\nLa cólera humana tendrá que alabarte,\nlos que sobrevivan al castigo te rodearán.\nHaced votos al Señor y cumplidlos,\ny traigan los vasallos tributo al Temible:\nÉl deja sin aliento a los príncipes,\ny es temible para los reyes del orbe.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"76":[{"r":"","t":"Alzo mi voz a Dios gritando,\nalzo mi voz a Dios para que me oiga.\n\nEn mi angustia te busco, Señor mío;\nde noche extiendo las manos sin descanso,\ny mi alma rehúsa el consuelo.\nCuando me acuerdo de Dios, gimo,\ny meditando me siento desfallecer.\n\nSujetas los párpados de mis ojos,\ny la agitación no me deja hablar.\nRepaso los días antiguos,\nrecuerdo los años remotos;\nde noche lo pienso en mis adentros,\ny meditándolo me pregunto:\n\n\"¿Es que el Señor nos rechaza para siempre\ny ya no volverá a favorecernos?\n¿Se ha agotado ya su misericordia,\nse ha terminado para siempre su promesa?\n¿Es que Dios se ha olvidado de su bondad,\no la cólera cierra sus entrañas?\"\n\nY me digo: \"¡Qué pena la mía!\n¡Se ha cambiado la diestra del Altísimo!\"\nRecuerdo las proezas del Señor;\nsí, recuerdo tus antiguos portentos,\nmedito todas tus obras\ny considero tus hazañas.\n\nDios mío, tus caminos son santos:\n¿qué dios es grande como nuestro Dios?\n\nTú, oh Dios, haciendo maravillas,\nmostraste tu poder a los pueblos;\ncon tu brazo rescataste a tu pueblo,\na los hijos de Jacob y de José.\n\nTe vio el mar, oh Dios,\nte vio el mar y tembló,\nlas olas se estremecieron.\n\nLas nubes descargaban sus aguas,\nretumbaban los nubarrones,\ntus saetas zigzagueaban.\n\nRodaba el estruendo de tu trueno,\nlos relámpagos deslumbraban el orbe,\nla tierra retembló estremecida.\n\nTú te abriste camino por las aguas,\nun vado por las aguas caudalosas,\ny no quedaba rastro de tus huellas:\n\nmientras guiabas a tu pueblo, como a un rebaño,\npor la mano de Moisés y de Aarón.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"77":[{"r":"1-39-","t":"Escucha, pueblo mío, mi enseñanza,\ninclina el oído a las palabras de mi boca:\nque voy a abrir mi boca a las sentencias,\npara que broten los enigmas del pasado.\n\nLo que oímos y aprendimos,\nlo que nuestros padres nos contaron,\nno lo ocultaremos a sus hijos,\nlo contaremos a la futura generación:\n\nlas alabanzas del Señor, su poder,\nlas maravillas que realizó;\nporque él estableció una norma para Jacob,\ndio una ley a Israel.\n\nÉl mandó a nuestros padres\nque lo enseñaran a sus hijos,\npara que lo supiera la generación siguiente,\nlos hijos que nacieran después.\n\nQue surjan y lo cuenten a sus hijos,\npara que pongan en Dios su confianza\ny no olviden las acciones de Dios,\nsino que guarden sus mandamientos;\n\npara que no imiten a sus padres,\ngeneración rebelde y pertinaz;\ngeneración de corazón inconstante,\nde espíritu infiel a Dios.\n\nLos arqueros de la tribu de Efraín\nvolvieron la espalda en la batalla;\nno guardaron la alianza de Dios,\nse negaron a seguir su ley,\n\nechando en olvido sus acciones,\nlas maravillas que les había mostrado,\ncuando hizo portentos a vista de sus padres,\nen el país de Egipto, en el campo de Soán:\n\nhendió el mar para abrirles paso,\nsujetando las aguas como muros;\nlos guiaba de día con una nube,\nla noche con el resplandor del fuego;\n\nhendió la roca en el desierto,\ny les dio a beber raudales de agua;\nsacó arroyos de la peña,\nhizo correr las aguas como ríos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"40-72-","t":"¡Qué rebeldes fueron en el desierto,\nenojando a Dios en la estepa!\nVolvían a tentar a Dios,\na irritar al santo de Israel,\nsin acordarse de aquella mano\nque un día los rescató de la opresión:\n\ncuando hizo prodigios en Egipto,\nportentos en el campo de Soán;\ncuando convirtió en sangre los canales\ny los arroyos, para que no bebieran;\n\ncuando les mandó tábanos que les picasen,\ny ranas que los hostigasen;\ncuando entregó a la langosta sus cosechas,\ny al saltamontes el fruto de sus sudores;\n\ncuando aplastó con granizo sus viñedos,\ny con escarcha sus higueras;\ncuando entregó sus ganados al pedrisco,\ny al rayo sus rebaños;\n\ncuando lanzó contra ellos el incendio de su ira,\nsu cólera, su furor, su indignación\ny, despachando a los siniestros mensajeros,\ndio curso libre a su ira:\n\nno los salvó de la muerte,\nentregó sus vidas a la peste;\ncuando hirió a los primogénitos de Egipto,\na las primicias de la virilidad en las tiendas de Cam.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"78":[{"r":"1-5","t":"Dios mío, los gentiles han entrado en tu heredad,\nhan profanado tu santo templo,\nhan reducido Jerusalén a ruinas.\n\nEcharon los cadáveres de tus siervos\nen pasto a las aves del cielo,\ny la carne de tus fieles\na las fieras de la tierra.\n\nDerramaron su sangre como agua\nen torno a Jerusalén,\ny nadie la enterraba.\n\nFuimos el escarnio de nuestros vecinos,\nla irrisión y la burla de los que nos rodean.\n\n¿Hasta cuándo, Señor?\n¿Vas a estar siempre enojado?\n¿Arderá como fuego tu cólera?\n\nNo recuerdes contra nosotros\nlas culpas de nuestros padres;\nque tu compasión nos alcance pronto,\npues estamos agotados.\n\nSocórrenos, Dios, Salvador nuestro,\npor el honor de tu nombre;\nlíbranos y perdona nuestros pecados\na causa de tu nombre.\n\n¿Por qué han de decir los gentiles:\n\"¿Dónde está su Dios\"?\nQue a nuestra vista conozcan los gentiles la venganza\nde la sangre de tus siervos derramada.\n\nLlegue a tu presencia el gemido del cautivo:\ncon tu brazo poderoso, salva a los condenados a muerte.\n\nMientras, nosotros, pueblo tuyo,\novejas de tu rebaño,\nte daremos gracias siempre,\ncantaremos tus alabanzas\nde generación en generación.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"79":[{"r":"","t":"Pastor de Israel, escucha,\ntú que guías a José como a un rebaño;\ntú que te sientas sobre querubines, resplandece\nante Efraín, Benjamín y Manasés;\ndespierta tu poder y ven a salvarnos.\n\nOh Dios, restáuranos,\nque brille tu rostro y nos salve.\n\nSeñor, Dios de los ejércitos,\n¿hasta cuándo estarás airado\nmientras tu pueblo te suplica?\n\nLes diste a comer llanto,\na beber lágrimas a tragos;\nnos entregaste a las contiendas de nuestros vecinos,\nnuestros enemigos se burlan de nosotros.\n\nDios de los ejércitos, restáuranos,\nque brille tu rostro y nos salve.\n\nSacaste una vid de Egipto,\nexpulsaste a los gentiles, y la trasplantaste;\nle preparaste el terreno, y echó raíces\nhasta llenar el país;\n\nsu sombra cubría las montañas,\ny sus pámpanos, los cedros altísimos;\nextendió sus sarmientos hasta el mar,\ny sus brotes hasta el Gran Río.\n\n¿Por qué has derribado su cerca\npara que la saqueen los viandantes,\nla pisoteen los jabalíes\ny se la coman las alimañas?\n\nDios de los ejércitos, vuélvete:\nmira desde el cielo, fíjate,\nven a visitar tu viña,\nla cepa que tu diestra plantó,\ny que tú hiciste vigorosa.\n\nLa han talado y le han prendido fuego;\ncon un bramido hazlos perecer.\nQue tu mano proteja a tu escogido,\nal hombre que tú fortaleciste.\nNo nos alejaremos de ti:\ndanos vida, para que invoquemos tu nombre.\n\nSeñor, Dios de los ejércitos, restáuranos,\nque brille tu rostro y nos salve.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"80":[{"r":"","t":"Aclamad a Dios, nuestra fuerza;\ndad vítores al Dios de Jacob:\n\nacompañad, tocad los panderos,\nlas cítaras templadas y las arpas;\ntocad la trompeta por la luna nueva,\npor la luna llena, que es nuestra fiesta.\n\nPorque es una ley de Israel,\nun precepto del Dios de Jacob,\nuna norma establecida para José\nal salir de Egipto.\n\nOigo un lenguaje desconocido:\n\"Retiré sus hombros de la carga,\ny sus manos dejaron la espuerta.\n\nClamaste en la aflicción, y te libré,\nte respondí oculto entre los truenos,\nte puse a prueba junto a la fuente de Meribá.\n\nEscucha, pueblo mío, doy testimonio contra ti;\n¡ojalá me escuchases, Israel!\n\nNo tendrás un dios extraño,\nno adorarás un dios extranjero;\nyo soy el Señor, Dios tuyo,\nque te saqué del país de Egipto;\nabre la boca que te la llene.\"\n\nPero mi pueblo no escuchó mi voz,\nIsrael no quiso obedecer:\nlos entregué a su corazón obstinado,\npara que anduviesen según sus antojos.\n\n¡Ojalá me escuchase mi pueblo\ny caminase Israel por mi camino!:\nen un momento humillaría a sus enemigos\ny volvería mi mano contra sus adversarios;\n\nlos que aborrecen al Señor te adularían,\ny su suerte quedaría fijada;\nte alimentaría con flor de harina,\nte saciaría con miel silvestre.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"81":[{"r":"","t":"Dios se levanta en la asamblea divina;\nrodeado de ángeles, juzga:\n\"¿Hasta cuándo daréis sentencia injusta,\nponiéndoos de parte del culpable?\n\nProteged al desvalido y al huérfano,\nhaced justicia al humilde y al necesitado,\ndefended al pobre y al indigente,\nsacándolos de las manos del culpable.\"\n\nEllos, ignorantes e insensatos, caminan a oscuras,\nmientras vacilan los cimientos del orbe.\n\nYo declaro: \"Aunque seáis dioses, \ne hijos del Altísimo todos,\nmoriréis como cualquier hombre,\ncaeréis, príncipes, como uno de tantos.\"\n\nLevántate, oh Dios, y juzga la tierra,\nporque tú eres el dueño de todos los pueblos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"83":[{"r":"","t":"¡Qué deseables son tus moradas,\nSeñor de los ejércitos!\nMi alma se consume y anhela\nlos atrios del Señor,\nmi corazón y mi carne\nretozan por el Dios vivo.\n\nHasta el gorrión ha encontrado una casa;\nla golondrina, un nido\ndonde colocar sus polluelos:\ntus altares, Señor de los ejércitos,\nRey mío y Dios mío.\n\nDichosos los que viven en tu casa,\nalabándote siempre.\nDichosos los que encuentran en ti su fuerza\nal preparar su peregrinación:\n\nCuando atraviesan áridos valles,\nlos convierten en oasis,\ncomo si la lluvia temprana\nlos cubriera de bendiciones;\ncaminan de baluarte en baluarte\nhasta ver a Dios en Sion.\n\nSeñor de los ejércitos, escucha mi súplica;\natiéndeme, Dios de Jacob.\nFíjate, oh Dios, en nuestro Escudo,\nmira el rostro de tu Ungido.\n\nVale más un día en tus atrios \nque mil en mi casa,\ny prefiero el umbral de la casa de Dios\na vivir con los malvados.\n\nPorque el Señor es sol y escudo,\nél da la gracia y la gloria;\nel Señor no niega sus bienes\na los de conducta intachable.\n\n¡Señor de los ejércitos, dichoso el hombre\nque confía en ti!\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"84":[{"r":"","t":"Señor, has sido bueno con tu tierra,\nhas restaurado la suerte de Jacob,\nhas perdonado la culpa de tu pueblo,\nhas sepultado todos sus pecados,\nhas reprimido tu cólera,\nhas frenado el incendio de tu ira.\n\nRestáuranos, Dios Salvador nuestro;\ncesa en tu rencor contra nosotros.\n¿Vas a estar siempre enojado,\no a prolongar tu ira de edad en edad?\n\n¿No vas a devolvernos la vida,\npara que tu pueblo se alegre contigo?\nMuéstranos, Señor, tu misericordia,\ny danos tu salvación.\n\nVoy a escuchar lo que dice el Señor:\n«Dios anuncia la paz\na su pueblo y a sus amigos\ny a los que se convierten de corazón.»\n\nLa salvación está ya cerca de sus fieles,\ny la gloria habitará en nuestra tierra;\nla misericordia y la fidelidad se encuentran,\nla justicia y la paz se besan;\n\nLa fidelidad brota de la tierra,\ny la justicia mira desde el cielo;\nel Señor nos dará la lluvia,\ny nuestra tierra dará su fruto.\n\nLa justicia marchará ante él,\nla salvación seguirá sus pasos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"85":[{"r":"","t":"Inclina tu oído, Señor, escúchame,\nque soy un pobre desamparado;\nprotege mi vida, que soy un fiel tuyo;\nsalva a tu siervo, que confía en ti.\n\nTú eres mi Dios, piedad de mí, Señor,\nque a ti te estoy llamando todo el día;\nalegra el alma de tu siervo,\npues levanto mi alma hacia ti;\n\nporque tú, Señor, eres bueno y clemente,\nrico en misericordia con los que te invocan.\nSeñor, escucha mi oración,\natiende a la voz de mi súplica.\n\nEn el día del peligro te llamo, \ny tú me escuchas.\nNo tienes igual entre los dioses, Señor,\nni hay obras como las tuyas.\n\nTodos los pueblos vendrán \na postrarse en tu presencia, Señor;\nbendecirán tu nombre:\n«Grande eres tú, y haces maravillas;\ntú eres el único Dios.»\n\nEnséñame, Señor, tu camino, \npara que siga tu verdad;\nmantén mi corazón entero\nen el temor de tu nombre.\n\nTe alabaré de todo corazón, Dios mío;\ndaré gloria a tu nombre por siempre,\npor tu gran piedad para conmigo,\nporque me salvaste del abismo profundo.\n\nDios mío, unos soberbios se levantan contra mí,\nuna banda de insolentes atenta contra mi vida,\nsin tenerte en cuenta a ti.\n\nPero tú, Señor, Dios clemente y misericordioso,\nlento a la cólera, rico en piedad y leal,\nmírame, ten compasión de mí.\n\nDa fuerza a tu siervo,\nsalva al hijo de tu esclava;\ndame una señal propicia,\nque la vean mis adversarios y se avergüencen,\nporque tú, Señor, me ayudas y consuelas.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"1-10","t":"Inclina tu oído, Señor, escúchame,\nque soy un pobre desamparado;\nprotege mi vida, que soy un fiel tuyo;\nsalva a tu siervo, que confía en ti.\n\nTú eres mi Dios, piedad de mí, Señor,\nque a ti te estoy llamando todo el día;\nalegra el alma de tu siervo,\npues levanto mi alma hacia tí;\n\nporque tú, Señor, eres bueno y clemente,\nrico en misericordia con los que te invocan.\nSeñor, escucha mi oración,\natiende a la voz de mi súplica.\n\nEn el día del peligro te llamo, \ny tú me escuchas.\nNo tienes igual entre los dioses, Señor,\nni hay obras como las tuyas.\n\nTodos los pueblos vendrán \na postrarse en tu presencia, Señor;\nbendecirán tu nombre:\n\"Grande eres tú, y haces maravillas;\ntú eres el único Dios.\"\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"86":[{"r":"","t":"Él la ha cimentado sobre el monte santo;\ny el Señor prefiere las puertas de Sion\na todas las moradas de Jacob.\n\n¡Qué pregón tan glorioso para ti,\nciudad de Dios!\n«Contaré a Egipto y a Babilonia\nentre mis fieles;\nfilisteos, tirios y etíopes\nhan nacido allí.»\n\nSe dirá de Sion: «Uno por uno\ntodos han nacido en ella;\nel Altísimo en persona la ha fundado.»\n\nEl Señor escribirá en el registro de los pueblos:\n«Este ha nacido allí.»\nY cantarán mientras danzan:\n«Todas mis fuentes están en ti.»\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"87":[{"r":"","t":"Señor, Dios mío, de día te pido auxilio,\nde noche grito en tu presencia;\nllegue hasta ti mi súplica,\ninclina tu oído a mi clamor.\n\nPorque mi alma está colmada de desdichas,\ny mi vida está al borde del abismo;\nya me cuentan con los que bajan a la fosa,\nsoy como un inválido.\n\nTengo mi cama entre los muertos,\ncomo los caídos que yacen en el sepulcro,\nde los cuales ya no guardas memoria,\nporque fueron arrancados de tu mano.\n\nMe has colocado en lo hondo de la fosa,\nen las tinieblas del fondo;\ntu cólera pesa sobre mí,\nme echas encima todas tus olas.\n\nHas alejado de mí a mis conocidos,\nme has hecho repugnante para ellos:\nencerrado, no puedo salir,\ny los ojos se me nublan de pesar.\n\nTodo el día te estoy invocando,\ntendiendo las manos hacia ti.\n¿Harás tú maravillas por los muertos?\n¿Se alzarán las sombras para darte gracias?\n\n¿Se anuncia en el sepulcro tu misericordia,\no tu fidelidad en el reino de la muerte?\n¿Se conocen tus maravillas en la tiniebla,\no tu justicia en el país del olvido?\n\nPero yo te pido auxilio,\npor la mañana irá a tu encuentro mi súplica.\n¿Por qué, Señor, me rechazas,\ny me escondes tu rostro?\n\nDesde niño fui desgraciado y enfermo,\nme doblo bajo el peso de tus terrores,\npasó sobre mí tu incendio,\ntus espantos me han consumido:\n\nme rodean como las aguas todo el día,\nme envuelven todos a una;\nalejaste de mí amigos y compañeros:\nmi compañía son las tinieblas.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Señor, Dios mío, de día te pido auxilio,\nde noche grito en tu presencia;\nllegue hasta ti mi súplica,\ninclina tu oído a mi clamor.\n\nPorque mi alma está colmada de desdichas,\ny mi vida está al borde del abismo;\nya me cuentan con los que bajan a la fosa,\nsoy como un inválido.\n\nTengo mi cama entre los muertos,\ncomo los caídos que yacen en el sepulcro,\nde los cuales ya no guardas memoria,\nporque fueron arrancados de tu mano.\n\nMe has colocado en lo hondo de la fosa,\nen las tinieblas del fondo;\ntu cólera pesa sobre mí,\nme echas encima todas tus olas.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Has alejado de mí a mis conocidos,\nme has hecho repugnante para ellos:\nencerrado, no puedo salir,\ny los ojos se me nublan de pesar.\n\nTodo el día te estoy invocando,\ntendiendo las manos hacia ti.\n¿Harás tú maravillas por los muertos?\n¿Se alzarán las sombras para darte gracias?\n\n¿Se anuncia en el sepulcro tu misericordia,\no tu fidelidad en el reino de la muerte?\n¿Se conocen tus maravillas en la tiniebla,\no tu justicia en el país del olvido?\n\nPero yo te pido auxilio,\npor la mañana irá a tu encuentro mi súplica.\n¿Por qué, Señor, me rechazas\ny me escondes tu rostro?\n\nDesde niño fui desgraciado y enfermo,\nme doblo bajo el peso de tus terrores,\npasó sobre mí tu incendio,\ntus espantos me han consumido:\n\nme rodean como las aguas todo el día,\nme envuelven todos a una;\nalejaste de mí amigos y compañeros:\nmi compañía son las tinieblas.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Señor, Dios mío, de día te pido auxilio,\nde noche grito en tu presencia;\nllegue hasta ti mi súplica,\ninclina tu oído a mi clamor.\n\nPorque mi alma está colmada de desdichas,\ny mi vida está al borde del abismo;\nya me cuentan con los que bajan a la fosa,\nsoy como un inválido.\n\nTengo mi cama entre los muertos,\ncomo los caídos que yacen en el sepulcro,\nde los cuales ya no guardas memoria,\nporque fueron arrancados de tu mano.\n\nMe has colocado en lo hondo de la fosa,\nen las tinieblas del fondo;\ntu cólera pesa sobre mí,\nme echas encima todas tus olas.\n\nHas alejado de mí a mis conocidos,\nme has hecho repugnante para ellos:\nencerrado, no puedo salir,\ny los ojos se me nublan de pesar.\n\nTodo el día te estoy invocando,\ntendiendo las manos hacia ti.\n¿Harás tú maravillas por los muertos?\n¿Se alzarán las sombras para darte gracias?\n\n¿Se anuncia en el sepulcro tu misericordia,\no tu fidelidad en el reino de la muerte?\n¿Se conocen tus maravillas en la tiniebla,\no tu justicia en el país del olvido?\n\nPero yo te pido auxilio,\npor la mañana irá a tu encuentro mi súplica.\n¿Por qué, Señor, me rechazas\ny me escondes tu rostro?\n\nDesde niño fui desgraciado y enfermo,\nme doblo bajo el peso de tus terrores,\npasó sobre mí tu incendio,\ntus espantos me han consumido:\n\nme rodean como las aguas todo el día,\nme envuelven todos a una;\nalejaste de mí amigos y compañeros:\nmi compañía son las tinieblas.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"88":[{"r":"2-38-","t":"Cantaré eternamente las misericordias del Señor,\nanunciaré tu fidelidad por todas las edades.\nPorque dije: «Tu misericordia es un edificio eterno,\nmás que el cielo has afianzado tu fidelidad.»\n\nSellé una alianza con mi elegido,\njurando a David, mi siervo:\n«Te fundaré un linaje perpetuo,\nedificaré tu trono para todas las edades.»\n\nEl cielo proclama tus maravillas, Señor,\ny tu fidelidad, en la asamblea de los ángeles.\n¿Quién sobre las nubes se compara a Dios?\n¿Quién como el Señor entre los seres divinos?\n\nDios es temible en el consejo de los ángeles,\nes grande y terrible para toda su corte.\nSeñor de los ejércitos, ¿quién como tú?\nEl poder y la fidelidad te rodean.\n\nTú domeñas la soberbia del mar\ny amansas la hinchazón del oleaje;\ntú traspasaste y destrozaste a Rahab,\ntu brazo potente desbarató al enemigo.\n\nTuyo es el cielo, tuya es la tierra;\ntú cimentaste el orbe y cuanto contiene;\ntú has creado el norte y el sur,\nel Tabor y el Hermón aclaman tu nombre.\n\nTienes un brazo poderoso:\nfuerte es tu izquierda y alta tu derecha.\nJusticia y derecho sostienen tu trono,\nmisericordia y fidelidad te preceden.\n\nDichoso el pueblo que sabe aclamarte:\ncaminará, oh Señor, a la luz de tu rostro;\ntu nombre es su gozo cada día,\ntu justicia es su orgullo.\n\nPorque tú eres su honor y su fuerza,\ny con tu favor realzas nuestro poder.\nPorque el Señor es nuestro escudo,\ny el Santo de Israel nuestro rey.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"39-53-","t":"Tú, encolerizado con tu Ungido,\nlo has rechazado y desechado;\nhas roto la alianza con tu siervo\ny has profanado hasta el suelo su corona;\n\nhas derribado sus murallas\ny derrocado sus fortalezas;\ntodo viandante lo saquea,\ny es la burla de sus vecinos;\n\nhas sostenido la diestra de sus enemigos\ny has dado el triunfo a sus adversarios;\npero a él le has embotado la espada\ny no lo has confortado en la pelea;\n\nhas quebrado su cetro glorioso\ny has derribado su trono;\nhas acortado los días de su juventud\ny lo has cubierto de ignominia.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"89":[{"r":"","t":"Señor, tú has sido nuestro refugio\nde generación en generación.\n\nAntes que naciesen los montes\no fuera engendrado el orbe de la tierra,\ndesde siempre y por siempre tú eres Dios.\n\nTú reduces el hombre a polvo,\ndiciendo: «Retornad, hijos de Adán.»\nMil años en tu presencia\nson un ayer, que pasó;\nuna vela nocturna.\n\nLos siembras año por año,\ncomo hierba que se renueva:\nque florece y se renueva por la mañana,\ny por la tarde la siegan y se seca.\n\n¡Cómo nos ha consumido tu cólera\ny nos ha trastornado tu indignación!\nPusiste nuestras culpas ante ti,\nnuestros secretos ante la luz de tu mirada:\ny todos nuestros días pasaron bajo tu cólera,\ny nuestros años se acabaron como un suspiro.\n\nAunque uno viva setenta años,\ny el más robusto hasta ochenta,\nla mayor parte son fatiga inútil,\nporque pasan aprisa y vuelan.\n\n¿Quién conoce la vehemencia de tu ira,\nquién ha sentido el peso de tu cólera?\nEnséñanos a calcular nuestros años,\npara que adquiramos un corazón sensato.\n\nVuélvete, Señor, ¿hasta cuándo?\nTen compasión de tus siervos;\npor la mañana sácianos de tu misericordia,\ny toda nuestra vida será alegría y júbilo.\n\nDanos alegría, por los días en que nos afligiste,\npor los años en que sufrimos desdichas.\nQue tus siervos vean tu acción\ny sus hijos tu gloria.\n\nBaje a nosotros la bondad del Señor\ny haga prósperas las obras de nuestras manos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"90":[{"r":"","t":"Tú que habitas al Amparo del Altísimo,\nque vives a la sombra del Omnipotente,\ndi al Señor: \"Refugio mío, alcázar mío,\nDios mío, confío en ti.\"\n\nÉl te librará de la red del cazador,\nde la peste funesta.\nTe cubrirá con sus plumas,\nbajo sus alas te refugiarás:\nsu brazo es escudo y armadura.\n\nNo temerás el espanto nocturno,\nni la flecha que vuela de día,\nni la peste que se desliza en las tinieblas,\nni la epidemia que devasta a mediodía.\n\nCaerán a tu izquierda mil,\ndiez mil a tu derecha;\na ti no te alcanzará.\n\nNada más mirar con tus ojos,\nverás la paga de los malvados,\nporque hiciste del Señor tu refugio,\ntomaste al Altísimo por defensa.\n\nNo se te acercará la desgracia,\nni la plaga llegará hasta tu tienda,\nporque a sus ángeles ha dado órdenes\npara que te guarden en tus caminos;\n\nte llevarán en sus palmas,\npara que tu pie no tropiece en la piedra;\ncaminarás sobre áspides y víboras,\npisotearás leones y dragones.\n\n\"Se puso junto a mí: lo libraré;\nlo protegeré porque conoce mi nombre,\nme invocará y lo escucharé.\n\nCon él estaré en la tribulación,\nlo defenderé, lo glorificaré,\nlo saciaré de largos días\ny le haré ver mi salvación.\"\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"91":[{"r":"","t":"Es bueno dar gracias al Señor\ny tocar para tu nombre, oh Altísimo,\nproclamar por la mañana tu misericordia\ny de noche tu fidelidad,\ncon arpas de diez cuerdas y laúdes,\nsobre arpegios de cítaras.\n\nTus acciones, Señor, son mi alegría,\ny mi júbilo, las obras de tus manos.\n¡Qué magníficas son tus obras, Señor,\nqué profundos tus designios!\nEl ignorante no los entiende\nni el necio se da cuenta.\n\nAunque germinen como hierba los malvados\ny florezcan los malhechores,\nserán destruidos para siempre.\nTú, en cambio, Señor, \neres excelso por los siglos.\n\nPorque tus enemigos, Señor, perecerán,\nlos malhechores serán dispersados;\npero a mí me das la fuerza de un búfalo\ny me unges con aceite nuevo.\nMis ojos despreciarán a mis enemigos,\nmis oídos escucharán su derrota.\n\nEl justo crecerá como una palmera,\nse alzará como un cedro del Líbano:\nplantado en la casa del Señor,\ncrecerá en los atrios de nuestro Dios;\n\nen la vejez seguirá dando fruto\ny estará lozano y frondoso,\npara proclamar que el Señor es justo,\nque en mi Roca no existe la maldad.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Es bueno dar gracias al Señor\ny tocar para tu nombre, oh Altísimo,\nproclamar por la mañana tu misericordia\ny de noche tu fidelidad,\ncon arpas de diez cuerdas y laúdes,\nsobre arpegios de cítaras.\n\nTus acciones, Señor, son mi alegría,\ny mi júbilo, las obras de tus manos.\n¡Qué magníficas son tus obras, Señor,\nqué profundos tus designios!\nEl ignorante no los entiende\nni el necio se da cuenta.\n\nAunque germinen como hierba los malvados\ny florezcan los malhechores,\nserán destruidos para siempre.\nTú, en cambio, Señor, \neres excelso por los siglos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Porque tus enemigos, Señor, perecerán,\nlos malhechores serán dispersados;\npero a mí me das la fuerza de un búfalo\ny me unges con aceite nuevo.\nMis ojos despreciarán a mis enemigos,\nmis oídos escucharán su derrota.\n\nEl justo crecerá como una palmera,\nse alzará como un cedro del Líbano:\nplantado en la casa del Señor,\ncrecerá en los atrios de nuestro Dios;\n\nen la vejez seguirá dando fruto\ny estará lozano y frondoso,\npara proclamar que el Señor es justo,\nque en mi Roca no existe la maldad.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"92":[{"r":"","t":"El Señor reina, vestido de majestad,\nel Señor, vestido y ceñido de poder:\nasí está firme el orbe y no vacila.\n\nTu trono está firme desde siempre, \ny tú eres eterno.\n\nLevantan los ríos, Señor,\nlevantan los ríos su voz,\nlevantan los ríos su fragor;\n\npero más que la voz de aguas caudalosas,\nmás potente que el oleaje del mar,\nmás potente en el cielo es el Señor.\n\nTus mandatos son fieles y seguros;\nla santidad es el adorno de tu casa,\nSeñor, por días sin término.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"93":[{"r":"","t":"Dios de la venganza, Señor,\nDios de la venganza, resplandece.\nLevántate, juzga la tierra,\npaga su merecido a los soberbios.\n\n¿Hasta cuándo, Señor, los culpables,\nhasta cuándo triunfarán los culpables?\nDiscursean profiriendo insolencias,\nse jactan los malhechores;\n\ntrituran, Señor, a tu pueblo,\noprimen a tu heredad;\nasesinan a viudas y forasteros, \ndegüellan a los huérfanos,\ny comentan: \"Dios no lo ve,\nel Dios de Jacob no se entera\".\n\nEnteraos, los más necios del pueblo,\nignorantes, ¿cuándo discurriréis?\nEl que plantó el oído ¿no va a oír?\nEl que formó el ojo ¿no va a ver?\n\nEl que educa a los pueblos ¿no va a castigar?\nEl que instruye al hombre ¿no va a saber?\nSabe el Señor que los pensamientos del hombre\nson insustanciales.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Dichoso el hombre a quien tú educas,\nal que enseñas tu ley,\ndándole descanso tras los años duros,\nmientras al malvado le cavan la fosa.\n\nPorque el Señor no rechaza a su pueblo,\nni abandona su heredad:\nel justo obtendrá su derecho,\ny un porvenir los rectos de corazón.\n\n¿Quién se pone a mi favor contra los perversos,\nquién se coloca a mi lado frente a los malhechores?\nSi el Señor no me hubiera auxiliado,\nya estaría yo habitando en el silencio.\n\nCuando me parece que voy a tropezar,\ntu misericordia, Señor, me sostiene;\ncuando se multiplican mis preocupaciones,\ntus consuelos son mi delicia.\n\n¿Podrá aliarse contigo un tribunal inicuo\nque dicta injusticias en nombre de la ley?\n\nAunque atenten contra la vida del justo\ny condenen a muerte al inocente,\nel Señor será mi alcázar,\nDios será mi roca de refugio.\n\nÉl les pagará su iniquidad,\nlos destruirá por sus maldades,\nlos destruirá el Señor, nuestro Dios.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"94":[{"r":"","t":"Venid, aclamemos al Señor,\ndemos vítores a la Roca que nos salva;\nentremos a su presencia dándole gracias,\naclamándolo con cantos.\n Se repite la antífonaPorque el Señor es un Dios grande,\nsoberano de todos los dioses:\ntiene en su mano las simas de la tierra,\nson suyas las cumbres de los montes.\nSuyo es el mar, porque él lo hizo,\nla tierra firme que modelaron sus manos\n\nSe repite la antífonaEntrad, postrémonos por tierra,\nbendiciendo al Señor, creador nuestro.\nPorque él es nuestro Dios,\ny nosotros su pueblo,\nel rebaño que él guía.\nSe repite la antífonaOjalá escuchéis hoy su voz:\n«No endurezcáis el corazón como en Meribá,\ncomo el día de Masá en el desierto;\ncuando vuestros padres me pusieron a prueba,\ny me tentaron, aunque habían visto mis obras.\nSe repite la antífonaDurante cuarenta años\naquella generación me asqueó, y dije:\n\"Es un pueblo de corazón extraviado,\nque no reconoce mi camino;\npor eso he jurado en mi cólera\nque no entrarán en mi descanso.\"»\nSe repite la antífonaGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"95":[{"r":"","t":"Cantad al Señor un cántico nuevo,\ncantad al Señor, toda la tierra;\ncantad al Señor, bendecid su nombre,\nproclamad día tras día su victoria.\n\nContad a los pueblos su gloria,\nsus maravillas a todas las naciones;\nporque es grande el Señor, y muy digno de alabanza,\nmás temible que todos los dioses.\n\nPues los dioses de los gentiles son apariencia,\nmientras que el Señor ha hecho el cielo;\nhonor y majestad lo preceden,\nfuerza y esplendor están en su templo.\n\nFamilias de los pueblos, aclamad al Señor,\naclamad la gloria y el poder del Señor,\naclamad la gloria del nombre del Señor,\nentrad en sus atrios trayéndole ofrendas.\n\nPostraos ante el Señor en el atrio sagrado,\ntiemble en su presencia la tierra toda;\ndecid a los pueblos: «El Señor es rey,\nél afianzó el orbe, y no se moverá;\nél gobierna a los pueblos rectamente».\n\nAlégrese el cielo, goce la tierra,\nretumbe el mar y cuanto lo llena;\nvitoreen los campos y cuanto hay en ellos,\naclamen los árboles del bosque,\n\ndelante del Señor, que ya llega,\nya llega a regir la tierra:\nregirá el orbe con justicia\ny los pueblos con fidelidad.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Cantad al Señor un cántico nuevo,\ncantad al Señor, toda la tierra;\ncantad al Señor, bendecid su nombre,\nproclamad día tras día su victoria.\n\nContad a los pueblos su gloria,\nsus maravillas a todas las naciones;\nporque es grande el Señor, y muy digno de alabanza,\nmás temible que todos los dioses.\n\nPues los dioses de los gentiles son apariencia,\nmientras que el Señor ha hecho el cielo;\nhonor y majestad lo preceden,\nfuerza y esplendor están en su templo.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Familias de los pueblos, aclamad al Señor,\naclamad la gloria y el poder del Señor,\naclamad la gloria del nombre del Señor,\nentrad en sus atrios trayéndole ofrendas.\n\nPostraos ante el Señor en el atrio sagrado,\ntiemble en su presencia la tierra toda;\ndecid a los pueblos: \"el Señor es rey,\nél afianzó el orbe, y no se moverá;\nél gobierna a los pueblos rectamente\".\n\nAlégrese el cielo, goce la tierra,\nretumbe el mar y cuanto lo llena;\nvitoreen los campos y cuanto hay en ellos,\naclamen los árboles del bosque,\n\ndelante del Señor, que ya llega,\nya llega a regir la tierra:\nregirá el orbe con justicia\ny los pueblos con fidelidad.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"96":[{"r":"","t":"El Señor reina, la tierra goza,\nse alegran las islas innumerables.\nTiniebla y nube lo rodean,\njusticia y derecho sostienen su trono.\n\nDelante de él avanza fuego,\nabrasando en torno a los enemigos;\nsus relámpagos deslumbran el orbe,\ny, viéndolos, la tierra se estremece.\n\nLos montes se derriten como cera \nante el dueño de toda la tierra;\nlos cielos pregonan su justicia,\ny todos los pueblos contemplan su gloria.\n\nLos que adoran estatuas se sonrojan,\nlos que ponen su orgullo en los ídolos;\nante él se postran todos los dioses.\n\nLo oye Sion, y se alegra, \nse regocijan las ciudades de Judá\npor tus sentencias, Señor;\n\nporque tú eres, Señor, \naltísimo sobre toda la tierra,\nencumbrado sobre todos los dioses.\n\nEl Señor ama al que aborrece el mal,\nprotege la vida de sus fieles\ny los libra de los malvados.\n\nAmanece la luz para el justo,\ny la alegría para los rectos de corazón.\nAlegraos, justos, con el Señor,\ncelebrad su santo nombre.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"97":[{"r":"","t":"Cantad al Señor un cántico nuevo,\nporque ha hecho maravillas:\nsu diestra le ha dado la victoria,\nsu santo brazo.\n\nEl Señor da a conocer su victoria,\nrevela a las naciones su justicia:\nse acordó de su misericordia y su fidelidad\nen favor de la casa de Israel.\n\nLos confines de la tierra han contemplado \nla victoria de nuestro Dios.\nAclama al Señor, tierra entera;\ngritad, vitoread, tocad:\n\ntañed la cítara para el Señor,\nsuenen los instrumentos:\ncon clarines y al son de trompetas,\naclamad al Rey y Señor.\n\nRetumbe el mar y cuanto contiene,\nla tierra y cuantos la habitan;\naplaudan los ríos, aclamen los montes\nal Señor, que llega para regir la tierra.\n\nRegirá el orbe con justicia\ny los pueblos con rectitud.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"98":[{"r":"","t":"El Señor reina, tiemblen las naciones;\nsentado sobre querubines, vacile la tierra.\n\nEl Señor es grande en Sion,\nencumbrado sobre todos los pueblos.\nReconozcan tu nombre, grande y terrible:\nÉl es santo.\n\nReinas con poder y amas la justicia,\ntú has establecido la rectitud;\ntú administras la justicia y el derecho,\ntú actúas en Jacob.\n\nEnsalzad al Señor, Dios nuestro,\npostraos ante el estrado de sus pies:\nÉl es santo.\n\nMoisés y Aarón con sus sacerdotes,\nSamuel con los que invocan su nombre,\ninvocaban al Señor, y él respondía.\nDios les hablaba desde la columna de nube;\noyeron sus mandatos y la ley que les dio.\n\nSeñor, Dios nuestro, tú les respondías,\ntú eras para ellos un Dios de perdón,\ny un Dios vengador de sus maldades.\n\nEnsalzad al Señor, Dios nuestro;\npostraos ante su monte santo:\nSanto es el Señor, nuestro Dios.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"99":[{"r":"","t":"Aclama al Señor, tierra entera,\nservid al Señor con alegría,\nentrad en su presencia con vítores.\n Se repite la antífonaSabed que el Señor es Dios:\nque Él nos hizo y somos suyos,\nsu pueblo y ovejas de su rebaño.\nSe repite la antífonaEntrad por sus puertas con acción de gracias,\npor sus atrios con himnos,\ndándole gracias y bendiciendo su nombre:\nSe repite la antífona«El Señor es bueno,\nsu misericordia es eterna,\nsu fidelidad por todas las edades»\nSe repite la antífonaGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Aclama al Señor, tierra entera,\nservid al Señor con alegría, \nentrad en su presencia con vítores.\n\nSabed que el Señor es Dios:\nque él nos hizo y somos suyos,\nsu pueblo y ovejas de su rebaño.\n\nEntrad por sus puertas con acción de gracias,\npor sus atrios con himnos,\ndándole gracias y bendiciendo su nombre:\n\n«El Señor es bueno,\nsu misericordia es eterna,\nsu fidelidad por todas las edades»\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"100":[{"r":"","t":"Voy a cantar la bondad y la justicia,\npara ti es mi música, Señor;\nvoy a explicar el camino perfecto:\n¿cuándo vendrás a mí?\n\nAndaré con rectitud de corazón\ndentro de mi casa;\nno pondré mis ojos\nen intenciones viles.\n\nAborrezco al que obra mal, \nno se juntará conmigo;\nlejos de mí el corazón torcido,\nno aprobaré al malvado.\n\nAl que en secreto difama a su prójimo\nlo haré callar;\nojos engreídos, corazones arrogantes\nno los soportaré.\n\nPongo mis ojos en los que son leales,\nellos vivirán conmigo;\nel que sigue un camino perfecto,\nese me servirá.\n\nNo habitará en mi casa\nquien comete fraudes;\nel que dice mentiras\nno durará en mi presencia.\n\nCada mañana haré callar\na los hombres malvados,\npara excluir de la ciudad del Señor\na todos los malhechores.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"101":[{"r":"","t":"Señor, escucha mi oración,\nque mi grito llegue hasta ti;\nno me escondas tu rostro\nel día de la desgracia.\nInclina tu oído hacia mí;\ncuando te invoco, escúchame enseguida.\n\nQue mis días se desvanecen como humo,\nmis huesos queman como brasas;\nmi corazón está agostado como hierba,\nme olvido de comer mi pan;\ncon la violencia de mis quejidos,\nse me pega la piel a los huesos.\n\nEstoy como lechuza en la estepa,\ncomo búho entre ruinas;\nestoy desvelado, gimiendo,\ncomo pájaro sin pareja en el tejado.\nMis enemigos me insultan sin descanso;\nfuriosos contra mí, me maldicen.\n\nEn vez de pan, como ceniza,\nmezclo mi bebida con llanto,\npor tu cólera y tu indignación,\nporque me alzaste en vilo y me tiraste;\nmis días son una sombra que se alarga,\nme voy secando como la hierba.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Tú, en cambio, permaneces para siempre,\ny tu nombre de generación en generación.\nLevántate y ten misericordia de Sion,\nque ya es hora y tiempo de misericordia.\n\nTus siervos aman sus piedras,\nse compadecen de sus ruinas,\nlos gentiles temerán tu nombre,\nlos reyes del mundo, tu gloria.\n\nCuando el Señor reconstruya Sion,\ny aparezca en su gloria,\ny se vuelva a las súplicas de los indefensos,\ny no desprecie sus peticiones,\nquede esto escrito para la generación futura,\ny el pueblo que será creado alabará al Señor.\n\nQue el Señor ha mirado desde su excelso santuario,\ndesde el cielo se ha fijado en la tierra,\npara escuchar los gemidos de los cautivos\ny librar a los condenados a muerte.\n\nPara anunciar en Sion el nombre del Señor,\ny su alabanza en Jerusalén,\ncuando se reúnan unánimes los pueblos\ny los reyes para dar culto al Señor.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"III","t":"Él agotó mis fuerzas en el camino,\nacortó mis días;\n\ny yo dije: \"Dios mío, no me arrebates\nen la mitad de mis días.\"\n\nTus años duran por todas las generaciones:\nal principio cimentaste la tierra,\ny el cielo es obra de tus manos.\n\nEllos perecerán, tú permaneces,\nse gastarán como la ropa,\nserán como un vestido que se muda.\nTú, en cambio, eres siempre el mismo,\ntus años no se acabarán.\n\nLos hijos de tus siervos vivirán seguros,\nsu linaje durará en tu presencia.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"102":[{"r":"","t":"Bendice, alma mía, al Señor,\ny todo mi ser a su santo nombre.\nBendice, alma mía, al Señor,\ny no olvides sus beneficios.\n\nÉl perdona todas tus culpas\ny cura todas tus enfermedades;\nÉl rescata tu vida de la fosa,\ny te colma de gracia y de ternura;\nÉl sacia de bienes tus anhelos,\ny como un águila se renueva tu juventud.\n\nEl Señor hace justicia\ny defiende a todos los oprimidos;\nenseñó sus caminos a Moisés \ny sus hazañas a los hijos de Israel.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"El Señor es compasivo y misericordioso,\nlento a la ira y rico en clemencia;\nno está siempre acusando\nni guarda rencor perpetuo;\nno nos trata como merecen nuestros pecados\nni nos paga según nuestras culpas.\n\nComo se levanta el cielo sobre la tierra,\nse levanta su bondad sobre sus fieles;\ncomo dista el oriente del ocaso,\nasí aleja de nosotros nuestros delitos.\n\nComo un padre siente ternura por sus hijos,\nsiente el Señor ternura por sus fieles;\nporque él conoce nuestra masa,\nse acuerda de que somos barro.\n\nLos días del hombre duran lo que la hierba,\nflorecen como flor del campo, \nque el viento la roza, y ya no existe,\nsu terreno no volverá a verla.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"III","t":"Pero la misericordia del Señor dura siempre,\nsu justicia pasa de hijos a nietos:\npara los que guardan la alianza\ny recitan y cumplen sus mandatos.\n\nEl Señor puso en el cielo su trono, \nsu soberanía gobierna el universo.\nBendecid al Señor, ángeles suyos,\npoderosos ejecutores de sus órdenes,\nprontos a la voz de su palabra.\n\nBendecid al Señor, ejércitos suyos, \nservidores que cumplís sus deseos.\nBendecid al Señor, todas sus obras,\nen todo lugar de su imperio.\n\n¡Bendice, alma mía, al Señor!\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"103":[{"r":"","t":"Bendice, alma mía, al Señor:\n¡Dios mío, qué grande eres!\nTe vistes de belleza y majestad,\nla luz te envuelve como un manto.\n\nExtiendes los cielos como una tienda,\nconstruyes tu morada sobre las aguas;\nlas nubes te sirven de carroza,\navanzas en las alas del viento;\nlos vientos te sirven de mensajeros;\nel fuego llameante, de ministro.\n\nAsentaste la tierra sobre sus cimientos,\ny no vacilará jamás;\nla cubriste con el manto del océano,\ny las aguas se posaron sobre las montañas;\n\npero a tu bramido huyeron,\nal fragor de tu trueno se precipitaron,\nmientras subían los montes y bajaban los valles:\ncada cual al puesto asignado. \nTrazaste una frontera que no traspasarán,\ny no volverán a cubrir la tierra.\n\nDe los manantiales sacas los ríos,\npara que fluyan entre los montes;\nen ellos beben las fieras de los campos,\nel asno salvaje apaga su sed;\njunto a ellos habitan las aves del cielo,\ny entre las frondas se oye su canto.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Desde tu morada riegas los montes,\ny la tierra se sacia de tu acción fecunda;\nhaces brotar hierba para los ganados,\ny forraje para los que sirven al hombre.\n\nÉl saca pan de los campos,\ny vino que le alegra el corazón;\ny aceite que da brillo a su rostro,\ny alimento que le da fuerzas.\n\nSe llenan de savia los árboles del Señor,\nlos cedros del Líbano que él plantó:\nallí anidan los pájaros,\nen su cima pone casa la cigüeña.\nLos riscos son para las cabras,\nlas peñas son madriguera de erizos.\n\nHiciste la luna con sus fases,\nel sol conoce su ocaso.\nPones las tinieblas y viene la noche,\ny rondan las fieras de la selva;\nlos cachorros rugen por la presa,\nreclamando a Dios su comida.\n\nCuando brilla el sol, se retiran,\ny se tumban en sus guaridas;\nel hombre sale a sus faenas,\na su labranza hasta el atardecer.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"III","t":"Cuántas son tus obras, Señor,\ny todas las hiciste con sabiduría;\nla tierra está llena de tus criaturas.\n\nAhí está el mar: ancho y dilatado,\nen él bullen, sin número, \nanimales pequeños y grandes;\nlo surcan las naves, y el Leviatán\nque modelaste para que retoce.\n\nTodos ellos aguardan\na que les eches comida a su tiempo:\nse la echas, y la atrapan;\nabres tu mano, y se sacian de bienes;\n\nescondes tu rostro, y se espantan;\nles retiras el aliento, y expiran\ny vuelven a ser polvo;\nenvías tu aliento, y los creas,\ny repueblas la faz de la tierra.\n\nGloria a Dios para siempre,\ngoce el Señor con sus obras,\ncuando él mira la tierra, ella tiembla;\ncuando toca los montes, humean.\n\nCantaré al Señor mientras viva,\ntocaré para mi Dios mientras exista:\nque le sea agradable mi poema,\ny yo me alegraré con el Señor.\n\nQue se acaben los pecadores en la tierra,\nque los malvados no existan más.\n¡Bendice, alma mía, al Señor!\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"104":[{"r":"","t":"Dad gracias al Señor, invocad su nombre,\ndad a conocer sus hazañas a los pueblos.\nCantadle al son de instrumentos,\nhablad de sus maravillas,\ngloriaos de su nombre santo,\nque se alegren los que buscan al Señor.\n\nRecurrid al Señor y a su poder,\nbuscad contínuamente su rostro.\nRecordad las maravillas que hizo,\nsus prodigios, las sentencias de su boca.\n\n¡Estirpe de Abrahán, su siervo;\nhijos de Jacob, su elegido!\nEl Señor es nuestro Dios,\nÉl gobierna toda la tierra.\nSe acuerda de su alianza eternamente,\nde la palabra dada, por mil generaciones;\n\nde la alianza sellada con Abrahán,\ndel juramento hecho a Isaac,\nconfirmado como ley para Jacob,\ncomo alianza eterna para Israel:\n\"A ti te daré el país cananeo,\ncomo lote de vuestra heredad.\"\n\nCuando eran unos pocos mortales, \ncontados, y forasteros en el país,\ncuando erraban de pueblo en pueblo,\nde un reino a otra nación,\na nadie permitió que los molestase,\ny por ellos castigó a reyes:\n\"No toquéis a mis ungidos,\nno hagáis mal a mis profetas.\"\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Llamó al hambre sobre aquella tierra:\ncortando el sustento de pan;\npor delante había enviado a un hombre,\na José, vendido como esclavo;\n\nle trabaron los pies con grillos,\nle metieron el cuello en la argolla,\nhasta que se cumplió su predicción,\ny la palabra del Señor lo acreditó.\n\nEl rey lo mandó desatar,\nel Señor de pueblos le abrió la prisión,\nlo nombró administrador de su casa,\nseñor de todas sus posesiones,\npara que a su gusto instruyera a los príncipes\ny enseñase sabiduría a los ancianos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"III","t":"Entonces Israel entró en Egipto,\nJacob se hospedó en la tierra de Cam.\nDios hizo a su pueblo muy fecundo,\nmás poderoso que sus enemigos.\n\nA éstos les cambió el corazón\npara que odiasen a su pueblo,\ny usaran malas artes con sus siervos.\nPero envió a Moisés, su siervo,\ny a Aarón, su escogido,\nque hicieron contra ellos sus signos,\nprodigios en la tierra de Cam.\n\nEnvió la oscuridad, y oscureció,\npero ellos resistieron a sus palabras;\nconvirtió sus aguas en sangre,\ny dio muerte a sus peces;\nsu tierra pululaba de ranas,\nhasta en la alcoba del rey.\n\nOrdenó que vinieran tábanos \ny mosquitos por todo el territorio;\nles dio en vez de lluvia granizo,\nllamas de fuego por su tierra;\ne hirió higueras y viñas,\ntronchó los árboles del país.\n\nOrdenó que viniera la langosta,\nsaltamontes innumerables,\nque roían la hierba de su tierra,\ny devoraron los frutos de sus campos.\nHirió de muerte a los primogénitos del país,\nprimicias de su virilidad.\n\nSacó a su pueblo cargado de oro y plata,\nentre sus tribus nadie tropezaba;\nlos Egipcios se alegraban de su marcha,\nporque los había sobrecogido el terror.\n\nTendió una nube que los cubriese,\ny un fuego que los alumbrase de noche.\nLo pidieron, y envió codornices,\nlos sació con pan del cielo;\nhendió la peña, y brotaron las aguas,\nque corrieron en ríos por el desierto.\n\nPorque se acordaba de la palabra sagrada,\nque había dado a su siervo Abrahán,\nsacó a su pueblo con alegría,\na sus escogidos con gritos de triunfo.\n\nLes asignó las tierras de los gentiles,\ny poseyeron las haciendas de las naciones:\npara que guarden sus decretos,\ny cumplan su ley.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"105":[{"r":"","t":"Dad gracias al Señor porque es bueno,\nporque es eterna su misericordia.\n\n¿Quién podrá contar las hazañas de Dios,\npregonar toda su alabanza?\nDichosos los que respetan el derecho\ny practican siempre la justicia.\n\nAcuérdate de mí por amor a tu pueblo,\nvisítame con tu salvación:\npara que vea la dicha de tus escogidos,\ny me alegre con la alegría de tu pueblo,\ny me gloríe con tu heredad.\n\nHemos pecado con nuestros padres,\nhemos cometido maldades e iniquidades.\nNuestros padres en Egipto\nno comprendieron tus maravillas;\n\nno se acordaron de tu abundante misericordia,\nse rebelaron contra el Altísimo en el mar Rojo,\npero Dios los salvó por amor de su nombre,\npara manifestar su poder.\n\nIncrepó al mar Rojo, y se secó,\nlos condujo por el abismo como por tierra firme;\nlos salvó de la mano del adversario,\nlos rescató del puño del enemigo;\n\nlas aguas cubrieron a los atacantes,\ny ni uno sólo se salvó:\nentonces creyeron sus palabras,\ncantaron su alabanza.\n\nBien pronto olvidaron sus obras,\ny no se fiaron de sus planes:\nardían de avidez en el desierto\ny tentaron a Dios en la estepa.\nEl les concedió lo que pedían,\npero les mandó un cólico por su gula.\n\nEnvidiaron a Moisés en el campamento,\ny a Aarón, el consagrado al Señor:\nse abrió la tierra y se tragó a Datán,\nse cerró sobre Abirón y sus secuaces;\nun fuego abrasó a su banda,\nuna llama consumió a los malvados.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"En Horeb se hicieron un becerro,\nadoraron un ídolo de fundición;\ncambiaron su gloria por la imagen\nde un toro que come hierba.\n\nSe olvidaron de Dios, su salvador,\nque había hecho prodigios en Egipto,\nmaravillas en el país de Cam,\nportentos junto al mar Rojo.\n\nDios hablaba ya de aniquilarlos;\npero Moisés, su elegido,\nse puso en la brecha frente a El,\npara apartar su cólera del exterminio.\n\nDespreciaron una tierra envidiable,\nno creyeron en su palabra;\nmurmuraban en las tiendas,\nno escucharon la voz del Señor.\n\nEl alzó la mano y juró\nque los haría morir en el desierto,\nque dispersaría su estirpe por las naciones\ny los aventaría por los países.\n\nSe acoplaron con Baal Fegor,\ncomieron de los sacrificios a dioses muertos;\nprovocaron a Dios con sus perversiones,\ny los asaltó una plaga;\n\npero Finés se levantó e hizo justicia,\ny la plaga cesó;\ny se le apuntó a su favor \npor generación sin término.\n\nLo irritaron junto a las aguas de Meribá,\nMoisés tuvo que sufrir por culpa de ellos;\nle habían amargado el alma,\ny desvariaron sus labios.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"III","t":"No exterminaron a los pueblos\nque el Señor les había mandado;\nemparentaron con los gentiles,\nimitaron sus costumbres;\n\nadoraron sus ídolos\ny cayeron en sus lazos;\ninmolaron a los demonios\nsus hijos y sus hijas;\n\nderramaron la sangre inocente \ny profanaron la tierra ensangrentándola;\nse mancharon con sus acciones\ny se prostituyeron con sus maldades.\n\nLa ira del Señor se encendió contra su pueblo,\ny aborreció su heredad;\nlos entregó en manos de gentiles,\ny sus adversarios los sometieron;\nsus enemigos los tiranizaban\ny los doblegaron bajo su poder.\n\nCuántas veces los libró;\nmás ellos, obstinados en su actitud,\nperecían por sus culpas;\npero él miró su angustia,\ny escuchó sus gritos.\n\nRecordando su pacto con ellos,\nse arrepintió con inmensa misericordia;\nhizo que movieran a compasión\na los que habían deportado.\n\nSálvanos, Señor, Dios nuestro,\nreúnenos de entre los gentiles:\ndaremos gracias a tu santo nombre,\ny alabarte será nuestra gloria.\n\nBendito sea el Señor, Dios de Israel,\ndesde siempre y por siempre.\nY todo el pueblo diga:\n\"¡Amén!\"\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"106":[{"r":"","t":"Dad gracias al Señor porque es bueno,\nporque es eterna su misericordia.\n\nQue lo confiesen los redimidos por el Señor,\nlos que Él rescató de la mano del enemigo,\nlos que reunió de todos los países:\nnorte y sur, oriente y occidente.\n\nErraban por un desierto solitario,\nno encontraban el camino de ciudad habitada;\npasaban hambre y sed,\nse les iba agotando la vida;\npero gritaron al Señor en su angustia,\ny los arrancó de la tribulación.\n\nLos guió por un camino derecho,\npara que llegaran a una ciudad habitada.\nDad gracias al Señor por su misericordia,\npor las maravillas que hace con los hombres.\nCalmó el ansia de los sedientos,\ny a los hambrientos los colmó de bienes.\n\nYacían en oscuridad y tinieblas,\ncautivos de hierros y miserias;\npor haberse rebelado contra los mandamientos,\ndespreciando el plan del Altísimo.\nÉl humilló su corazón con trabajos,\nsucumbían y nadie los socorría.\nPero gritaron al Señor en su angustia,\ny los arrancó de la tribulación.\n\nLos sacó de las sombrías tinieblas,\narrancó sus cadenas.\nDad gracias al Señor por su misericordia,\npor las maravillas que hace con los hombres.\nDestrozó las puertas de bronce,\nquebró los cerrojos de hierro.\n\nEstaban enfermos por sus maldades,\npor sus culpas eran afligidos;\naborrecían todos los manjares,\ny ya tocaban las puertas de la muerte.\nPero gritaron al Señor en su angustia,\ny los arrancó de la tribulación.\n\nEnvió su palabra para curarlos,\npara salvarlos de la perdición.\nDad gracias al Señor por su misericordia,\npor las maravillas que hace con los hombres.\nOfrezcedle sacrificios de alabanza,\ny contad con entusiasmo sus acciones.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Entraron en naves por el mar,\ncomerciando por las aguas inmensas.\nContemplaron las obras de Dios,\nsus maravillas en el océano.\n\nÉl habló y levantó un viento tormentoso,\nque alzaba las olas a lo alto:\nsubían al cielo, bajaban al abismo,\nel estómago revuelto por el mareo,\nrodaban, se tambaleaban como borrachos,\ny no les valía su pericia.\nPero gritaron al Señor en su angustia,\ny los arrancó de la tribulación.\n\nApaciguó la tormenta en suave brisa,\ny enmudecieron las olas del mar.\nSe alegraron de aquella bonanza,\ny él los condujo al ansiado puerto.\nDen gracias al Señor por su misericordia,\npor las maravillas que hace con los hombres.\n\nAclámenlo en la asamblea del pueblo,\nalábenlo en el consejo de los ancianos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Él transforma los ríos en desierto,\nlos manantiales de agua en aridez;\nla tierra fértil en marismas,\npor la depravación de sus habitantes.\n\nTransforma el desierto en estanques,\nel erial en manantiales de agua.\nColoca allí a los hambrientos,\ny fundan una ciudad para habitar.\n\nSiembran campos, plantan huertos,\nrecogen cosechas.\nLos bendice, y se multiplican,\ny no les escatima el ganado.\n\nSi menguan, abatidos por el peso\nde infortunios y desgracias,\nel mismo que arroja desprecio sobre los príncipes\ny los descarría por una soledad sin caminos\nlevanta a los pobres de la miseria\ny multiplica sus familias como rebaños.\n\nLos rectos lo ven y se alegran,\na la maldad se le tapa la boca.\nEl que sea sabio, que recoja estos hechos\ny comprenda la misericordia del Señor.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"107":[{"r":"","t":"Dios mío, mi corazón está firme,\npara ti cantaré y tocaré, gloria mía.\nDespertad, cítara y arpa,\ndespertaré a la aurora.\n\nTe daré gracias ante los pueblos, Señor,\ntocaré para ti ante las naciones:\npor tu bondad, que es más grande que los cielos;\npor tu fidelidad, que alcanza a las nubes.\n\nElévate sobre el cielo, Dios mío,\ny llene la tierra tu gloria;\npara que se salven tus predilectos,\nque tu mano salvadora nos responda.\n\nDios habló en su santuario:\n«Triunfante, ocuparé Siquén,\nparcelaré el valle de Sucot;\n\nmío es Galaad, mío Manasés,\nEfraín es yelmo de mi cabeza,\nJudá es mi cetro;\n\nMoab, una jofaina para lavarme,\nsobre Edom echo mi sandalia,\nsobre Filistea canto victoria.»\n\nPero, ¿quién me guiará a la plaza fuerte,\nquién me conducirá a Edom,\nsi tú, oh Dios, nos has rechazado\ny no sales ya con nuestras tropas?\n\nAuxílianos contra el enemigo,\nque la ayuda del hombre es inútil;\ncon Dios haremos proezas,\nél pisoteará a nuestros enemigos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"109":[{"r":"1-5","t":"Oráculo del Señor a mi Señor:\n«Siéntate a mi derecha,\ny haré de tus enemigos\nestrado de tus pies.»\nDesde Sion extenderá el Señor\nel poder de tu cetro:\nsomete en la batalla a tus enemigos.\n\n«Eres príncipe desde el día de tu nacimiento,\nentre esplendores sagrados;\nyo mismo te engendré, como rocío,\nantes de la aurora.»\n\nEl Señor lo ha jurado y no se arrepiente:\n«Tú eres sacerdote eterno,\nsegún el rito de Melquisedec.»\n\nEl Señor a tu derecha, el día de su ira,\nquebrantará a los reyes.\nEn su camino beberá del torrente,\npor eso levantará la cabeza.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"110":[{"r":"","t":"Doy gracias al Señor de todo corazón,\nen compañía de los rectos, en la asamblea.\nGrandes son las obras del Señor,\ndignas de estudio para los que las aman.\n\nEsplendor y belleza son su obra,\nsu generosidad dura por siempre;\nha hecho maravillas memorables,\nel Señor es piadoso y clemente.\n\nÉl da alimento a sus fieles,\nrecordando siempre su alianza;\nmostró a su pueblo la fuerza de su obrar,\ndándoles la heredad de los gentiles.\n\nJusticia y verdad son las obras de sus manos,\ntodos sus preceptos merecen confianza:\nson estables para siempre jamás,\nse han de cumplir con verdad y rectitud.\n\nEnvió la redención a su pueblo,\nratificó para siempre su alianza,\nsu nombre es sagrado y temible.\n\nPrimicia de la sabiduría es el temor del Señor,\ntienen buen juicio los que lo practican;\nla alabanza del Señor dura por siempre.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"111":[{"r":"","t":"Dichoso quien teme al Señor\ny ama de corazón sus mandatos.\nSu linaje será poderoso en la tierra,\nla descendencia del justo será bendita.\n\nEn su casa habrá riquezas y abundancia,\nsu caridad es constante, sin falta.\nEn las tinieblas brilla como una luz\nel que es justo, clemente y compasivo.\n\nDichoso el que se apiada y presta,\ny administra rectamente sus asuntos.\nEl justo jamás vacilará,\nsu recuerdo será perpetuo.\n\nNo temerá las malas noticias,\nsu corazón está firme en el Señor.\nSu corazón está seguro, sin temor,\nhasta que vea derrotados a sus enemigos.\n\nReparte limosna a los pobres;\nsu caridad es constante, sin falta,\ny alzará la frente con dignidad.\n\nEl malvado, al verlo, se irritará,\nrechinará los dientes hasta consumirse.\nLa ambición del malvado fracasará.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"112":[{"r":"","t":"Alabad, siervos del Señor,\nalabad el nombre del Señor.\nBendito sea el nombre del Señor,\nahora y por siempre:\nde la salida del sol hasta su ocaso,\nalabado sea el nombre del Señor.\n\nEl Señor se eleva sobre todos los pueblos,\nsu gloria sobre los cielos.\n¿Quién como el Señor, Dios nuestro,\nque se eleva en su trono\ny se abaja para mirar\nal cielo y a la tierra?\n\nLevanta del polvo al desvalido,\nalza de la basura al pobre,\npara sentarlo con los príncipes,\nlos príncipes de su pueblo;\na la estéril le da un puesto en la casa,\ncomo madre feliz de hijos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"113":[{"r":"","t":"Cuando Israel salió de Egipto,\nlos hijos de Jacob de un pueblo balbuciente,\nJudá fue su santuario,\nIsrael fue su dominio.\n\nEl mar, al verlos, huyó,\nel Jordán se echó atrás;\nlos montes saltaron como carneros;\nlas colinas, como corderos.\n\n¿Qué te pasa, mar, que huyes,\ny a ti, Jordán, que te echas atrás?\n¿Y a vosotros, montes, que saltáis como carneros;\ncolinas, que saltáis como corderos?\n\nEn presencia del Señor se estremece la tierra,\nen presencia del Dios de Jacob;\nque transforma las peñas en estanques,\nel pedernal en manantiales de agua.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"No a nosotros, Señor, no a nosotros,\nsino a tu nombre da la gloria,\npor tu bondad, por tu lealtad.\n¿Por qué han de decir las naciones:\n\"Dónde está su Dios\"?\n\nNuestro Dios está en el cielo,\nlo que quiere lo hace.\nSus ídolos, en cambio, son plata y oro,\nhechura de manos humanas:\n\ntienen boca, y no hablan;\ntienen ojos, y no ven;\ntienen orejas, y no oyen;\ntienen nariz, y no huelen;\n\ntienen manos, y no tocan;\ntienen pies, y no andan;\nno tiene voz su garganta:\nque sean igual los que los hacen,\ncuantos confían en ellos.\n\nIsrael confía en el Señor:\nél es su auxilio y su escudo.\nLa casa de Aarón confía en el Señor:\nél es su auxilio y su escudo.\nLos fieles del Señor confían en el Señor:\nél es su auxilio y su escudo.\n\nQue el Señor se acuerde de nosotros y nos bendiga,\nbendiga a la casa de Israel,\nbendiga a la casa de Aarón;\nbendiga a los fieles del Señor,\npequeños y grandes.\n\nQue el Señor os acreciente,\na vosotros y a vuestros hijos;\nbenditos seáis del Señor,\nque hizo el cielo y la tierra.\nEl cielo pertenece al Señor,\nla tierra se la ha dado a los hombres.\n\nLos muertos ya no alaban al Señor,\nni los que bajan al silencio.\nNosotros, sí, bendeciremos al Señor\nahora y por siempre.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"114":[{"r":"","t":"Amo al Señor, porque escucha\nmi voz suplicante,\nporque inclina su oído hacia mí\nel día que lo invoco.\n\nMe envolvían redes de muerte,\nme alcanzaron los lazos del abismo,\ncaí en tristeza y angustia.\nInvoqué el nombre del Señor:\n«Señor, salva mi vida.»\n\nEl Señor es benigno y justo,\nnuestro Dios es compasivo;\nel Señor guarda a los sencillos:\nestando yo sin fuerzas, me salvó.\n\nAlma mía, recobra tu calma,\nque el Señor fue bueno contigo:\narrancó mi alma de la muerte,\nmis ojos de las lágrimas,\nmis pies de la caída.\n\nCaminaré en presencia del Señor\nen el país de la vida.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"115":[{"r":"","t":"Tenía fe, aun cuando dije:\n«¡Qué desgraciado soy!»\nYo decía en mi apuro:\n«Los hombres son unos mentirosos.»\n\n¿Cómo pagaré al Señor\ntodo el bien que me ha hecho?\nAlzaré la copa de la salvación,\ninvocando su nombre.\nCumpliré al Señor mis votos\nen presencia de todo el pueblo.\n\nMucho le cuesta al Señor\nla muerte de sus fieles.\nSeñor, yo soy tu siervo,\nsiervo tuyo, hijo de tu esclava:\nrompiste mis cadenas.\n\nTe ofreceré un sacrificio de alabanza,\ninvocando tu nombre, Señor.\nCumpliré al Señor mis votos\nen presencia de todo el pueblo,\nen el atrio de la casa del Señor,\nen medio de ti, Jerusalén.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"116":[{"r":"","t":"Alabad al Señor, todas las naciones,\naclamadlo, todos los pueblos.\n\nFirme es su misericordia con nosotros,\nsu fidelidad dura por siempre.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"117":[{"r":"","t":"Dad gracias al Señor porque es bueno,\nporque es eterna su misericordia.\n\nDiga la casa de Israel:\neterna es su misericordia.\n\nDiga la casa de Aarón:\neterna es su misericordia.\n\nDigan los fieles del Señor:\neterna es su misericordia.\n\nEn el peligro grité al Señor,\ny me escuchó, poniéndome a salvo.\n\nEl Señor está conmigo: no temo;\n¿qué podrá hacerme el hombre?\nEl Señor está conmigo y me auxilia,\nveré la derrota de mis adversarios.\n\nMejor es refugiarse en el Señor\nque fiarse de los hombres,\nmejor es refugiarse en el Señor\nque fiarse de los jefes.\n\nTodos los pueblos me rodeaban,\nen el nombre del Señor los rechacé;\nme rodeaban cerrando el cerco,\nen el nombre del Señor los rechacé;\nme rodeaban como avispas,\nardiendo como fuego en las zarzas,\nen el nombre del Señor los rechacé.\n\nEmpujaban y empujaban para derribarme,\npero el Señor me ayudó;\nel Señor es mi fuerza y mi energía,\nél es mi salvación.\n\nEscuchad: hay cantos de victoria\nen las tiendas de los justos:\n\"La diestra del Señor es poderosa,\nla diestra del Señor es excelsa,\nla diestra del Señor es poderosa.\"\n\nNo he de morir, viviré\npara contar las hazañas del Señor.\nMe castigó, me castigó el Señor,\npero no me entregó a la muerte.\n\nAbridme las puertas del triunfo,\ny entraré para dar gracias al Señor.\n\n-Ésta es la puerta del Señor:\nlos vencedores entrarán por ella.\n\n-Te doy gracias porque me escuchaste\ny fuiste mi salvación.\n\nLa piedra que desecharon los arquitectos\nes ahora la piedra angular.\nEs el Señor quien lo ha hecho,\nha sido un milagro patente.\n\nÉste es el día en que actuó el Señor:\nsea nuestra alegría y nuestro gozo.\nSeñor, danos la salvación;\nSeñor, danos prosperidad.\n\n-Bendito el que viene en nombre del Señor,\nos bendecimos desde la casa del Señor;\nel Señor es Dios, él nos ilumina.\n\n-Ordenad una procesión con ramos\nhasta los ángulos del altar.\n\nTú eres mi Dios, te doy gracias;\nDios mío, yo te ensalzo.\n\nDad gracias al Señor porque es bueno,\nporque es eterna su misericordia.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Dad gracias al Señor porque es bueno,\nporque es eterna su misericordia.\n\nDiga la casa de Israel:\neterna es su misericordia.\n\nDiga la casa de Aarón:\neterna es su misericordia.\n\nDigan los fieles del Señor:\neterna es su misericordia.\n\nEn el peligro grité al Señor,\ny me escuchó, poniéndome a salvo.\n\nEl Señor está conmigo: no temo;\n¿qué podrá hacerme el hombre?\nEl Señor está conmigo y me auxilia,\nveré la derrota de mis adversarios.\n\nMejor es refugiarse en el Señor\nque fiarse de los hombres,\nmejor es refugiarse en el Señor\nque fiarse de los jefes.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Todos los pueblos me rodeaban,\nen el nombre del Señor los rechacé;\nme rodeaban cerrando el cerco,\nen el nombre del Señor los rechacé;\nme rodeaban como avispas,\nardiendo como fuego en las zarzas,\nen el nombre del Señor los rechacé.\n\nEmpujaban y empujaban para derribarme,\npero el Señor me ayudó;\nel Señor es mi fuerza y mi energía,\nÉl es mi salvación.\n\nEscuchad: hay cantos de victoria\nen las tiendas de los justos:\n«La diestra del Señor es poderosa,\nla diestra del Señor es excelsa,\nla diestra del Señor es poderosa.»\n\nNo he de morir, viviré\npara contar las hazañas del Señor.\nMe castigó, me castigó el Señor,\npero no me entregó a la muerte.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"III","t":"Abridme las puertas del triunfo,\ny entraré para dar gracias al Señor.\n\n- Esta es la puerta del Señor:\nlos vencedores entrarán por ella.\n\n- Te doy gracias porque me escuchaste\ny fuiste mi salvación.\n\nLa piedra que desecharon los arquitectos\nes ahora la piedra angular.\nEs el Señor quien lo ha hecho,\nha sido un milagro patente.\n\nEste es el día en que actuó el Señor:\nsea nuestra alegría y nuestro gozo.\nSeñor, danos la salvación;\nSeñor, danos prosperidad.\n\n- Bendito el que viene en nombre del Señor,\nos bendecimos desde la casa del Señor;\nel Señor es Dios, él nos ilumina. \n\n- Ordenad una procesión con ramos\nhasta los ángulos del altar.\n\nTú eres mi Dios, te doy gracias;\nDios mío, yo te ensalzo.\n\nDad gracias al Señor porque es bueno,\nporque es eterna su misericordia.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"118":[{"r":"105-112","t":"Lámpara es tu palabra para mis pasos,\nluz en mi sendero;\nlo juro y lo cumpliré:\nguardaré tus justos mandamientos;\n¡estoy tan afligido!\nSeñor, dame vida según tu promesa.\n\nAcepta, Señor, los votos que pronuncio,\nenséñame tus mandatos;\nmi vida está siempre en peligro,\npero no olvido tu voluntad;\nlos malvados me tendieron un lazo,\npero no me desvié de tus decretos.\n\nTus preceptos son mi herencia perpetua,\nla alegría de mi corazón;\ninclino mi corazón a cumplir tus leyes,\nsiempre y cabalmente.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"113-120","t":"Detesto a los inconstantes\ny amo tu voluntad;\ntú eres mi refugio y mi escudo,\nyo espero en tu palabra;\napartaos de mí, los perversos,\ny cumpliré tus mandatos, Dios mío.\n\nSosténme con tu promesa, y viviré,\nque no quede frustrada mi esperanza;\ndame apoyo, y estaré a salvo,\nme fijaré en tus leyes sin cesar;\ndesprecias a los que se desvían de tus decretos,\nsus proyectos son engaño.\n\nTienes por escoria a los malvados,\npor eso amo tus preceptos;\nmi carne se estremece con tu temor,\ny respeto tus mandamientos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"145-152","t":"Te invoco de todo corazón:\nrespóndeme, Señor, y guardaré tus leyes;\na ti grito: sálvame,\ny cumpliré tus decretos;\nme adelanto a la aurora pidiendo auxilio,\nesperando tus palabras.\n\nMis ojos se adelantan a las vigilias,\nmeditando tu promesa;\nescucha mi voz por tu misericordia,\ncon tus mandamientos dame vida;\nya se acercan mis inicuos perseguidores,\nestán lejos de tu voluntad.\n\nTú, Señor, estás cerca,\ny todos tus mandatos son estables;\nhace tiempo comprendí que tus preceptos\nlos fundaste para siempre.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"121-128","t":"Practico la justicia y el derecho,\nno me entregues a mis opresores;\nda fianza en favor de tu siervo,\nque no me opriman los insolentes;\nmis ojos se consumen aguardando\ntu salvación y tu promesa de justicia.\n\nTrata con misericordia a tu siervo,\nenséñame tus leyes;\nyo soy tu siervo: dame inteligencia,\ny conoceré tus preceptos;\nes hora de que actúes, Señor:\nhan quebrantado tu voluntad.\n\nYo amo tus mandatos\nmás que el oro purísimo;\npor eso aprecio tus decretos\ny detesto el camino de la mentira.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"153-160","t":"Mira mi abatimiento y líbrame,\nporque no olvido tu voluntad;\ndefiende mi causa y rescátame,\ncon tu promesa dame vida;\nla justicia está lejos de los malvados\nque no buscan tus leyes.\n\nGrande es tu ternura, Señor,\ncon tus mandamientos dame vida;\nmuchos son los enemigos que me persiguen,\npero yo no me aparto de tus preceptos;\nviendo a los renegados, sentía asco,\nporque no guardan tus mandatos.\n\nMira como amo tus decretos,\nSeñor, por tu misericordia dame vida;\nel compendio de tu palabra es la verdad,\ny tus justos juicios son eternos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"161-168","t":"Los nobles me perseguían sin motivo,\npero mi corazón respetaba tus palabras;\nyo me alegraba con tu promesa,\ncomo el que encuentra un rico botín;\ndetesto y aborrezco la mentira,\ny amo tu voluntad.\n\nSiete veces al día te alabo\npor tus justos mandamientos;\nmucha paz tienen los que aman tus leyes,\ny nada los hace tropezar;\naguardo tu salvación, Señor,\ny cumplo tus mandatos.\n\nMi alma guarda tus preceptos\ny los ama intensamente;\nguardo tus decretos,\ny tú tienes presentes mis caminos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"169-176","t":"Que llegue mi clamor a tu presencia,\nSeñor, con tus palabras dame inteligencia;\nque mi súplica entre en tu presencia,\nlíbrame según tu promesa;\nde mis labios brota la alabanza,\nporque me enseñaste tus leyes.\n\nMi lengua canta tu fidelidad,\nporque todos tus preceptos son justos;\nque tu mano me auxilie,\nya que prefiero tus decretos;\nansío tu salvación, Señor;\ntu voluntad es mi delicia.\n\nQue mi alma viva para alabarte,\nque tus mandamientos me auxilien;\nme extravié como oveja perdida:\nbusca a tu siervo, que no olvida tus mandatos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"1-8","t":"Dichoso el que, con vida intachable,\ncamina en la voluntad del Señor;\ndichoso el que, guardando sus preceptos,\nlo busca de todo corazón;\nel que, sin cometer iniquidad,\nanda por sus senderos.\n\nTú promulgas tus decretos\npara que se observen exactamente.\nOjalá esté firme mi camino,\npara cumplir tus consignas;\nentonces no sentiré vergüenza\nal mirar tus mandatos.\n\nTe alabaré con sincero corazón\ncuando aprenda tus justos mandamientos.\nQuiero guardar tus leyes exactamente,\ntú, no me abandones.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"9-16","t":"¿Cómo podrá un joven andar honestamente?\nCumpliendo tus palabras.\nTe busco de todo corazón,\nno consientas que me desvíe de tus mandamientos.\nEn mi corazón escondo tus consignas,\nasí no pecaré contra ti.\n\nBendito eres, Señor,\nenséñame tus leyes.\nMis labios van enumerando\nlos mandamientos de tu boca;\nmi alegría es el camino de tus preceptos,\nmás que todas las riquezas.\n\nMedito tus decretos,\ny me fijo en tus sendas;\ntu voluntad es mi delicia,\nno olvidaré tus palabras.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"17-24","t":"Haz bien a tu siervo: viviré\ny cumpliré tus palabras;\nábreme los ojos, y contemplaré\nlas maravillas de tu voluntad;\nsoy un forastero en la tierra:\nno me ocultes tus promesas.\n\nMi alma se consume, deseando\ncontinuamente tus mandamientos;\nreprendes a los soberbios,\nmalditos los que se apartan de tus mandatos.\n\nAleja de mí las afrentas y el desprecio,\nporque observo tus preceptos;\naunque los nobles se sienten a murmurar de mí,\ntu siervo medita tus leyes;\ntus preceptos son mi delicia,\ntus decretos son mis consejeros.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"25-32","t":"Mi alma está pegada al polvo:\nreanímame con tus palabras;\nte expliqué mi camino, y me escuchaste:\nenséñame tus leyes;\ninstrúyeme en el camino de tus decretos,\ny meditaré tus maravillas.\n\nMi alma llora de tristeza,\nconsuélame con tus promesas;\napártame del camino falso,\ny dame la gracia de tu voluntad;\nescogí el camino verdadero,\ndeseé tus mandamientos.\n\nMe apegué a tus preceptos,\nSeñor, no me defraudes;\ncorreré por el camino de tus mandatos\ncuando me ensanches el corazón.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"33-40","t":"Muéstrame, Señor, el camino de tus leyes,\ny lo seguiré puntualmente;\nenséñame a cumplir tu voluntad\ny a guardarla de todo corazón;\nguíame por la senda de tus mandatos,\nporque ella es mi gozo.\n\nInclina mi corazón a tus preceptos,\ny no al interés;\naparta mis ojos de las vanidades,\ndame vida con tu palabra;\ncumple a tu siervo la promesa\nque hiciste a tus fieles.\n\nAparta de mí la afrenta que temo,\nporque tus mandamientos son amables;\nmira cómo ansío tus decretos:\ndame vida con tu justicia.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"41-48","t":"Señor, que me alcance tu favor,\ntu salvación según tu promesa:\nasí responderé a los que me injurian,\nque confío en tu palabra;\nno quites de mi boca las palabras sinceras,\nporque yo espero en tus mandamientos.\n\nCumpliré sin cesar tu voluntad,\npor siempre jamás;\nandaré por un camino ancho,\nbuscando tus decretos;\ncomentaré tus preceptos ante los reyes,\ny no me avergonzaré.\n\nSerán mi delicia tus mandatos,\nque tanto amo;\nlevantaré mis manos hacia ti\nrecitando tus mandatos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"57-64","t":"Mi porción es el Señor;\nhe resuelto guardar tus palabras;\nde todo corazón busco tu favor:\nten piedad de mí, según tu promesa;\nhe examinado mi camino,\npara enderezar mis pies a tus preceptos.\n\nCon diligencia, sin tardanza,\nobservo tus mandatos;\nlos lazos de los malvados me envuelven,\npero no olvido tu voluntad;\na media noche me levanto para darte gracias\npor tus justos mandamientos.\n\nMe junto con tus fieles,\nque guardan tus decretos;\nSeñor, de tu bondad está llena la tierra;\nenséñame tus leyes.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"65-72","t":"Has dado bienes a tu siervo,\nSeñor, con tus palabras;\nenséñame a gustar y a comprender,\nporque me fío de tus mandatos;\nantes de sufrir, yo andaba extraviado,\npero ahora me ajusto a tu promesa.\n\nTú eres bueno y haces el bien;\ninstrúyeme en tus leyes;\nlos insolentes urden engaños contra mí,\npero yo custodio tus leyes;\ntienen el corazón espeso como grasa,\npero mi delicia es tu voluntad.\n\nMe estuvo bien el sufrir,\nasí aprendí tus mandamientos;\nmás estimo yo los preceptos de tu boca\nque miles de monedas de oro y plata.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"73-80","t":"Tus manos me hicieron y me formaron:\ninstrúyeme para que aprenda tus mandatos;\ntus fieles verán con alegría\nque he esperado en tu palabra;\nreconozco, Señor, que tus mandamientos son justos,\nque con razón me hiciste sufrir.\n\nQue tu bondad me consuele,\nsegún la promesa hecha a tu siervo;\ncuando me alcance tu compasión, viviré,\ny mis delicias serán tu voluntad;\nque se avergüencen los insolentes\ndel daño que me hacen;\nyo meditaré tus decretos.\n\nVuelvan a mí tus fieles\nque hacen caso de tus preceptos;\nsea mi corazón perfecto en tus leyes,\nasí no quedaré avergonzado.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"81-88","t":"Me consumo ansiando tu salvación,\ny espero en tu palabra;\nmis ojos se consumen ansiando tus promesas,\nmientras digo: «¿Cuándo me consolarás?»\nEstoy como un odre puesto al humo,\npero no olvido tus leyes.\n\n¿Cuántos serán los días de tu siervo?\n¿Cuándo harás justicia de mis perseguidores?\nMe han cavado fosas los insolentes,\nignorando tu voluntad;\ntodos tus mandatos son leales,\nsin razón me persiguen, protégeme.\n\nCasi dieron conmigo en la tumba,\npero yo no abandoné tus decretos;\npor tu bondad dame vida,\npara que observe los preceptos de tu boca.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"89-96","t":"Tu palabra, Señor, es eterna,\nmás estable que el cielo;\ntu fidelidad de generación en generación,\nigual que fundaste la tierra y permanece;\npor tu mandamiento subsisten hasta hoy,\nporque todo está a tu servicio.\n\nSi tu voluntad no fuera mi delicia,\nya habría perecido en mi desgracia;\njamás olvidaré tus decretos,\npues con ellos me diste vida;\nsoy tuyo, sálvame,\nque yo consulto tus leyes.\n\nLos malvados me esperaban para perderme,\npero yo meditaba tus preceptos;\nhe visto el límite de todo lo perfecto:\ntu mandato se dilata sin término.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"97-104","t":"¡Cuánto amo tu voluntad!:\ntodo el día la estoy meditando;\ntu mandato me hace más sabio que mis enemigos,\nsiempre me acompaña;\nsoy más docto que todos mis maestros,\nporque medito tus preceptos.\n\nSoy más sagaz que los ancianos,\nporque cumplo tus leyes;\naparto mi pie de toda senda mala,\npara guardar tu palabra;\nno me aparto de tus mandamientos,\nporque tú me has instruido.\n\n¡Qué dulce al paladar tu promesa:\nmás que miel en la boca!\nConsidero tus decretos,\ny odio el camino de la mentira.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"137-144","t":"Señor, tú eres justo,\ntus mandamientos son rectos;\nhas prescrito leyes justas\nsumamente estables;\nme consume el celo,\nporque mis enemigos olvidan tus palabras.\n\nTu promesa es acrisolada,\ny tu siervo la ama;\nsoy pequeño y despreciable,\npero no olvido tus decretos;\ntu justicia es justicia eterna,\ntu voluntad es verdadera.\n\nMe asaltan angustias y aprietos,\ntus mandatos son mi delicia;\nla justicia de tus preceptos es eterna,\ndame inteligencia, y tendré vida.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"49-56","t":"Recuerda la palabra que diste a tu siervo,\nde la que hiciste mi esperanza;\neste es mi consuelo en la aflicción:\nque tu promesa me da vida;\nlos insolentes me insultan sin parar,\npero yo no me aparto de tus mandatos.\n\nRecordando tus antiguos mandamientos,\nSeñor, quedé consolado;\nsentí indignación ante los malvados,\nque abandonan tu voluntad;\ntus leyes eran mi canción\nen tierra extranjera.\n\nDe noche pronuncio tu nombre,\nSeñor, y, velando, tus preceptos;\nesto es lo que a mí me toca:\nguardar tus decretos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"129-136","t":"Tus preceptos son admirables,\npor eso los guarda mi alma;\nla explicación de tus palabras ilumina,\nda inteligencia a los ignorantes;\nabro la boca y respiro,\nansiando tus mandamientos.\n\nVuélvete a mí y ten misericordia,\ncomo es tu norma con los que aman tu nombre;\nasegura mis pasos con tu promesa,\nque ninguna maldad me domine;\nlíbrame de la opresión de los hombres,\ny guardaré tus decretos.\n\nHaz brillar tu rostro sobre tu siervo,\nenséñame tus leyes;\narroyos de lágrimas bajan de mis ojos\npor los que no cumplen tu voluntad.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"119":[{"r":"","t":"En mi aflicción llamé al Señor,\ny él me respondió.\nLíbrame, Señor, de los labios mentirosos,\nde la lengua traidora.\n\n¿Qué te va a dar o a mandarte Dios,\nlengua traidora?\nFlechas de arquero,\nafiladas con ascuas de retama.\n\n¡Ay de mí, desterrado en Masac,\nacampado en Cadar!\nDemasiado llevo viviendo\ncon los que odian la paz;\ncuando yo digo: «Paz»,\nellos dicen: «Guerra».\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"120":[{"r":"","t":"Levanto mis ojos a los montes:\n¿de dónde me vendrá el auxilio?\nEl auxilio me viene del Señor,\nque hizo el cielo y la tierra.\n\nNo permitirá que resbale tu pie,\ntu guardián no duerme;\nno duerme ni reposa\nel guardián de Israel.\n\nEl Señor te guarda a su sombra,\nestá a tu derecha;\nde día el sol no te hará daño,\nni la luna de noche.\n\nEl Señor te guarda de todo mal,\nél guarda tu alma;\nel Señor guarda tus entradas y salidas,\nahora y por siempre.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"121":[{"r":"","t":"¡Qué alegría cuando me dijeron:\n«Vamos a la casa del Señor»!\nYa están pisando nuestros pies\ntus umbrales, Jerusalén.\n\nJerusalén está fundada\ncomo ciudad bien compacta.\nAllá suben las tribus,\nlas tribus del Señor,\n\nsegún la costumbre de Israel,\na celebrar el nombre del Señor;\nen ella están los tribunales de justicia,\nen el palacio de David.\n\nDesead la paz a Jerusalén:\n«Vivan seguros los que te aman,\nhaya paz dentro de tus muros,\nseguridad en tus palacios.»\n\nPor mis hermanos y compañeros,\nvoy a decir: «La paz contigo.»\nPor la casa del Señor, nuestro Dios,\nte deseo todo bien.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"122":[{"r":"","t":"A ti levanto mis ojos,\na ti que habitas en el cielo.\n\nComo están los ojos de los esclavos\nfijos en las manos de sus señores,\ncomo están los ojos de la esclava\nfijos en las manos de su señora,\nasí están nuestros ojos\nen el Señor, Dios nuestro,\nesperando su misericordia.\n\nMisericordia, Señor, misericordia,\nque estamos saciados de desprecios;\nnuestra alma está saciada\ndel sarcasmo de los satisfechos,\ndel desprecio de los orgullosos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"123":[{"r":"","t":"Si el Señor no hubiera estado de nuestra parte\n-que lo diga Israel-,\nsi el Señor no hubiera estado de nuestra parte,\ncuando nos asaltaban los hombres,\nnos habrían tragado vivos:\ntanto ardía su ira contra nosotros.\n\nNos habrían arrollado las aguas,\nllegándonos el torrente hasta el cuello;\nnos habrían llegado hasta el cuello\nlas aguas espumantes.\n\nBendito el Señor, que no nos entregó\nen presa a sus dientes;\nhemos salvado la vida, como un pájaro\nde la trampa del cazador:\nla trampa se rompió, y escapamos.\n\nNuestro auxilio es el nombre del Señor,\nque hizo el cielo y la tierra.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"124":[{"r":"","t":"Los que confían en el Señor son como el monte Sion:\nno tiembla, está asentado para siempre.\n\nJerusalén está rodeada de montañas,\ny el Señor rodea a su pueblo\nahora y por siempre.\n\nNo pesará el cetro de los malvados\nsobre el lote de los justos,\nno sea que los justos extiendan\nsu mano a la maldad.\n\nSeñor, concede bienes a los buenos,\na los sinceros de corazón;\ny a los que se desvían por sendas tortuosas,\nque los rechace el Señor con los malhechores.\n¡Paz a Israel!\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"125":[{"r":"","t":"Cuando el Señor cambió la suerte de Sion,\nnos parecía soñar:\nla boca se nos llenaba de risas,\nla lengua de cantares.\n\nHasta los gentiles decían:\n«El Señor ha estado grande con ellos.»\nEl Señor ha estado grande con nosotros,\ny estamos alegres.\n\nQue el Señor cambie nuestra suerte,\ncomo los torrentes del Negueb.\nLos que sembraban con lágrimas\ncosechan entre cantares.\n\nAl ir, iba llorando,\nllevando la semilla;\nal volver, vuelve cantando,\ntrayendo sus gavillas.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"126":[{"r":"","t":"Si el Señor no construye la casa,\nen vano se cansan los albañiles;\nsi el Señor no guarda la ciudad,\nen vano vigilan los centinelas.\n\nEs inútil que madruguéis,\nque veléis hasta muy tarde,\nque comáis el pan de vuestros sudores:\n¡Dios lo da a sus amigos mientras duermen!\n\nLa herencia que da el Señor son los hijos;\nsu salario, el fruto del vientre:\nson saetas en manos de un guerrero\nlos hijos de la juventud.\n\nDichoso el hombre que llena\ncon ellas su aljaba:\nno quedará derrotado cuando litigue\ncon su adversario en la plaza.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"127":[{"r":"","t":"Dichoso el que teme al Señor\ny sigue sus caminos.\n\nComerás del fruto de tu trabajo,\nserás dichoso, te irá bien;\ntu mujer, como parra fecunda,\nen medio de tu casa;\n\ntus hijos, como renuevos de olivo,\nalrededor de tu mesa:\nésta es la bendición del hombre\nque teme al Señor.\n\nQue el Señor te bendiga desde Sion,\nque veas la prosperidad de Jerusalén\ntodos los días de tu vida;\nque veas a los hijos de tus hijos.\n¡Paz a Israel!\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"128":[{"r":"","t":"¡Cuánta guerra me han hecho desde mi juventud\n-que lo diga Israel-,\ncuánta guerra me han hecho desde mi juventud,\npero no pudieron conmigo!\n\nEn mis espaldas metieron el arado\ny alargaron los surcos.\nPero el Señor, que es justo,\nrompió las coyundas de los malvados.\n\nRetrocedan avergonzados,\nlos que odian a Sion;\nsean como la hierba del tejado,\nque se seca y nadie la siega;\n\nque no llena la mano del segador\nni la brazada del que agavilla;\nni le dicen los que pasan:\n\"Que el Señor te bendiga.\"\n\nOs bendecimos en el nombre del Señor.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"129":[{"r":"","t":"Desde lo hondo a ti grito, Señor;\nSeñor, escucha mi voz;\nestén tus oídos atentos\na la voz de mi súplica.\n\nSi llevas cuenta de los delitos, Señor,\n¿quién podrá resistir?\nPero de ti procede el perdón,\ny así infundes respeto.\n\nMi alma espera en el Señor,\nespera en su palabra;\nmi alma aguarda al Señor,\nmás que el centinela la aurora.\n\nAguarde Israel al Señor,\ncomo el centinela la aurora;\nporque del Señor viene la misericordia,\nla redención copiosa;\ny él redimirá a Israel\nde todos sus delitos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"130":[{"r":"","t":"Señor, mi corazón no es ambicioso,\nni mis ojos altaneros;\nno pretendo grandezas\nque superan mi capacidad;\nsino que acallo y modero mis deseos,\ncomo un niño en brazos de su madre.\n\nEspere Israel en el Señor\nahora y por siempre.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"131":[{"r":"","t":"Señor, tenle en cuenta a David\ntodos sus afanes:\ncómo juró al Señor\ne hizo voto al Fuerte de Jacob:\n\n\"No entraré bajo el techo de mi casa,\nno subiré al lecho de mi descanso,\nno daré sueño a mis ojos,\nni reposo a mis párpados,\nhasta que encuentre un lugar para el Señor,\nuna morada para el Fuerte de Jacob.\"\n\nOímos que estaba en Efrata,\nla encontramos en el Soto de Jaar:\nentremos en su morada,\npostrémonos ante el estrado de sus pies.\n\nLevántate, Señor, ven a tu mansión,\nven con el arca de tu poder:\nque tus sacerdotes se vistan de gala,\nque tus fieles vitoreen.\nPor amor a tu siervo David,\nno niegues audiencia a tu Ungido.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"El Señor ha jurado a David\nuna promesa que no retractará:\n\"A uno de tu linaje\npondré sobre tu trono.\n\nSi tus hijos guardan mi alianza\ny los mandatos que les enseño,\ntambién sus hijos, por siempre,\nse sentarán sobre tu trono.\"\n\nPorque el Señor ha elegido a Sion,\nha deseado vivir en ella:\n\"Ésta es mi mansión por siempre,\naquí viviré, porque la deseo.\n\nBendeciré sus provisiones,\na sus pobres los saciaré de pan,\nvestiré a sus sacerdotes de gala,\ny sus fieles aclamarán con vítores.\n\nHaré germinar el vigor de David,\nenciendo una lámpara para mi Ungido.\nA sus enemigos los vestiré de ignominia,\nsobre él brillará mi diadema\".\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"132":[{"r":"","t":"Ved qué dulzura, qué delicia,\nconvivir los hermanos unidos.\n\nEs ungüento precioso en la cabeza,\nque va bajando por la barba,\nque baja por la barba de Aarón,\nhasta la franja de su ornamento.\n\nEs rocío del Hermón, que va bajando\nsobre el monte Sion.\nPorque allí manda el Señor la bendición:\nla vida para siempre.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"133":[{"r":"","t":"Y ahora bendecid al Señor,\nlos siervos del Señor,\nlos que pasáis la noche\nen la casa del Señor.\n\nLevantad las manos hacia el santuario\ny bendecid al Señor.\n\nEl Señor te bendiga desde Sión,\nel que hizo cielo y tierra.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"134":[{"r":"","t":"Alabad el nombre del Señor,\nalabadlo, siervos del Señor,\nque estáis en la casa del Señor,\nen los atrios de la casa de nuestro Dios.\n\nAlabad al Señor porque es bueno,\ntañed para su nombre, que es amable.\nPorque él se escogió a Jacob,\na Israel en posesión suya.\n\nYo sé que el Señor es grande,\nnuestro dueño más que todos los dioses.\nEl Señor todo lo que quiere lo hace:\nen el cielo y en la tierra,\nen los mares y en los océanos.\n\nHace subir las nubes desde el horizonte,\ncon los relámpagos desata la lluvia,\nsuelta a los vientos de sus silos.\n\nÉl hirió a los primogénitos de Egipto,\ndesde los hombres hasta los animales.\nEnvió signos y prodigios\n-en medio de ti, Egipto-\ncontra el Faraón y sus ministros.\n\nHirió de muerte a pueblos numerosos,\nmató a reyes poderosos:\na Sijón, rey de los amorreos,\na Hog, rey de Basán,\ny a todos los reyes de Canaán.\nY dio su tierra en heredad,\nen heredad a Israel, su pueblo.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Señor, tu nombre es eterno;\nSeñor, tu recuerdo de edad en edad.\nPorque el Señor gobierna a su pueblo\ny se compadece de sus siervos.\n\nLos ídolos de los gentiles son oro y plata,\nhechura de manos humanas:\ntienen boca y no hablan,\ntienen ojos y no ven,\n\ntienen orejas y no oyen,\nno hay aliento en sus bocas.\nSean lo mismo los que los hacen,\ncuantos confían en ellos.\n\nCasa de Israel, bendice al Señor;\ncasa de Aarón, bendice al Señor;\ncasa de Leví, bendice al Señor;\nfieles del Señor, bendecid al Señor.\n\nBendito en Sion el Señor,\nque habita en Jerusalén.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"135":[{"r":"","t":"Dad gracias al Señor porque es bueno:\nporque es eterna su misericordia.\n\nDad gracias al Dios de los dioses:\nporque es eterna su misericordia.\n\nDad gracias al Señor de los señores:\nporque es eterna su misericordia.\n\nSólo él hizo grandes maravillas:\nporque es eterna su misericordia.\n\nÉl hizo sabiamente los cielos:\nporque es eterna su misericordia.\n\nÉl afianzó sobre las aguas la tierra:\nporque es eterna su misericordia.\n\nÉl hizo lumbreras gigantes:\nporque es eterna su misericordia.\n\nEl sol que gobierna el día:\nporque es eterna su misericordia.\n\nLa luna que gobierna la noche:\nporque es eterna su misericordia.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Él hirió a Egipto en sus primogénitos:\nporque es eterna su misericordia.\n\nY sacó a Israel de aquel país:\nporque es eterna su misericordia.\n\nCon mano poderosa, con brazo extendido:\nporque es eterna su misericordia.\n\nÉl dividió en dos partes el mar Rojo:\nporque es eterna su misericordia.\n\nY condujo por en medio a Israel:\nporque es eterna su misericordia.\n\nArrojó en el mar Rojo al faraón:\nporque es eterna su misericordia.\n\nGuió por el desierto a su pueblo:\nporque es eterna su misericordia.\n\nÉl hirió a reyes famosos:\nporque es eterna su misericordia.\n\nDio muerte a reyes poderosos:\nporque es eterna su misericordia.\n\nA Sijón, rey de los amorreos:\nporque es eterna su misericordia.\n\nY a Hog, rey de Basán:\nporque es eterna su misericordia.\n\nLes dio su tierra en heredad:\nporque es eterna su misericordia.\n\nEn heredad a Israel su siervo:\nporque es eterna su misericordia.\n\nEn nuestra humillación, se acordó de nosotros:\nporque es eterna su misericordia.\n\nY nos libró de nuestros opresores:\nporque es eterna su misericordia.\n\nÉl da alimento a todo viviente:\nporque es eterna su misericordia.\n\nDad gracias al Dios del cielo:\nporque es eterna su misericordia.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Él hirió a Egipto en sus primogénitos:\nporque es eterna su misericordia.\n\nY sacó a Israel de aquel país:\nporque es eterna su misericordia.\n\nCon mano poderosa, con brazo extendido:\nporque es eterna su misericordia.\n\nÉl dividió en dos partes el mar Rojo:\nporque es eterna su misericordia.\n\nY condujo por en medio a Israel:\nporque es eterna su misericordia.\n\nArrojó en el mar Rojo al Faraón:\nporque es eterna su misericordia.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"III","t":"Guió por el desierto a su pueblo:\nporque es eterna su misericordia.\n\nÉl hirió a reyes famosos:\nporque es eterna su misericordia.\n\nDio muerte a reyes poderosos:\nporque es eterna su misericordia.\n\nA Sijón, rey de los amorreos:\nporque es eterna su misericordia.\n\nY a Hog, rey de Basán:\nporque es eterna su misericordia.\n\nLes dio su tierra en heredad:\nporque es eterna su misericordia.\n\nEn heredad a Israel su siervo:\nporque es eterna su misericordia.\n\nEn nuestra humillación, se acordó de nosotros:\nporque es eterna su misericordia.\n\nY nos libró de nuestros opresores:\nporque es eterna su misericordia.\n\nÉl da alimento a todo viviente:\nporque es eterna su misericordia.\n\nDad gracias al Dios del cielo:\nporque es eterna su misericordia.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"136":[{"r":"","t":"Junto a los canales de Babilonia\nnos sentamos a llorar con nostalgia de Sion;\nen los sauces de sus orillas\ncolgábamos nuestras cítaras.\n\nAllí los que nos deportaron\nnos invitaban a cantar;\nnuestros opresores, a divertirlos:\n\"Cantadnos un cantar de Sion.\"\n\n¡Cómo cantar un cántico del Señor\nen tierra extranjera!\nSi me olvido de ti, Jerusalén,\nque se me paralice la mano derecha;\n\nque se me pegue la lengua al paladar\nsi no me acuerdo de ti,\nsi no pongo a Jerusalén\nen la cumbre de mis alegrías.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"137":[{"r":"","t":"Te doy gracias, Señor, de todo corazón;\ndelante de los ángeles tañeré para ti,\nme postraré hacia tu santuario,\ndaré gracias a tu nombre:\n\npor tu misericordia y tu lealtad,\nporque tu promesa supera a tu fama;\ncuando te invoqué, me escuchaste,\nacreciste el valor en mi alma.\n\nQue te den gracias, Señor, los reyes de la tierra,\nal escuchar el oráculo de tu boca;\ncanten los caminos del Señor,\nporque la gloria del Señor es grande.\n\nEl Señor es sublime, se fija en el humilde,\ny de lejos conoce al soberbio.\n\nCuando camino entre peligros,\nme conservas la vida;\nextiendes tu brazo contra la ira de mi enemigo,\ny tu derecha me salva.\n\nEl Señor completará sus favores conmigo:\nSeñor, tu misericordia es eterna,\nno abandones la obra de tus manos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"138":[{"r":"1-18","t":"Señor, tú me sondeas y me conoces;\nme conoces cuando me siento o me levanto,\nde lejos penetras mis pensamientos;\ndistingues mi camino y mi descanso,\ntodas mis sendas te son familiares.\n\nNo ha llegado la palabra a mi lengua,\ny ya, Señor, te la sabes toda.\nMe estrechas detrás y delante,\nme cubres con tu palma.\nTanto saber me sobrepasa,\nes sublime, y no lo abarco.\n\n¿Adónde iré lejos de tu aliento,\nadónde escaparé de tu mirada?\nSi escalo el cielo, allí estás tú;\nsi me acuesto en el abismo, allí te encuentro;\n\nsi vuelo hasta el margen de la aurora,\nsi emigro hasta el confín del mar,\nallí me alcanzará tu izquierda,\nme agarrará tu derecha.\n\nSi digo: \"Que al menos la tiniebla me encubra,\nque la luz se haga noche en torno a mí\",\nni la tiniebla es oscura para ti,\nla noche es clara como el día.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"139":[{"r":"2-9","t":"Líbrame, Señor, del malvado,\nguárdame del hombre violento:\nque planean maldades en su corazón\ny todo el día provocan contiendas;\nafilan sus lenguas como serpientes,\ncon veneno de víboras en los labios.\n\nDefiéndeme, Señor, de la mano perversa,\nguárdame de los hombres violentos,\nque preparan zancadillas a mis pasos.\nLos soberbios me esconden trampas;\nlos perversos me tienden una red\ny por el camino me colocan lazos.\n\nPero yo digo al Señor: «Tú eres mi Dios»;\nSeñor, atiende a mis gritos de socorro;\nSeñor Dios, mi fuerte salvador,\nque cubres mi cabeza el día de la batalla.\n\nSeñor, no le concedas sus deseos al malvado,\nno des éxito a sus proyectos.\n\nYo sé que el Señor hace justicia al afligido\ny defiende el derecho del pobre.\nLos justos alabarán tu nombre,\nlos honrados habitarán en tu presencia.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"140":[{"r":"1-9","t":"Señor, te estoy llamando, ven deprisa,\nescucha mi voz cuando te llamo.\nSuba mi oración como incienso en tu presencia,\nel alzar de mis manos como ofrenda de la tarde.\n\nColoca, Señor, una guardia en mi boca,\nun centinela a la puerta de mis labios;\nno dejes inclinarse mi corazón a la maldad,\na cometer crímenes y delitos;\nni que con los hombres malvados\nparticipe en banquetes.\n\nQue el justo me golpee, que el bueno me reprenda,\npero que el ungüento del impío no perfume mi cabeza;\nyo seguiré rezando en sus desgracias.\n\nSus jefes cayeron despeñados,\naunque escucharon mis palabras amables;\ncomo una piedra de molino, rota por tierra,\nestán esparcidos nuestros huesos a la boca de la tumba.\n\nSeñor, mis ojos están vueltos a ti,\nen ti me refugio, no me dejes indefenso;\nguárdame del lazo que me han tendido,\nde la trampa de los malhechores.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"141":[{"r":"","t":"A voz en grito clamo al Señor,\na voz en grito suplico al Señor;\ndesahogo ante él mis afanes,\nexpongo ante él mi angustia,\nmientras me va faltando el aliento.\n\nPero tú conoces mis senderos,\ny que en el camino por donde avanzo\nme han escondido una trampa.\n\nMira a la derecha, fíjate:\nnadie me hace caso;\nno tengo adónde huir,\nnadie mira por mi vida.\n\nA ti grito, Señor;\nte digo: «Tú eres mi refugio\ny mi lote en el país de la vida.»\n\nAtiende a mis clamores,\nque estoy agotado;\nlíbrame de mis perseguidores,\nque son más fuertes que yo.\n\nSácame de la prisión,\ny daré gracias a tu nombre:\nme rodearán los justos\ncuando me devuelvas tu favor.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"142":[{"r":"1-11","t":"Señor, escucha mi oración;\ntú, que eres fiel, atiende a mi súplica;\ntú, que eres justo, escúchame.\nNo llames a juicio a tu siervo,\npues ningún hombre vivo es inocente frente a ti.\n\nEl enemigo me persigue a muerte,\nempuja mi vida al sepulcro,\nme confina a las tinieblas\ncomo a los muertos ya olvidados.\nMi aliento desfallece,\nmi corazón dentro de mí está yerto.\n\nRecuerdo los tiempos antiguos,\nmedito todas tus acciones,\nconsidero las obras de tus manos\ny extiendo mis brazos hacia ti:\ntengo sed de ti como tierra reseca.\n\nEscúchame en seguida, Señor,\nque me falta el aliento.\nNo me escondas tu rostro,\nigual que a los que bajan a la fosa.\n\nEn la mañana hazme escuchar tu gracia,\nya que confío en ti.\nIndícame el camino que he de seguir,\npues levanto mi alma a ti.\n\nLíbrame del enemigo, Señor,\nque me refugio en ti.\nEnséñame a cumplir tu voluntad,\nya que tú eres mi Dios.\nTu espíritu, que es bueno,\nme guíe por tierra llana.\n\nPor tu nombre, Señor, consérvame vivo;\npor tu clemencia, sácame de la angustia.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"143":[{"r":"1-10","t":"Bendito el Señor, mi Roca,\nque adiestra mis manos para el combate,\nmis dedos para la pelea;\n\nmi bienhechor, mi alcázar,\nbaluarte donde me pongo a salvo,\nmi escudo y mi refugio,\nque me somete los pueblos.\n\nSeñor, ¿qué es el hombre para que te fijes en él?;\n¿qué los hijos de Adán para que pienses en ellos?\nEl hombre es igual que un soplo;\nsus días, una sombra que pasa.\n\nSeñor, inclina tu cielo y desciende;\ntoca los montes, y echarán humo;\nfulmina el rayo y dispérsalos;\ndispara tus saetas y desbarátalos.\n\nExtiende la mano desde arriba:\ndefiéndeme, líbrame de las aguas caudalosas,\nde la mano de los extranjeros,\ncuya boca dice falsedades,\ncuya diestra jura en falso.\n\nDios mío, te cantaré un cántico nuevo,\ntocaré para ti el arpa de diez cuerdas:\npara ti que das la victoria a los reyes,\ny salvas a David, tu siervo.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Bendito el Señor, mi Roca,\nque adiestra mis manos para el combate,\nmis dedos para la pelea;\n\nmi bienhechor, mi alcázar,\nbaluarte donde me pongo a salvo,\nmi escudo y mi refugio,\nque me somete los pueblos.\n\nSeñor, ¿qué es el hombre para que te fijes en él?;\n¿qué los hijos de Adán para que pienses en ellos?\nEl hombre es igual que un soplo;\nsus días, una sombra que pasa.\n\nSeñor, inclina tu cielo y desciende;\ntoca los montes, y echarán humo;\nfulmina el rayo y dispérsalos;\ndispara tus saetas y desbarátalos.\n\nExtiende la mano desde arriba:\ndefiéndeme, líbrame de las aguas caudalosas,\nde la mano de los extranjeros,\ncuya boca dice falsedades,\ncuya diestra jura en falso.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Dios mío, te cantaré un cántico nuevo,\ntocaré para ti el arpa de diez cuerdas:\npara ti que das la victoria a los reyes,\ny salvas a David, tu siervo.\n\nDefiéndeme de la espada cruel,\nsálvame de las manos de extranjeros,\ncuya boca dice falsedades, \ncuya diestra jura en falso.\n\nSean nuestros hijos un plantío,\ncrecidos desde su adolescencia; \nnuestras hijas sean columnas talladas,\nestructura de un templo.\n\nQue nuestros silos estén repletos \nde frutos de toda especie;\nque nuestros rebaños a millares\nse multipliquen en las praderas,\ny nuestros bueyes vengan cargados;\nque no haya brechas ni aberturas, \nni alarma en nuestras plazas.\n\nDichoso el pueblo que esto tiene, \ndichoso el pueblo cuyo Dios es el Señor.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"144":[{"r":"","t":"Te ensalzaré, Dios mío, mi rey;\nbendeciré tu nombre por siempre jamás.\n\nDía tras día, te bendeciré\ny alabaré tu nombre por siempre jamás.\n\nGrande es el Señor, merece toda alabanza,\nes incalculable su grandeza;\nuna generación pondera tus obras a la otra,\ny le cuenta tus hazañas.\n\nAlaban ellos la gloria de tu majestad,\ny yo repito tus maravillas;\nencarecen ellos tus temibles proezas,\ny yo narro tus grandes acciones;\ndifunden la memoria de tu inmensa bondad,\ny aclaman tus victorias.\n\nEl Señor es clemente y misericordioso,\nlento a la cólera y rico en piedad;\nel Señor es bueno con todos,\nes cariñoso con todas sus criaturas.\n\nQue todas tus criaturas te den gracias, Señor,\nque te bendigan tus fieles;\nque proclamen la gloria de tu reinado,\nque hablen de tus hazañas;\n\nexplicando tus hazañas a los hombres,\nla gloria y majestad de tu reinado.\nTu reinado es un reinado perpetuo,\ntu gobierno va de edad en edad.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"El Señor es fiel a sus palabras,\nbondadoso en todas sus acciones.\nEl Señor sostiene a los que van a caer,\nendereza a los que ya se doblan.\n\nLos ojos de todos te están aguardando,\ntú les das la comida a su tiempo;\nabres tú la mano,\ny sacias de favores a todo viviente.\n\nEl Señor es justo en todos sus caminos,\nes bondadoso en todas sus acciones;\ncerca está el Señor de los que lo invocan,\nde los que lo invocan sinceramente.\n\nSatisface los deseos de sus fieles,\nescucha sus gritos, y los salva.\nEl Señor guarda a los que lo aman,\npero destruye a los malvados.\n\nPronuncie mi boca la alabanza del Señor,\ntodo viviente bendiga su santo nombre\npor siempre jamás.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"","t":"Te ensalzaré, Dios mío, mi rey;\nbendeciré tu nombre por siempre jamás.\n\nDía tras día, te bendeciré\ny alabaré tu nombre por siempre jamás.\n\nGrande es el Señor, merece toda alabanza,\nes incalculable su grandeza;\nuna generación pondera tus obras a la otra,\ny le cuenta tus hazañas.\n\nAlaban ellos la gloria de tu majestad,\ny yo repito tus maravillas;\nencarecen ellos tus temibles proezas,\ny yo narro tus grandes acciones;\ndifunden la memoria de tu inmensa bondad,\ny aclaman tus victorias.\n\nEl Señor es clemente y misericordioso,\nlento a la cólera y rico en piedad;\nel Señor es bueno con todos,\nes cariñoso con todas sus criaturas.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."},{"r":"II","t":"Que todas tus criaturas te den gracias, Señor,\nque te bendigan tus fieles;\nque proclamen la gloria de tu reinado,\nque hablen de tus hazañas;\n\nexplicando tus hazañas a los hombres,\nla gloria y majestad de tu reinado.\nTu reinado es un reinado perpetuo,\ntu gobierno va de edad en edad.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"145":[{"r":"","t":"Alaba, alma mía, al Señor:\nalabaré al Señor mientras viva,\ntañeré para mi Dios mientras exista.\n\nNo confiéis en los príncipes,\nseres de polvo que no pueden salvar;\nexhalan el espíritu y vuelven al polvo,\nese día perecen sus planes.\n\nDichoso a quien auxilia el Dios de Jacob,\nel que espera en el Señor, su Dios,\nque hizo el cielo y la tierra,\nel mar y cuanto hay en él;\n\nque mantiene su fidelidad perpetuamente,\nque hace justicia a los oprimidos,\nque da pan a los hambrientos.\n\nEl Señor liberta a los cautivos,\nel Señor abre los ojos al ciego,\nel Señor endereza a los que ya se doblan,\nel Señor ama a los justos.\n\nEl Señor guarda a los peregrinos,\nsustenta al huérfano y a la viuda\ny trastorna el camino de los malvados.\n\nEl Señor reina eternamente,\ntu Dios, Sion, de edad en edad.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"146":[{"r":"","t":"Alabad al Señor, que la música es buena;\nnuestro Dios merece una alabanza armoniosa.\n\nEl Señor reconstruye Jerusalén,\nreúne a los deportados de Israel;\nél sana los corazones destrozados,\nvenda sus heridas.\n\nCuenta el número de las estrellas,\na cada una la llama por su nombre.\nNuestro Señor es grande y poderoso,\nsu sabiduría no tiene medida.\nEl Señor sostiene a los humildes,\nhumilla hasta el polvo a los malvados.\n\nEntonad la acción de gracias al Señor,\ntocad la cítara para nuestro Dios,\nque cubre el cielo de nubes,\npreparando la lluvia para la tierra;\n\nque hace brotar hierba en los montes,\npara los que sirven al hombre;\nque da su alimento al ganado\ny a las crías de cuervo que graznan.\n\nNo aprecia el vigor de los caballos,\nno estima los jarretes del hombre:\nel Señor aprecia a sus fieles,\nque confían en su misericordia.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"147":[{"r":"","t":"Glorifica al Señor, Jerusalén:\nalaba a tu Dios, Sion:\nque ha reforzado los cerrojos de tus puertas\ny ha bendecido a tus hijos dentro de ti;\nha puesto paz en tus fronteras,\nte sacia con flor de harina.\n\nÉl envía su mensaje a la tierra,\ny su palabra corre veloz;\nmanda la nieve como lana,\nesparce la escarcha como ceniza;\n\nhace caer el hielo como migajas\ny con el frío congela las aguas;\nenvía una orden, y se derriten;\nsopla su aliento, y corren.\n\nAnuncia su palabra a Jacob,\nsus decretos y mandatos a Israel;\ncon ninguna nación obró así,\nni les dio a conocer sus mandatos.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"148":[{"r":"","t":"Alabad al Señor en el cielo,\nalabad al Señor en lo alto.\n\nAlabadlo, todos sus ángeles;\nalabadlo, todos sus ejércitos.\n\nAlabadlo, sol y luna;\nalabadlo, estrellas lucientes.\n\nAlabadlo, espacios celestes\ny aguas que cuelgan en el cielo.\n\nAlaben el nombre del Señor,\nporque él lo mandó, y existieron.\n\nLes dio consistencia perpetua\ny una ley que no pasará.\n\nAlabad al Señor en la tierra,\ncetáceos y abismos del mar,\n\nrayos, granizo, nieve y bruma,\nviento huracanado que cumple sus órdenes,\n\nmontes y todas las sierras,\nárboles frutales y cedros,\n\nfieras y animales domésticos,\nreptiles y pájaros que vuelan.\n\nReyes y pueblos del orbe,\npríncipes y jefes del mundo,\n\nlos jóvenes y también las doncellas,\nlos viejos junto con los niños,\n\nalaben el nombre del Señor,\nel único nombre sublime.\n\nSu majestad sobre el cielo y la tierra;\nél acrece el vigor de su pueblo.\n\nAlabanza de todos sus fieles,\nde Israel, su pueblo escogido.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"149":[{"r":"","t":"Cantad al Señor un cántico nuevo,\nresuene su alabanza en la asamblea de los fieles;\nque se alegre Israel por su Creador,\nlos hijos de Sion por su Rey.\n\nAlabad su nombre con danzas,\ncantadle con tambores y cítaras;\nporque el Señor ama a su pueblo\ny adorna con la victoria a los humildes.\n\nQue los fieles festejen su gloria\ny canten jubilosos en filas:\ncon vítores a Dios en la boca\ny espadas de dos filos en las manos:\n\npara tomar venganza de los pueblos\ny aplicar el castigo a las naciones,\nsujetando a los reyes con argollas,\na los nobles con esposas de hierro.\n\nEjecutar la sentencia dictada\nes un honor para todos sus fieles.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}],"150":[{"r":"","t":"Alabad al Señor en su templo,\nalabadlo en su fuerte firmamento.\n\nAlabadlo por sus obras magníficas,\nalabadlo por su inmensa grandeza.\n\nAlabadlo tocando trompetas,\nalabadlo con arpas y cítaras,\n\nalabadlo con tambores y danzas,\nalabadlo con trompas y flautas,\n\nalabadlo con platillos sonoros,\nalabadlo con platillos vibrantes.\n\nTodo ser que alienta alabe al Señor.\n\nGloria al Padre, y al Hijo, y al Espíritu Santo.\nComo era en el principio, ahora y siempre,\npor los siglos de los siglos. Amén."}]};

  const KATHISMATA = [
    { n: 1,  rng: '1-8',     nom: 'I'   },
    { n: 2,  rng: '9-16',    nom: 'II'  },
    { n: 3,  rng: '17-23',   nom: 'III' },
    { n: 4,  rng: '24-31',   nom: 'IV'  },
    { n: 5,  rng: '32-36',   nom: 'V'   },
    { n: 6,  rng: '37-45',   nom: 'VI'  },
    { n: 7,  rng: '46-54',   nom: 'VII' },
    { n: 8,  rng: '55-63',   nom: 'VIII' },
    { n: 9,  rng: '64-69',   nom: 'IX'  },
    { n: 10, rng: '70-76',   nom: 'X'   },
    { n: 11, rng: '77-84',   nom: 'XI'  },
    { n: 12, rng: '85-90',   nom: 'XII' },
    { n: 13, rng: '91-100',  nom: 'XIII' },
    { n: 14, rng: '101-104', nom: 'XIV' },
    { n: 15, rng: '105-108', nom: 'XV'  },
    { n: 16, rng: '109-117', nom: 'XVI' },
    { n: 17, rng: '118',     nom: 'XVII' },
    { n: 18, rng: '119-133', nom: 'XVIII' },
    { n: 19, rng: '134-142', nom: 'XIX' },
    { n: 20, rng: '143-150', nom: 'XX'  }
  ];

  // Reparto semanal habitual (Typikon): Maitines 2 kathismata, Vísperas 1.
  const SEMANA = {
    0: { maitines: [2, 3] },                      // Domingo
    1: { maitines: [4, 5], visperas: [6] },       // Lunes
    2: { maitines: [7, 8], visperas: [9] },       // Martes
    3: { maitines: [10, 11], visperas: [12] },    // Miércoles
    4: { maitines: [13, 14], visperas: [15] },    // Jueves
    5: { maitines: [16, 17], visperas: [18] },    // Viernes
    6: { maitines: [19, 20] }                     // Sábado
  };

  function kathisma(n) { return KATHISMATA.find(k => k.n === n) || null; }
  function rango(n) {
    const k = kathisma(n);
    if (!k) return null;
    const [a, b] = k.rng.split('-').map(Number);
    const list = [];
    for (let i = a; i <= (b || a); i++) list.push({ lxx: i, mt: i });
    return list;
  }
  function psalmText(n) { return PSALMOS[n] || null; }

  return { PSALMOS, KATHISMATA, SEMANA, kathisma, rango, psalmText };
})();
if (typeof window !== 'undefined') window.Salterio = Salterio;
if (typeof module !== 'undefined' && module.exports) module.exports = { Salterio };
